import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b2-001","clusterId":"B","werkstueckRef":"B.17","stufe":1,"question":"Welche Antwort auf diese beiden Aussagen trifft den Kern, ohne das Gespräch ins Gegenteil kippen zu lassen?","options":["Der erste Satz ist richtig, denn das Verbot, Menschen als Besitz zu halten, gilt zeitlos, und für dieses Urteil über die Zeitgenossen braucht es kein Verstehen.","Der erste Satz ersetzt das Verstehen der damaligen Menschen durch ein heutiges Urteil, der zweite verbietet jedes Urteil. Beide Sätze sind verkürzt.","Der zweite Satz ist richtig, denn jedes Urteil über Menschen von vor 250 Jahren geht von heutigen Maßstäben aus und kann deshalb nicht belastbar sein.","Beide Sätze lassen sich nicht beurteilen, denn ohne gesicherte Quellen über die damaligen Menschen bleibt jede Aussage über sie bloße Meinung."],"correctIndex":1,"explanation":"Der erste Satz begeht den Fehler des Präsentismus: Er misst Menschen früherer Zeiten an Normen und Wissen von heute und hält das für das ganze Bild. Damit bleibt unverstanden, in welchem Weltbild, mit welchem Wissen und mit welchen Handlungsmöglichkeiten sie lebten. Die Gegenposition schießt übers Ziel hinaus: Wer Verstehen verlangt, muss deshalb nicht auf Bewertung verzichten. Das zeigt der Fall Thomas Jefferson: Den Kontext zu beachten entschuldigt die Sklaverei nicht, ihn zu ignorieren verhindert aber das Verständnis der Widersprüche, mit denen er rang. Jefferson nannte die Sklaverei in seinen „Notes on the State of Virginia“ selbst einen „unablässigen Despotismus“ und hielt zugleich die Unterlegenheit Schwarzer „nur als Verdacht“ für möglich. Falsch wird es erst, wenn Verurteilung oder Verklärung das Verständnis ersetzen. Gute Prüffrage: Versuche ich gerade, diese Person aus ihrer eigenen Realität heraus zu verstehen, oder benutze ich sie nur als Leinwand für heutige Urteile? Die anderen Antworten klingen vertretbar, scheitern aber: Dass manche Normen zeitlos gelten mögen, ersetzt das Verstehen nicht, und genau dieses überspringt der erste Satz. Dass ein Urteil heutige Maßstäbe nutzt, macht es nicht unbegründet; es darf nur den Kontext nicht ausblenden. Und die Quellenlage ist zwar wichtig, aber nicht das Thema der beiden Sätze.","coreRule":"⚡ Verstehen und Urteilen schließen sich nicht aus. Falsch wird es, wenn das Urteil das Verständnis ersetzt.","quote":"Versuche ich gerade, diese Epoche/Person aus ihrer eigenen, komplexen Realität heraus zu verstehen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.17 (Kernidee; Kipppunkt)","status":"entwurf","scenario":"In einer Diskussion über historische Figuren sagt jemand: „Wer vor 250 Jahren Menschen als Besitz gehalten hat, war eben ein Verbrecher, und alle damaligen Zeitgenossen gleich mit. Da gibt es nichts zu verstehen.“ Eine andere Person entgegnet: „Das ist unfair, man muss jede Zeit an ihren eigenen Maßstäben messen. Urteilen darf man über die Vergangenheit gar nicht.“","kurz":"Wer nur heutig urteilt, versteht die Menschen von damals nicht; wer jedes Urteil verbietet, verzichtet auf Bewertung, die neben dem Verstehen möglich bleibt. Der Kern liegt darin, dass Verstehen und Urteilen sich nicht ersetzen, sondern ergänzen.","prueffrage":"Gab es vor 250 Jahren schon Menschen, die Sklaverei öffentlich als Unrecht bezeichneten, und wie reagierte ihre Umgebung darauf?","rueckmeldung":[{"option":0,"text":"Manche Normen mögen tatsächlich zeitlos gelten, und das Urteil über die Sklaverei bleibt möglich. Daraus folgt aber nicht, dass es nichts zu verstehen gäbe: Wie die Menschen damals dachten und handelten, bleibt so unverstanden."},{"option":2,"text":"Jedes Urteil nutzt heutige Maßstäbe, das stimmt. Es ist deshalb aber nicht unbelastbar, es darf nur den Kontext nicht ausblenden. Der zweite Satz schießt übers Ziel hinaus, denn Verstehen verlangt keinen Verzicht auf Bewertung."},{"option":3,"text":"Die Quellenlage ist wichtig, darum geht es in den beiden Sätzen aber nicht. Sie streiten über das Verhältnis von Verstehen und Urteilen, und dazu liegen durchaus Quellen vor, etwa Jeffersons eigene Schriften."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, University of Virginia, Faksimile der Ausgaben 1784/1787)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, University of Virginia)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (American Historical Association)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"92f6b5c7859c5826"}},{"id":"qx-b2-002","clusterId":"B","werkstueckRef":"B.17","stufe":2,"question":"Welche Entgegnung prüft die Schwärmerei von der „guten alten Zeit“ in der Sache, ohne selbst die Vorfahren abzuwerten?","scenario":"Beim Abendessen schwärmt ein Freund nach einem Historienfilm, der um 1800 spielt: „Früher waren die Menschen naturverbundener, hatten stärkere Gemeinschaften und keinen Stress. Wir sollten wieder so leben.“","options":["Man stellt der Schwärmerei überprüfbare Lebensdaten gegenüber, etwa dass die Lebenserwartung um 1800 in keiner Weltregion über 40 Jahren lag, auch wegen früh sterbender Kinder.","Man fragt ihn, ob er für ein Leben wie im Film auch auf Zahnarzt, Heizung und Kühlschrank verzichten würde, und zeigt damit, dass seine Forderung nicht ernst gemeint sein kann.","Man erklärt die Schwärmerei mit der Nostalgie nach dem Historienfilm, die es in jeder Epoche gab, und folgert daraus, dass seine Aussagen über Natur und Gemeinschaft um 1800 falsch sind.","Man hält ihm vor, dass er mit seiner Sehnsucht nach 1800 Medizin und Komfort von heute geringschätzt, und verlangt von ihm mehr Dankbarkeit für das Leben, das er heute führen darf."],"correctIndex":0,"explanation":"Die Schwärmerei pickt Ästhetisches heraus (schöne Kleider, keine Smartphones) und blendet Hunger, Krankheiten, Kindersterblichkeit, erdrückende soziale Kontrolle und fehlende Rechte aus. Der stärkste Einwand setzt dort an, wo sich etwas überprüfen lässt: Lebensdaten sind Tatsachen, kein Werturteil, und sie stellen das idealisierte Bild auf die Probe. Gegen Verklärung hilft der Blick auf den ganzen Alltag der Epoche, ohne die Menschen von damals herabzusetzen. Die Frage nach Zahnarzt, Heizung und Kühlschrank wirkt wie ein anschaulicher Test, trifft aber die Person und nicht das Bild der Zeit. Dass Sehnsucht nach früher in jeder Epoche vorkommt, erklärt ihre Herkunft, aber nicht, ob das Bild von 1800 stimmt. Der Vorwurf der Undankbarkeit klingt nach Wertschätzung der Gegenwart, ersetzt aber die Prüfung durch einen Appell.","coreRule":"⚡ Gegen die Verklärung der Vergangenheit helfen überprüfbare Daten über den ganzen Alltag der Epoche, nicht ihre Verurteilung.","beleg":"Werkstück B.17, Abschnitt „Die zweite, subtilere Falle: Die naive Romantisierung“ und Abschnitt „Bei Esoterik & New Age“; Fn. gl-b-lebenserwartung (Dattani u. a. 2023, Our World in Data)","status":"entwurf","kurz":"Wer das Bild von 1800 an überprüfbaren Lebensdaten misst, prüft es in der Sache und lässt die Menschen von damals und den Freund in Ruhe. Der naheliegende Fehler wäre, ihn zu beschämen oder seine Sehnsucht zu erklären, statt das Bild zu testen.","prueffrage":"Welche Seiten des damaligen Lebens zeigt ein Historienfilm, und welche lässt er meistens weg?","rueckmeldung":[{"option":1,"text":"Der Test mit Zahnarzt, Heizung und Kühlschrank ist anschaulich und erinnert an Dinge, die damals fehlten. Er setzt aber an der Person an und zeigt sie als unernst, statt zu klären, ob das Bild von 1800 stimmt."},{"option":2,"text":"Dass es Sehnsucht nach früher in jeder Epoche gab, trifft zu und erklärt, woher seine Schwärmerei kommt. Ob seine Aussagen über Natur und Gemeinschaft um 1800 stimmen, folgt daraus nicht: Das entscheiden die Tatsachen, nicht die Herkunft."},{"option":3,"text":"Mehr Dankbarkeit zu fordern klingt nach Wertschätzung der Gegenwart. Es ist aber ein Appell an sein Gewissen und wertet ihn ab, ohne etwas am Bild von 1800 zu prüfen."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5f2abf3c28865015"}},{"id":"qx-b2-003","clusterId":"B","werkstueckRef":"B.17","stufe":3,"question":"Du hörst in einer Diskussion: „Thomas Jefferson hatte Sklaven – also war er ein monströser Heuchler.“ Jemand kontert: „Damals dachten eben alle so, also darf man ihn nicht verurteilen.“ Dann kommt der Hinweis, dass Jefferson die Sklaverei in einem eigenen Buch einen „unablässigen Despotismus“ nannte und schrieb, er zittere um sein Land, wenn er bedenke, dass Gott gerecht sei – im selben Buch äußerte er „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Was folgt daraus für das Argument „Damals dachten alle so“?","options":["Der Kontext verbietet jede Bewertung, weil Menschen einer fremden Epoche nur an den Maßstäben ihrer eigenen Zeit gemessen werden dürfen.","Der Kontext erklärt, aber entschuldigt nicht: Jefferson sah den Widerspruch selbst, und diesen zu verstehen bringt mehr als ein Etikett.","Der Kontext entlastet Jefferson weitgehend, weil Sklaverei damals als natürliche Ordnung galt und er sie nur kritisch kommentierte.","Der Kontext ist wertlos, weil es in jeder Zeit Menschen gab, die anders dachten als die Mehrheit, und an ihnen wird jede Figur gemessen."],"correctIndex":1,"explanation":"Beide Kurzschlüsse greifen zu kurz: weder „monströser Heuchler“ noch „Kind seiner Zeit, also unschuldig“. Dass alle gleich dachten, trifft nicht zu: Jefferson nannte die Sklaverei selbst einen „unablässigen Despotismus“, äußerte im selben Buch aber zugleich „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Den Widerspruch sah er also selbst. Das entschuldigt die Sklaverei nicht, aber es zu ignorieren, verhindert das Verständnis der tiefen Widersprüche, mit denen historische Akteure rangen.","coreRule":"⚡ Kontext ist eine Erklärung, kein Freispruch – und ohne ihn bleibt das Urteil blind.","beleg":"Werkstück B.17 (Anwendung: Bewertung historischer Figuren; Jefferson)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"4df819394debbbd9","vermerk":"Prüfpult"},"scenario":"","kurz":"Dass alle so dachten, stimmt hier nicht: Jefferson nannte die Sklaverei selbst „unablässigen Despotismus“ und äußerte zugleich den „Verdacht“, Schwarze seien unterlegen. Er sah den Widerspruch also selbst. Das entschuldigt nichts, erklärt aber mehr als ein Etikett.","prueffrage":"Was hat Jefferson selbst über die Sklaverei geschrieben, und deckt sich das mit der Behauptung, alle hätten damals gleich gedacht?","rueckmeldung":[{"option":0,"text":"Kontext gehört zum Verstehen einer Person tatsächlich dazu. Ein Bewertungsverbot folgt daraus aber nicht, zumal Jefferson die Sklaverei selbst „Despotismus“ nannte und sich so an seinen eigenen Maßstäben messen lassen muss."},{"option":2,"text":"Die Sklaverei war damals weit verbreitet, das stimmt. Dass sie allgemein als natürliche Ordnung galt, passt aber nicht zu Jeffersons eigenen Worten. Kritische Kommentare entlasten ihn auch nicht, sie zeigen eher, dass er den Widerspruch kannte."},{"option":3,"text":"Dass es auch damals Menschen gab, die anders dachten, trifft zu und widerlegt „alle dachten so“. Daraus folgt aber nicht, dass Kontext wertlos wäre. Er hilft zu verstehen, wie Einsicht und Handeln so weit auseinandergehen konnten."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4df819394debbbd9"}},{"id":"qx-b2-004","clusterId":"B","werkstueckRef":"B.17","stufe":4,"question":"Welche Rückfrage prüft die Behauptung am besten, ohne sie sofort zu verwerfen oder zu übernehmen?","scenario":"Ein Politiker beschwört „die guten alten 50er“ und nennt heutige gesellschaftliche Veränderungen „Verfall und Dekadenz“.","options":["Welche Ausbildung hat der Politiker, und versteht er genug von der Geschichte der 50er Jahre, um sie überhaupt beurteilen zu können?","Seit wann gelten Veränderungen in politischen Reden als „Verfall und Dekadenz“, und wie hat sich die Bedeutung dieser Wörter seit den 50er Jahren gewandelt?","Wie reagiert der Politiker, wenn man ihm Schattenseiten der 50er nennt, und bleibt er bei „Verfall und Dekadenz“, wenn man ihm Gegenbeispiele vorhält?","Wie sahen Alltag, Rechte und Gesundheit damals tatsächlich aus, und wozu wird dieses Bild heute gebraucht, etwa um Veränderungen als Verfall darzustellen?"],"correctIndex":3,"explanation":"Eine „goldene“ Vergangenheit ist oft ein idealisiertes Zerrbild: Man pickt die angenehmen Seiten heraus (schöne Kleider, keine Smartphones) und blendet den Rest aus, etwa hohe Kindersterblichkeit, fehlende Rechte oder soziale Kontrolle. Außerdem dient ein solches Bild häufig dazu, gegenwärtige Veränderungen, zum Beispiel mehr Rechte für Minderheiten, als Verfall darzustellen. Eine gute Prüfung fragt deshalb zweierlei: Wie sah der tatsächliche Alltag der Epoche aus, und welche Funktion hat das Bild in der heutigen Debatte? So wird die Behauptung weder pauschal abgetan noch übernommen.","coreRule":"⚡ Prüfe bei jeder „guten alten Zeit“, wie der Alltag damals tatsächlich aussah und wofür das Bild heute gebraucht wird.","beleg":"Werkstück B.17 (Anwendung: Verschwörungsmythen, rechts-konservative Variante; Red Flags)","status":"entwurf","kurz":"Ob die Rede stimmt, zeigt sich am tatsächlichen Alltag der Epoche mit Licht und Schatten und daran, wozu das Bild heute dient. So wird sie weder pauschal abgetan noch übernommen. Eine „goldene“ Zeit blendet oft Unangenehmes aus und rahmt Veränderungen als Verfall.","prueffrage":"Für wen waren die 50er „gut“, und wer hätte damals wohl ganz anders darüber gesprochen?","rueckmeldung":[{"option":0,"text":"Sachkenntnis ist grundsätzlich ein Hinweis auf Verlässlichkeit, klingt also nach einer guten Prüfung. Sie sagt aber nicht, ob sein Bild der 50er stimmt: Auch Kundige idealisieren, und Laien können recht haben. Geprüft wird die Aussage, nicht die Person."},{"option":1,"text":"Die Geschichte der Wörter „Verfall“ und „Dekadenz“ wirkt gründlich und erklärt, wie solche Begriffe gebraucht werden. Wie es in den 50ern tatsächlich zuging und wozu das Bild heute dient, bleibt dabei aber unbeantwortet."},{"option":2,"text":"Wie jemand auf Gegenbeispiele reagiert, ist aufschlussreich für sein Gesprächsverhalten. Es sagt aber nichts darüber, wie die 50er waren oder wozu das Bild heute eingesetzt wird; die Aussage selbst bleibt damit ungeprüft."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"27d06fa58afe9c22"}},{"id":"qx-b2-005","clusterId":"B","werkstueckRef":"B.18","stufe":1,"question":"Was ist an dieser Begründung für das Weitermachen fehlerhaft?","options":["Sie schließt aus dem bisherigen Ausbleiben eines Schadens auf Sicherheit und deutet das Schweigen der anderen als Zustimmung, obwohl es auch Selbstzensur sein kann.","Sie begeht den Fehlschluss versunkener Kosten: Sie hält am Weitermachen fest, weil schon viel Zeit und Geld in die Konstruktion geflossen sind, und scheut eine neue Bewertung der Warnzeichen.","Sie argumentiert im Kreis: Die Unbedenklichkeit der Konstruktion wird vorausgesetzt, um dann die Unbedenklichkeit der Konstruktion zu folgern, ganz ohne eigenen Grund.","Sie stellt eine falsche Alternative auf, als gäbe es für die Konstruktion nur Weitermachen oder Abbrechen, obwohl sich die Warnzeichen auch gezielt prüfen und beheben ließen."],"correctIndex":0,"explanation":"Zwei Schlüsse tragen hier nicht. Erstens: Dass dreimal nichts passiert ist, zeigt nicht, dass das Risiko klein ist. Ein Schaden, der bisher ausblieb, kann beim nächsten Mal eintreten. Genau so wurde bei der Challenger über Jahre der Dichtungsschaden als „annehmbares Risiko“ verbucht, weil Flug um Flug gut ging, bis der Start bei großer Kälte zur Katastrophe führte. Zweitens: Wer Bedenken ausdrücklich unerwünscht macht, darf Schweigen nicht als Zustimmung lesen. Ausbleibender Widerspruch kann auch Selbstzensur aus Angst vor Ausgrenzung sein. Hier wird aus einem individuellen Impuls („die anderen sehen es offenbar auch so“) über sozialen Druck ein Gruppendenken, bei dem Einigkeit wichtiger wird als eine gute Entscheidung. Der Gruppendruck erklärt solche Entscheidungen allerdings nur zum Teil; hinzu kommt die schleichende Normalisierung der Abweichung. Kritik gehört deshalb nicht unterdrückt, sondern gezielt eingeholt.","coreRule":"⚡ Wer „bisher ging es gut“ als Beweis nimmt und Schweigen als Zustimmung liest, übersieht Risiko und Selbstzensur.","beleg":"Werkstück B.18 (Kernidee; Analyse: Die drei Stufen; Abschnitt „Die Nacht erzählt allerdings nur das Ende“; Fn. gl-b-normalisierung)","status":"entwurf","scenario":"Ein Projektteam hat dreimal in Folge Warnzeichen für ein Qualitätsproblem bemerkt, jedes Mal ohne sichtbaren Schaden. In der Sitzung sagt die Leiterin: „Bisher ist immer alles gut gegangen, also verkraftet die Konstruktion das. Wenn jemand Bedenken hat, soll er sie bitte für sich behalten, wir sind uns doch alle einig.“","kurz":"Dreimal ohne Schaden zeigt nicht, dass das Risiko klein ist; der Schaden kann beim nächsten Mal kommen. Wo Bedenken unerwünscht sind, ist Schweigen zudem oft Selbstzensur und keine Zustimmung.","prueffrage":"Was ist aus den drei Warnzeichen geworden, und wer im Team hat in der Sitzung überhaupt etwas dazu gesagt?","rueckmeldung":[{"option":1,"text":"Am Weitermachen festzuhalten, obwohl Warnzeichen vorliegen, erinnert an versunkene Kosten. Davon ist im Szenario aber keine Rede: Die Leiterin beruft sich nicht auf bereits Investiertes, sondern darauf, dass bisher nichts passiert ist."},{"option":2,"text":"Ein Zirkelschluss setzt das zu Beweisende schon voraus. Die Leiterin nennt aber einen eigenen Grund, nämlich dass bisher alles gut gegangen ist. Er trägt nicht, ist jedoch etwas anderes als die Behauptung selbst."},{"option":3,"text":"Dass sich die Warnzeichen auch gezielt prüfen und beheben ließen, stimmt. Die Leiterin verengt die Wahl aber nicht auf Weitermachen oder Abbrechen; ihr Problem ist, dass sie die Warnzeichen gar nicht prüfen will."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196","abruf":"2026-10-12"},{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V „The Contributing Cause of the Accident“ (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Esser, J. K.; Lindoerfer, J. S. (1989): Groupthink and the space shuttle Challenger accident. Journal of Behavioral Decision Making 2(3)","oeffentlich":false,"doi":"10.1002/bdm.3960020304","seite":"S. 173"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bb6548138c8e7c00"}},{"id":"qx-b2-006","clusterId":"B","werkstueckRef":"B.18","stufe":2,"question":"Was ist an dieser Schlussfolgerung der Kollegin fehlerhaft?","scenario":"In der Teamsitzung stimmt dir eine Zahl nicht. Alle nicken, du schweigst – nicht weil du glaubst, die anderen wüssten es besser, sondern weil du nicht als Spielverderber dastehen willst. Später sagt dir eine Kollegin: „Du hast das ja einfach mitgetragen, also warst du überzeugt.“","options":["Sie hält dein Schweigen für Zustimmung, obwohl es auch aus Furcht vor sozialer Ablehnung entstehen kann und dann nichts über deine Überzeugung sagt.","Sie schließt aus dem Nicken der anderen im Team, dass die Zahl stimmt, obwohl die Zahl der Zustimmenden nichts darüber aussagt, ob die Zahl wahr ist.","Sie schließt aus deinem Schweigen in dieser einen Sitzung auf dein Verhalten in allen Teams, obwohl ein einzelner Vorfall dafür nicht ausreicht.","Sie kehrt die Beweislast um, als müsstest du die Zahl widerlegen, obwohl fehlender Widerspruch eine Zahl nicht belegt und derjenige sie belegen muss, der sie nennt."],"correctIndex":0,"explanation":"Äußeres Verhalten und innere Überzeugung fallen nicht zusammen. Es gibt zwei Gründe, sich einer Gruppe anzuschließen: Man hält die anderen für wissender (informativer Einfluss), oder man fürchtet Ausgrenzung, Lächerlichkeit oder Bestrafung (normativer Einfluss). Dein Schweigen entspringt dem zweiten Grund, und dann sagt das Nicken der Gruppe nichts darüber, was die Einzelnen wirklich denken. Genau so entsteht in eng verbundenen Gruppen die Illusion der Einstimmigkeit: Schweigen wird fälschlich als Zustimmung gedeutet, während Einzelne ihre Zweifel zurückhalten (Selbstzensur). In Asch-Experimenten gaben rund drei Viertel der Versuchspersonen mindestens einmal öffentlich eine offensichtlich falsche Antwort, nur weil alle anderen es taten. Wer Einigkeit nur an äußerer Zustimmung misst, kann sich täuschen. Die anderen Deutungen nennen bekannte Denkfehler, passen aber nicht: Die Kollegin schließt nicht auf die Richtigkeit der Zahl, sondern auf deine Überzeugung. Sie verallgemeinert auch nicht auf andere Teams, sondern bezieht sich auf diese Sitzung. Und eine Beweislast für die Zahl mag bei dem liegen, der sie nennt, aber die Kollegin spricht nicht über die Zahl, sondern über dein Schweigen. Eine gute Frage wäre: „Welche Argumente haben wir noch nicht gehört oder trauen uns nicht auszusprechen?“","coreRule":"⚡ Schweigen ist kein Beleg für Zustimmung: Es kann auch aus Angst vor dem Gruppenurteil entstehen.","beleg":"Werkstück B.18 (Stufe 2; Symptom 6 Selbstzensur)","status":"entwurf","kurz":"Schweigen ist nicht gleich Zustimmung: Man kann sich anschließen, weil man Ausgrenzung scheut, und dann sagt das Mitgetragene nichts über die eigene Überzeugung. Genau so entsteht der Anschein von Einigkeit in einer Gruppe.","prueffrage":"Wie viele der Nickenden hatten vielleicht eigene Bedenken, und woran hätte die Kollegin das von außen erkennen können?","rueckmeldung":[{"option":1,"text":"Dass Zustimmung der Menge eine Zahl nicht wahr macht, stimmt. Die Kollegin behauptet aber gar nichts über die Zahl, sondern über deine Überzeugung. Ihr Fehler liegt darin, was sie aus deinem Mitgehen folgert."},{"option":2,"text":"Aus einem Einzelfall auf alles zu schließen, wäre tatsächlich ein Fehler. Die Kollegin redet aber nur über diese eine Sitzung und behauptet nichts über andere Teams. Ihr Schluss geht an anderer Stelle schief."},{"option":3,"text":"Fehlender Widerspruch belegt eine Zahl nicht, und belegen muss sie, wer sie nennt. Darum geht es der Kollegin aber nicht: Sie äußert sich nicht zur Zahl, sondern zu dem, was dein Schweigen über dich verraten soll."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Spielman, R. M.; Jenkins, W. J.; Lovett, M. D.: Psychology 2e, Kap. 12.4 „Conformity, Compliance, and Obedience“ (OpenStax)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/12-4-conformity-compliance-and-obedience","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9)","oeffentlich":false,"doi":"10.1037/h0093718","seite":"S. 10–11"},{"typ":"doi","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3)","oeffentlich":false,"doi":"10.1037/h0046408","seite":"S. 629–633"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f2cd8bc166b5f885"}},{"id":"qx-b2-007","clusterId":"B","werkstueckRef":"B.18","stufe":3,"question":"Ein Kommentator sagt: „Der Gruppendruck in der Nacht davor erklärt alles.“ Welche Einschätzung dieser Erklärung passt am besten zur Schilderung?","options":["Sie greift zu kurz: Schon bei früheren Flügen waren Dichtringe angegriffen; weil diese Flüge gut gingen, galt der Schaden als annehmbar.","Sie trifft im Kern zu: Das Management überging am Vorabend die Warnung der eigenen Ingenieure, und darin liegt die eigentliche Ursache.","Sie trifft im Kern zu: Die oberste Startleitung kannte die Einwände der Ingenieure und gab den Start in jener Nacht trotzdem frei.","Sie greift zu kurz: Ursache war allein die Kälte; die Dichtungen hätten versagt, gleich welche Entscheidung in jener Nacht gefallen wäre."],"correctIndex":0,"explanation":"Eine einzelne dramatische Szene ist eine verlockende Ursache, aber selten die ganze. Hier hatten die Ingenieure dringend abgeraten, ihr Management revidierte die Warnung, und die oberste Startleitung erfuhr nach eigener Aussage nichts davon. Dahinter steht eine längere Vorgeschichte: Schon seit den ersten Flügen waren Dichtringe immer wieder angegriffen worden, ein Jahr zuvor nach Kältenächten besonders stark. Weil die Flüge trotzdem gut gingen, galt jeder neue Schaden als Beweis, dass die Konstruktion ihn verkraftet. Dieses Muster wird „Normalisierung der Abweichung“ genannt; die Untersuchung nach dem Absturz der Columbia 2003 fand es auch beim Isolierschaum wieder. Eine gute Ursachenanalyse fragt deshalb nicht nur, wer in der entscheidenden Nacht was sagte, sondern auch, welche Gewöhnung diese Entscheidung über Jahre vorbereitet hat. Dass das Management die Warnung überging, gehört zur Ursache, erklärt aber nicht, warum angegriffene Dichtringe überhaupt als annehmbar galten. Die oberste Startleitung sagte aus, von den Einwänden nichts gewusst zu haben; ein bewusstes Überstimmen durch sie gibt die Schilderung nicht her. Und „allein die Kälte“ übersieht, dass gerade wegen der Kälte abgeraten wurde: Ein Verzicht auf den Start hätte das Unglück verhindert.","coreRule":"⚡ Wer ein Unglück mit der letzten Entscheidung erklärt, übersieht oft die Gewöhnung an Warnzeichen, die Jahre vorher begann.","beleg":"Werkstück B.18; Fn. gl-b-challenger (Rogers Commission 1986, Bd. 1, Kap. V; Vaughan 1996); Fn. gl-b-normalisierung (CAIB 2003, Bd. 1, Kap. 8, S. 196–197)","status":"entwurf","scenario":"Vor einem Raumfähren-Start bei Kälte rieten Ingenieure des Herstellers der Feststoffraketen dringend ab: Die Dichtungen waren bei Kälte nicht für einen sicheren Start zertifiziert. Ihr Management gab am Vorabend dennoch die Freigabe, und die oberste Startleitung sagte später aus, von den Einwänden nichts gewusst zu haben. Schon bei früheren Flügen waren Dichtringe angegriffen worden, doch weil die Flüge gut gegangen waren, wurde der Schaden als „annehmbares Risiko“ geführt. Der Start endete in der Katastrophe.","kurz":"Die Entscheidung der Nacht ist nur das letzte Glied. Dichtringe waren schon bei früheren Flügen angegriffen worden, und weil diese Flüge gut gingen, galt jeder neue Schaden als annehmbar. Diese Gewöhnung bereitete die Freigabe über Jahre vor.","prueffrage":"Seit wann waren Dichtringe angegriffen, und wie wurde damit bei den Flügen davor umgegangen?","rueckmeldung":[{"option":1,"text":"Dass das Management die Warnung überging, gehört tatsächlich zur Ursache. Es erklärt aber nicht, warum angegriffene Dichtringe überhaupt als annehmbar galten; dafür muss man auf die Jahre davor schauen."},{"option":2,"text":"Die Freigabe fiel in jener Nacht, das stimmt. Nach eigener Aussage erfuhr die oberste Startleitung von den Einwänden aber nichts; ein bewusstes Überstimmen durch sie steht in der Schilderung nicht."},{"option":3,"text":"Die Kälte spielte eine große Rolle, und genau ihretwegen rieten die Ingenieure ab. Hätte man auf sie gehört und auf den Start verzichtet, wäre das Unglück ausgeblieben, daher war nicht die Kälte allein entscheidend."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196–197","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Vaughan, D. (1996): The Challenger Launch Decision. Chicago: University of Chicago Press","oeffentlich":false}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3ee4d6f53abfc496"}},{"id":"qx-b2-008","clusterId":"B","werkstueckRef":"B.18","stufe":4,"question":"Was ist an der Schlussfolgerung der Vorsitzenden am ehesten fragwürdig?","scenario":"Ein Vorstand will Gruppendenken vermeiden. In jeder Sitzung muss reihum ein Mitglied die Rolle des „Advocatus Diaboli“ spielen und gegen den Beschlussvorschlag argumentieren. Nach einem halben Jahr fällt auf: Die Beschlüsse fallen weiterhin sehr schnell und fast immer einstimmig. Der Teufelsanwalt bringt regelmäßig Einwände vor, die nach kurzer Diskussion allen als „bekannt“ gelten. Die Vorsitzende deutet das als Beweis, dass die Gruppe gründlich prüft.","options":["Fragwürdig ist nur die Häufigkeit: Gäbe es zu jedem Tagesordnungspunkt einen Teufelsanwalt, wären auch die schnellen Beschlüsse gründlich geprüft.","Fragwürdig ist die Einstimmigkeit: Fällt ein halbes Jahr lang fast alles einstimmig, beweist das schon für sich, dass nachlässig geprüft wird.","Fragwürdig ist der Beleg: Einwände, die reihum aus Pflicht kommen und rasch als „bekannt“ gelten, zeigen noch keinen echten Widerspruch an.","Fragwürdig ist nur die Besetzung: Läge die Rolle dauerhaft bei einem erfahrenen Mitglied, würden seine Einwände ernster genommen und geprüft."],"correctIndex":2,"explanation":"Ein Einwand, den jemand pflichtgemäß vorbringt, weil er an der Reihe ist, zeigt noch nicht, dass die Gruppe Widerspruch ernst nimmt. Das Ritual kann den Eindruck gründlicher Prüfung erwecken, ohne dass echter Widerspruch stattfindet. Dass hier jeder Einwand schnell als „bekannt“ gilt und die Beschlüsse einstimmig bleiben, ist eher ein Warnsignal. Echter, selbst geäußerter Widerspruch ist dagegen nicht an eine Rolle gebunden und wird eher als ernsthafte Alternative geprüft. Laut Experimenten war von sich aus geäußerter Widerspruch jeder geprüften Form des bestellten Teufelsanwalts überlegen. Das heißt nicht, dass die Rolle wertlos wäre, wohl aber, dass sie echten Widerspruch nicht ersetzt. Mehr bestellte Teufelsanwälte vervielfachen nur dasselbe Ritual, und auch ein erfahrenes Mitglied in einer Dauerrolle widerspräche aus einer zugewiesenen Rolle statt aus eigener Überzeugung. Einstimmigkeit allein beweist weder Sorgfalt noch Nachlässigkeit; entscheidend ist, ob abweichende Meinungen real geäußert und ernsthaft geprüft werden können.","coreRule":"⚡ Ein bestellter Widerspruch ersetzt nicht die Kultur, in der echter Widerspruch erwünscht ist.","beleg":"Werkstück B.18 (Verbindungen: Advocatus Diaboli)","status":"entwurf","kurz":"Pflichteinwände, die reihum kommen und rasch als „bekannt“ gelten, zeigen noch keinen echten Widerspruch. Der naheliegende Fehler: Ein Ritual für Prüfung zu halten, obwohl es nur den Anschein gründlicher Prüfung erzeugen kann.","prueffrage":"Hat schon einmal ein Einwand einen Beschluss verändert oder verzögert, und von wem kam er?","rueckmeldung":[{"option":0,"text":"Mehr Teufelsanwälte brächten mehr Einwände, aber aus derselben Pflicht heraus. Solange jeder Einwand schnell als „bekannt“ abgehakt wird, vervielfacht sich nur das Ritual, nicht die Prüfung."},{"option":1,"text":"Dass fast alles einstimmig fällt, ist ein Warnsignal, aber noch kein Beweis. Auch bei Einstimmigkeit kann gründlich geprüft worden sein; entscheidend ist, ob abweichende Meinungen real geäußert und ernst genommen werden können."},{"option":3,"text":"Ein erfahrenes Mitglied in einer Dauerrolle wirkt glaubwürdiger, widerspräche aber weiterhin aus einer zugewiesenen Rolle statt aus eigener Überzeugung. An der Pflicht als Quelle des Einwands ändert Erfahrung nichts."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Nemeth, C.; Brown, K.; Rogers, J. (2001): Devil's advocate versus authentic dissent: stimulating quantity and quality. European Journal of Social Psychology 31(6), 707–720","oeffentlich":false,"doi":"10.1002/ejsp.58","seite":"S. 707, 713–717"},{"typ":"url","kurz":"Behavioral Scientist (2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7db93f1fb88bc965"}},{"id":"qx-b2-009","clusterId":"B","werkstueckRef":"B.19","stufe":2,"question":"Welche Frage prüft die Werbebehauptung am besten?","scenario":"Eine Broschüre für ein Nahrungsergänzungsmittel wirbt: „Studie belegt – zwei Gesundheitswerte verbessert!“ Im Kleingedruckten steht, dass die Studie insgesamt 50 verschiedene Gesundheitswerte erfasst hat. Über die übrigen 48 Werte schweigt die Broschüre.","options":["Wurde vor der Studie festgelegt, welche Werte als Erfolgskriterium gelten sollten, und wie sahen die übrigen gemessenen Werte aus?","Wurde die Studie mit den zwei verbesserten Werten in einer Fachzeitschrift veröffentlicht, und wie oft haben andere Forschende sie seither zitiert?","Wie lange dauerte die Studie mit den 50 Werten, und hielten die zwei verbesserten Werte auch an, nachdem die Teilnehmer das Mittel abgesetzt hatten?","Wer hat die Studie zu diesem Mittel bezahlt, und stand der Geldgeber in einer geschäftlichen Beziehung zum Hersteller, der die Broschüre verteilt?"],"correctIndex":0,"explanation":"Wer 50 Werte misst, bekommt allein durch Zufall bei einigen davon eine scheinbar „signifikante“ Veränderung, ganz ohne jede Wirkung des Mittels. Entscheidend ist deshalb, ob die zwei Werte schon vor der Messung als Ziel festgelegt waren oder ob man sie erst im Nachhinein aus den Ergebnissen herausgepickt hat. Das ist, als würde man erst auf die Scheunenwand schießen und dann die Zielscheibe um die dichtesten Einschusslöcher malen. Und nur wenn man die übrigen 48 Werte kennt, lässt sich einschätzen, ob die zwei Treffer ein Volltreffer oder ein Zufallscluster sind. Dass die Studie in einer Fachzeitschrift erschien und oft zitiert wurde, klingt nach Qualität, sagt aber nicht, ob aus 50 Werten die passenden zwei herausgesucht wurden. Dauer und Nachwirkung der Verbesserung sind eine sinnvolle Frage, betreffen aber eine andere Sache als die Auswahl der Werte. Die Geldgeber zu kennen hilft bei der Einordnung, beantwortet aber nicht, ob die zwei Treffer ein Zufallscluster sind.","coreRule":"⚡ Frag nie nur nach dem Treffer, sondern nach allen Schüssen und nach dem Zeitpunkt der Zielscheibe.","beleg":"Werkstück B.19 (Anwendung: Pseudomedizin und Nahrungsergänzungsmittel; Red Flags)","status":"entwurf","kurz":"Bei 50 gemessenen Werten verbessern sich zufällig einige, auch ohne Wirkung des Mittels. Entscheidend ist, ob die zwei Werte vorab als Ziel galten und wie die übrigen 48 aussahen, sonst zeichnet man die Zielscheibe um die Treffer.","prueffrage":"Was würdest du bei 50 gemessenen Werten erwarten, wenn das Mittel überhaupt nichts bewirkt?","rueckmeldung":[{"option":1,"text":"Eine Veröffentlichung samt vieler Zitate wirkt wie ein Gütesiegel. Sie sagt aber nicht, ob aus den 50 Werten nachträglich zwei passende herausgesucht wurden, und genau das bleibt offen."},{"option":2,"text":"Ob ein Effekt anhält, ist eine sinnvolle Frage. Sie betrifft aber eine andere Sache: Selbst ein lange anhaltender Wert kann ein Zufallstreffer unter 50 Messungen sein."},{"option":3,"text":"Wer das Geld gab, hilft bei der Einordnung, und ein Interessenkonflikt wäre ein Warnzeichen. Ob die zwei Treffer unter 50 Werten ein Zufallscluster sind, beantwortet das aber nicht."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 21–22","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"21fe3c42f73287b2"}},{"id":"qx-b2-010","clusterId":"B","werkstueckRef":"B.19","stufe":3,"question":"Ein Team wertet die Daten einer großen Befragung ohne vorab festgelegte Hypothese aus und stößt auf eine auffällige Häufung. Was darf es mit diesem Ergebnis redlicherweise tun?","options":["Die Häufung von Rosenkohlvorliebe und Frühjahrsgeburtstagen als vorläufige Hypothese festhalten und an einer neuen, unabhängigen Stichprobe gezielt prüfen, bevor sie als Befund gemeldet wird.","Nach einem Drittfaktor suchen, der Rosenkohlvorliebe und Geburtsmonat verbindet, und die Häufung als Befund melden, sobald er aus den Daten herausgerechnet ist.","Die Häufung mit einem Signifikanztest an denselben 3.000 Datensätzen prüfen und als Befund melden, sobald der p-Wert unter 0,05 liegt.","Einen plausiblen Mechanismus zwischen Rosenkohlvorliebe und Geburtsmonat ausarbeiten und die Häufung als Befund melden, sobald dieser Mechanismus schlüssig klingt."],"correctIndex":0,"explanation":"Das Suchen nach Mustern ist legitim, denn so entstehen Hypothesen. Ein Arzt, der aus vielen unspezifischen Symptomen eine seltene Krankheit vermutet, tut genau das. Kritisch wird es erst, wenn der Fund als Beweis ausgegeben wird. In jeder ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster, daher kann der erste Fund nur eine Hypothese sein. Erst die Prüfung an einem neuen, unabhängigen Datensatz zeigt, ob das Muster mehr ist als Rauschen. Einen Drittfaktor herauszurechnen ist sinnvoll, wenn ein Zusammenhang schon als echt gilt; hier ist aber erst offen, ob die Häufung mehr als Zufall ist, und das bleibt in denselben Daten ungeklärt. Ein Signifikanztest wirkt streng, doch ein p-Wert unter 0,05 beweist bei 40 durchsuchten Merkmalen wenig, weil bei so vielen Vergleichen irgendwo zufällig einer darunter liegt. Ein schlüssig klingender Mechanismus wirkt vernünftig, doch im Nachhinein lässt sich zu fast jedem Muster einer finden, deshalb prüft er nichts.","coreRule":"⚡ Ein gefundenes Muster ist der Anfang der Prüfung, nicht ihr Ergebnis.","beleg":"Werkstück B.19 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"Eine Forschungsgruppe hat 40 Merkmale von 3.000 Personen erhoben. Beim Durchsehen fällt auf, dass Menschen, die gern Rosenkohl essen, auffällig oft im Frühjahr Geburtstag haben. Die Gruppe überlegt, wie sie damit umgehen soll.","kurz":"Aus dem Durchsuchen von 40 Merkmalen kann eine Häufung rein zufällig entstehen. Der Fund ist daher nur eine Hypothese, und erst eine neue, unabhängige Stichprobe zeigt, ob mehr als Rauschen dahintersteckt.","prueffrage":"Wie viele Merkmalspaare lassen sich bei 40 Merkmalen überhaupt miteinander vergleichen, und wie viele davon fallen zufällig auf?","rueckmeldung":[{"option":1,"text":"Einen Drittfaktor herauszurechnen ist sinnvoll, wenn ein Zusammenhang schon als echt gilt. Hier ist aber offen, ob die Häufung überhaupt mehr als Zufall ist, und das lässt sich in denselben Daten nicht klären."},{"option":2,"text":"Ein Signifikanztest wirkt streng, wird hier aber an denselben Daten gemacht, in denen das Muster gefunden wurde. Bei 40 durchsuchten Merkmalen liegt zufällig irgendwo ein p-Wert unter 0,05."},{"option":3,"text":"Ein schlüssiger Mechanismus gibt dem Fund Rückhalt. Im Nachhinein lässt sich aber zu fast jedem Muster einer finden, deshalb zeigt er nicht, ob die Häufung über den Zufall hinausgeht."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a1d2b654c64ee46b"}},{"id":"qx-b2-011","clusterId":"B","werkstueckRef":"B.19","stufe":4,"question":"Was sollte die Stadt als Erstes prüfen, bevor sie den Mast für die Häufung verantwortlich macht?","scenario":"In einer Straße mit rund 400 Bewohnern fiel einer Anwohnerin auf, dass mehrere Nachbarn erkrankt waren. Daraufhin begannen die Anwohner zu zählen und kamen auf neun Krankheitsfälle. Eine Lokalzeitung führt die Häufung auf den Mobilfunkmast am Ende der Straße zurück, der dort seit fünfzehn Jahren steht, und druckt eine Karte mit den Wohnorten der Erkrankten. Die Stadt will reagieren.","options":["Die Fälle noch einmal unabhängig nachzählen lassen, denn eine bestätigte Häufung ist schon ein Hinweis, dass vor Ort etwas dahintersteckt.","Prüfen, ob neun Fälle bei 400 Bewohnern auch zufällig zu erwarten sind, denn ein erst beim Zählen entdecktes Muster ist nur eine Vermutung.","Die Abstände der Wohnungen zum Mast genau vermessen, denn liegen die Fälle nahe am Mast, zeigt die Karte den Zusammenhang deutlich.","Die Erkrankten fragen, wann ihre Beschwerden begannen, denn begannen sie nach dem Bau des Masts, stützt die Reihenfolge den Verdacht."],"correctIndex":1,"explanation":"In einer ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster und scheinbar unwahrscheinliche Muster, auch wenn nichts dahintersteckt. Hier kommt hinzu, dass die Häufung erst beim Zählen aufgefallen ist. Ein solches nachträglich gefundenes Muster ist nur eine Hypothese. Bevor man ihm eine Bedeutung beimisst, muss geklärt werden, ob schon der Zufall genügt, um neun Fälle unter rund 400 Bewohnern zu erklären, und der Zusammenhang muss an einem neuen, unabhängigen Datensatz getestet werden. Erneutes Zählen bestätigt nur dieselben Daten, aus denen das Muster überhaupt erst stammt. Abstände auf einer Karte verstärken den Eindruck, prüfen aber nicht, ob das Muster mehr ist als Zufall. Und weil der Mast seit fünfzehn Jahren steht, begannen praktisch alle Beschwerden nach seinem Bau; diese Reihenfolge unterscheidet also nichts.","coreRule":"⚡ Bevor ein Cluster eine Ursache bekommt, muss der Zufall als Erklärung ausgeschlossen sein.","beleg":"Werkstück B.19 (Red Flags: Cluster in geografischen Daten; Kontext & Tiefe; Das Adaptive Talent; Anti-Denkmuster)","status":"entwurf","kurz":"Entdeckt man ein Muster erst beim Zählen, ist es nur eine Vermutung. Zuerst ist zu klären, ob neun Fälle bei rund 400 Bewohnern auch ohne jede Ursache zu erwarten sind, denn in genug Daten entstehen zwangsläufig scheinbare Häufungen.","prueffrage":"Wie viele Krankheitsfälle sind bei rund 400 Menschen in einem Zeitraum ohnehin normal, und wer hat wann angefangen zu zählen?","rueckmeldung":[{"option":0,"text":"Ein Zählfehler lässt sich so ausschließen, das ist nicht verkehrt. Doch erneutes Zählen bestätigt nur dieselben Daten, aus denen das Muster stammt, und sagt nichts darüber, ob der Zufall allein die neun Fälle erklärt."},{"option":2,"text":"Eine Karte mit Abständen lässt eine Nähe zum Mast auffällig wirken. Sie prüft aber nicht, ob das Muster mehr als Zufall ist, denn Wohnorte liegen immer irgendwo, und die Auswertung erfolgt an denselben Fällen, die das Muster erst ausgelöst haben."},{"option":3,"text":"Die Reihenfolge klingt nach einem Ursache-Wirkung-Test. Weil der Mast aber seit fünfzehn Jahren steht, begannen praktisch alle Beschwerden nach seinem Bau, und diese Abfolge unterscheidet daher nichts."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 3, 22","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e296ac2f032daae0"}},{"id":"qx-b2-012","clusterId":"B","werkstueckRef":"B.19","stufe":1,"question":"Welche Einordnung ist am besten begründet?","options":["Nach sieben Mal Kopf in Folge ist Zahl bei den nächsten Würfen überfällig, weil sich Zufallsfolgen ausgleichen und das Gleichgewicht bald wiederhergestellt wird.","Sieben Mal Kopf in Folge hat bei einer fairen Münze nur etwa 0,8 Prozent Wahrscheinlichkeit, daher ist Zufall bei diesen 100 Würfen wenig plausibel.","Der Freund hat beim Aufschreiben der 100 Würfe vermutlich vor allem die beachtet, die zu seiner Vermutung passen, sodass ein Bestätigungsfehler seinen Eindruck prägt.","Bei 100 Würfen sind sieben Mal Kopf in Folge gar nicht selten; eine gezinkte Münze wäre erst eine Vermutung, die an neuen, unabhängigen Würfen zu prüfen wäre."],"correctIndex":3,"explanation":"Bei 100 Würfen gibt es viele Stellen, an denen eine solche Reihe beginnen könnte: Mindestens sieben Mal Kopf in Folge kommt bei einer fairen Münze in etwa jeder dritten Hunderterreihe vor, sieben gleiche Ergebnisse in Folge sogar in etwa jeder zweiten. Dein Freund hat erst die Daten angesehen und dann eine Erklärung um den Klumpen gebaut, wie jemand, der erst auf die Scheunenwand schießt und die Zielscheibe danach um die dichteste Stelle malt. Eine gezinkte Münze ist deshalb nur eine Hypothese, die an neuen, unabhängigen Würfen geprüft werden muss, bevor man ihr glaubt. Der Wert von etwa 0,8 Prozent klingt überzeugend, gilt aber nur für sieben Würfe, die man vorher festgelegt hat; hier wurde die Stelle erst im Nachhinein gesucht. Ein Bestätigungsfehler ist als Erklärung naheliegend, trifft aber nicht zu, denn er hat jedes Ergebnis notiert. Dass Zahl nun „überfällig“ sei, liest ebenfalls Bedeutung in den Zufall hinein, denn die Münze hat kein Gedächtnis.","coreRule":"⚡ Wo Zufall wirkt, entstehen Klumpen, ohne dass jemand sie verursacht hat.","quote":"Der Fehler liegt darin, diesen Zufallsclustern eine Bedeutung beizumessen, nachdem man sie gefunden hat.","quoteLabel":"Merksatz:","beleg":"Werkstück B.19 (Werkbank-Frage; Analyse)","status":"entwurf","scenario":"Ein Freund wirft 100-mal eine Münze und schreibt jedes Ergebnis auf. In der Reihe findet er sieben Mal hintereinander Kopf. Er ist sicher: „Das kann kein Zufall sein. Entweder ist die Münze gezinkt, oder irgendetwas hat das Ergebnis beeinflusst.“","kurz":"Bei 100 Würfen bietet sich viele Male die Chance, dass irgendwo eine lange Reihe beginnt; sie kommt oft vor. Wer erst die Daten ansieht und dann eine Erklärung um den Klumpen baut, hat nur eine Vermutung, die neue, unabhängige Würfe prüfen müssten.","prueffrage":"In wie vielen von zehn Hunderterreihen einer fairen Münze würdest du irgendwo sieben Mal Kopf hintereinander erwarten?","rueckmeldung":[{"option":0,"text":"Auf lange Sicht nähern sich die Anteile tatsächlich 50:50, aber nicht, weil Zahl etwas nachholt. Jeder Wurf ist unabhängig, die Münze hat kein Gedächtnis, und die Chance auf Zahl liegt nach sieben Mal Kopf weiter bei 50 Prozent."},{"option":1,"text":"Für sieben vorher festgelegte Würfe stimmt der Wert von etwa 0,8 Prozent. Hier wurde die Stelle aber erst im Nachhinein in 100 Würfen gesucht, und dann kommt eine solche Reihe überraschend häufig vor."},{"option":2,"text":"Ein Bestätigungsfehler wäre bei einer Auswahl der Ergebnisse naheliegend. Hier hat der Freund aber jedes Wurfergebnis notiert; der Fehler liegt woanders, nämlich darin, dass das Muster erst nachträglich gesucht und gedeutet wurde."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie auf einer Kursseite der University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1125","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1125"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f41bcb46573c6c61"}},{"id":"qx-b2-013","clusterId":"B","werkstueckRef":"B.20","stufe":1,"question":"Ein Schätzexperiment: Menschen sehen ein Glücksrad, das zufällig bei 10 oder 65 stehen bleibt. Danach sagen sie, ob der Anteil afrikanischer Länder in der UNO über oder unter dieser Zahl liegt, und schätzen ihn. Wer die 10 sah, schätzt im Median 25 %, wer die 65 sah, 45 %. Wie lässt sich das am besten deuten?","options":["Nur Zahlen mit erkennbarem Bezug zur UNO-Frage beeinflussen Schätzungen, ein Glücksrad blenden Menschen aus; der Unterschied zwischen 25 % und 45 % hat andere Gründe.","Die Gruppe mit der 65 wusste schon vorher mehr über die Zusammensetzung der UNO als die mit der 10, wie es bei Vergleichen ohne Zufallszuteilung vorkommt.","Die Teilnehmer schätzten nach dem, was ihnen aus Nachrichten über afrikanische Länder präsent war (Verfügbarkeitsheuristik), nicht nach der Zahl auf dem Glücksrad.","Auch eine zufällige, völlig unpassende Zahl wie die 10 oder die 65 zieht Schätzungen in ihre Richtung, selbst wenn sie mit der UNO-Frage nichts zu tun hat."],"correctIndex":3,"explanation":"Die zufällige, bedeutungslose Zahl des Glücksrads wirkte als mentaler Anker: Die Schätzungen wurden in Richtung dieser ersten Zahl gezogen. Bei Schätzungen wirkt eine solche erste Zahl selbst dann, wenn sie erkennbar willkürlich ist.","coreRule":"⚡ Die erste Zahl zieht dein Urteil zu sich, auch wenn sie nichts mit der Frage zu tun hat.","beleg":"Werkstück B.20; Fn. gl-b-anchoring (Tversky/Kahneman 1974, Science 185, S. 1128; Rad-Detail nach Kahneman 2012, Kap. 11)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Selbst eine erkennbar willkürliche Zahl zieht Schätzungen in ihre Richtung. Da das Glücksrad die Gruppen zufällig einteilte, bleibt als Erklärung der Unterschied 25 % gegenüber 45 %, nicht Vorwissen oder Nachrichtenlage.","prueffrage":"Wie wurde entschieden, wer die 10 und wer die 65 zu sehen bekam, und welche Gruppe schätzte höher?","rueckmeldung":[{"option":0,"text":"Der Gedanke, dass nur Passendes zählt, klingt plausibel. Hier widerspricht ihm der Befund aber selbst: Die Zahl vom Glücksrad hatte erkennbar keinen Bezug zur Frage und verschob die Schätzungen trotzdem."},{"option":1,"text":"Vorwissen ist bei Gruppenvergleichen oft eine Störquelle, das stimmt. Hier teilte aber der Zufall des Glücksrads die Gruppen ein, sodass sich Vorwissensunterschiede im Schnitt ausgleichen und den Abstand nicht erklären."},{"option":2,"text":"Was aus Nachrichten präsent ist, kann Schätzungen tatsächlich prägen. Es betrifft aber beide zufällig gebildeten Gruppen gleichermaßen und erklärt daher nicht, warum sie sich je nach gesehener Zahl unterscheiden."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1128"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Kap. 11","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"7d30faf1e48ae118"}},{"id":"qx-b2-014","clusterId":"B","werkstueckRef":"B.20","stufe":2,"question":"Wie wirkt der durchgestrichene Preis auf dein Urteil, und welche Frage prüft das Angebot am besten?","scenario":"Im Onlineshop steht neben einer Jacke: „UVP 199 €, jetzt nur 99 €!“ Du hattest vorher keine Vorstellung davon, was eine solche Jacke kosten sollte.","options":["Die 199 € löst die Angst aus, die Jacke zu verpassen, denn Verluste wiegen schwerer als Gewinne; frag dich, ob du das Angebot bereuen würdest, wenn du es auslässt.","Die 199 € zieht dein Urteil in ihre Richtung, denn die hohe erste Zahl lässt 99 € billig erscheinen; frag dich, wie du den Preis ohne die 199 ganz neu bewerten würdest.","Die 199 € wirkt über die Zahl früherer Käufer, denn was viele zu diesem Preis gekauft haben, scheint gut zu sein; frag dich, wie beliebt die Jacke bei anderen Kunden ist.","Die 199 € wirkt über den Ruf einer Marke, denn bekannte Namen färben auf die Bewertung ab (Halo-Effekt); frag dich, ob du die Jacke auch ohne Markennamen kaufen würdest."],"correctIndex":1,"explanation":"Die durchgestrichene Zahl ist ein klassischer Anker: Die erste genannte Zahl setzt den Rahmen, in dem du die zweite beurteilst, und 99 € wirken günstig, weil sie neben 199 € stehen, nicht weil du den Wert der Jacke kennst. Gegen die Wirkung hilft die Frage, wie du den Preis bewerten würdest, wenn es die erste Zahl nie gegeben hätte. Preiswissen schützt nicht zuverlässig: In einem Versuch ließen sich auch erfahrene Immobilienmakler bei der Schätzung eines Hauswerts vom vorgegebenen Angebotspreis beeinflussen (Northcraft und Neale 1987). Der Streichpreis ist außerdem kein verlässlicher Beleg für den Wert, sondern ein hoher Anker, der den tatsächlichen Preis als Schnäppchen erscheinen lässt. Die Angst, ein Angebot zu verpassen, klingt bei einem Sonderpreis naheliegend, braucht aber eine Frist oder knappe Ware, wovon hier nichts steht. Beliebtheit bei anderen Käufern wirkt wie ein Qualitätszeichen, doch ein durchgestrichener Preis sagt nichts über andere Kunden. Auch ein Markenname, der auf die Bewertung abfärben könnte, kommt nicht vor.","coreRule":"⚡ Bewerte jeden Preis so, als hättest du den ersten genannten nie gesehen.","quote":"Wenn diese erste Zahl/diese erste Information nie existiert hätte, wie würde ich diese Situation dann völlig neu und von Grund auf bewerten?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.20 (Anwendung: Preisgestaltung; Anti-Denkmuster)","status":"entwurf","kurz":"Die 199 € setzt den Rahmen, in dem du die 99 € beurteilst: Neben der hohen Zahl wirken sie günstig, obwohl du den Wert der Jacke nicht kennst. Frag dich daher, wie du den Preis ohne die erste Zahl bewerten würdest.","prueffrage":"Was kosten vergleichbare Jacken bei anderen Händlern, und steht dort ebenfalls ein Streichpreis daneben?","rueckmeldung":[{"option":0,"text":"Die Sorge, ein Angebot zu verpassen, ist bei Sonderpreisen vertraut. Sie braucht aber einen Auslöser wie eine Frist oder knappe Ware, und davon steht hier nichts. Die Streichzahl wirkt als Bezugsrahmen, nicht als Verlustdrohung."},{"option":2,"text":"Dass viele Käufer ein Qualitätszeichen sein können, stimmt, und die Frage nach der Beliebtheit ist an sich vernünftig. Hier gibt es aber keine Angabe zu anderen Kunden, und ein durchgestrichener Preis sagt darüber nichts."},{"option":3,"text":"Bekannte Markennamen können die Bewertung tatsächlich färben. Im Szenario wird aber keine Marke genannt, es gibt nur die beiden Preise. Die Wirkung kommt von der Zahl 199 und nicht von einem Ruf."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"literatur","kurz":"Northcraft, G. B.; Neale, M. A. (1987): Experts, amateurs, and real estate: An anchoring-and-adjustment perspective on property pricing decisions. Organizational Behavior and Human Decision Processes 39(1), 84–97","oeffentlich":false},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"18fdc3ca91694dcb"}},{"id":"qx-b2-015","clusterId":"B","werkstueckRef":"B.20","stufe":3,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Der Befund zu Weinpreisen und Versicherungsnummern ist weniger gesichert als gedacht; dass Anker Schätzungen beeinflussen, ist davon unabhängig weiterhin gut belegt.","Spätere Studien zum Weinpreis fanden meist schwächere Effekte; also ist der Ankereffekt insgesamt widerlegt, auch bei Schätzungen und anderen Urteilen.","Der Befund mit der Versicherungsnummer wurde begutachtet veröffentlicht; er wiegt daher schwerer als spätere Wiederholungen und bleibt gültig.","Dass mehrere Wiederholungen zum Wein überhaupt etwas fanden, wenn auch weniger, bestätigt den Befund; die schwächeren Effekte sind nur Messrauschen."],"correctIndex":0,"explanation":"Misslingt die Wiederholung eines Versuchs oder fällt der Effekt viel schwächer aus, ist der ursprüngliche Befund weniger sicher, aber nicht automatisch widerlegt. Und er sagt nur etwas über genau diese Versuchsanordnung: Dass ein zufälliger Zahlenanker die Zahlungsbereitschaft stark lenkt, ist unsicher. Dass Anker Schätzungen verzerren, ist davon getrennt gut belegt, etwa durch das Glücksrad-Experiment von Tversky und Kahneman, in dem eine erkennbar zufällige Zahl die Schätzung des Anteils afrikanischer UN-Mitglieder verschob (Median 25 % gegenüber 45 %). Selbst Maniadis und Kollegen, die deutlich kleinere Effekte fanden als Ariely und seine Kollegen, halten Ankereffekte bei Bewertungen für real und bezweifeln nur deren Größe. Dass die Wiederholungen den Ankereffekt insgesamt widerlegen, klingt konsequent, folgt aber nicht, denn sie betrafen nur diese Versuchsanordnung. Eine Begutachtung klingt nach Qualitätssiegel, schützt aber nicht vor einem Befund, den andere nicht reproduzieren können, deshalb zählen hier die Wiederholungen. Und dass die Wiederholungen etwas fanden, klingt nach Bestätigung, doch Effekte, die deutlich kleiner ausfielen oder ganz fehlten, lassen sich nicht als bloßes Messrauschen abtun.","coreRule":"⚡ Wird ein Befund schlechter bestätigt, ist er weniger sicher, nicht automatisch falsch. Prüfe, was genau wackelt, und wie stark.","beleg":"Werkstück B.20 (Analyse); Fn. gl-b-anker-preis (Ariely/Loewenstein/Prelec 2003, S. 75–77; Maniadis/Tufano/List 2014, AER 104(1), S. 277–290, dort: andere Studien fanden „(if any) much smaller effects“; Ankereffekte bei Bewertungen gelten dennoch als real, offen ist ihre Größe)","status":"entwurf","scenario":"Eine Kollegin sagt: „Ein Experiment hat gezeigt, dass Menschen mehr für einen Wein zahlen, wenn sie vorher die letzten Ziffern ihrer Sozialversicherungsnummer als Dollarbetrag notiert haben. Ein Zufallswert steuert also, was wir bereit sind zu zahlen.“ Später liest du, dass spätere Studien meist deutlich schwächere Effekte fanden, manche gar keine.","kurz":"Dass spätere Studien den Weinpreis-Effekt kaum bestätigen, macht genau diesen Befund unsicherer. Der Fehler wäre, daraus den Ankereffekt insgesamt für widerlegt zu halten: Die Wiederholungen betrafen nur diese Versuchsanordnung.","prueffrage":"Was genau fanden die späteren Studien im Vergleich zum ersten Versuch, und was wurde dort überhaupt gemessen?","rueckmeldung":[{"option":1,"text":"Dass die späteren Studien meist schwächere Effekte fanden, stimmt. Sie prüften aber nur die Weinpreis-Anordnung. Für Ankereffekte bei Schätzungen und anderen Urteilen sagt das wenig, und selbst Kritiker halten sie für real."},{"option":2,"text":"Eine Begutachtung klingt nach Qualitätssiegel, garantiert aber nicht, dass andere den Befund wiederholen können. Deshalb zählen hier die Wiederholungen, und die sprechen eher gegen ein „bleibt gültig“."},{"option":3,"text":"Dass überhaupt etwas gefunden wurde, spricht dafür, dass der Befund nicht ganz leer ist. Deutlich kleinere oder fehlende Effekte sind aber selbst ein Ergebnis und lassen sich nicht einfach als Messrauschen abtun."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Maniadis, Z.; Tufano, F.; List, J. A. (2013): One Swallow Doesn't Make a Summer: New Evidence on Anchoring Effects. CeDEx Discussion Paper 2013-07 (später AER 104(1), 277–290)","oeffentlich":true,"url":"https://www.nottingham.ac.uk/cedex/documents/papers/cedex-discussion-paper-2013-07.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ariely, D.; Loewenstein, G.; Prelec, D. (2003): „Coherent Arbitrariness“: Stable Demand Curves Without Stable Preferences. Quarterly Journal of Economics 118(1), 73–106","oeffentlich":false,"doi":"10.1162/00335530360535153"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"55dd66ad3f108af2"}},{"id":"qx-b2-016","clusterId":"B","werkstueckRef":"B.20","stufe":4,"question":"Welche Erklärung passt am besten dazu, dass die Zufallszahl die Schätzungen trotzdem verschiebt?","scenario":"In einem Versuch sollen Menschen schätzen, wie viel Prozent der Mitgliedstaaten der Vereinten Nationen afrikanische Länder sind. Vorher dreht die Versuchsleitung ein Glücksrad (Ergebnis: 65) und fragt: „Liegt der Anteil über oder unter dieser Zahl?“ Danach liegen die Schätzungen deutlich höher als bei einer Vergleichsgruppe, die ohne Rad schätzt. Du weißt: Das Rad war reiner Zufall, und niemand hielt die Zahl für eine Expertenauskunft.","options":["Die Zahl wirkt, weil Menschen sich Zahlen nur einmal merken können und auch bei neuen Informationen nicht mehr umdenken.","Die Zahl wirkt, weil die Schätzenden sie für eine Expertenauskunft halten und sie dann ungeprüft übernehmen.","Die Frage nach „darüber oder darunter“ ruft bevorzugt Wissen wach, das zur Zahl passt, und färbt so die anschließende Schätzung.","Die Schätzenden starten bei der Zahl und passen von dort aus immer zu wenig an, genau wie bei selbst gewählten Ausgangswerten."],"correctIndex":2,"explanation":"Das Rad war erkennbar zufällig, und niemand hielt die Zahl für eine Expertenauskunft; ungeprüftes Vertrauen erklärt den Effekt also nicht. Die klassische Erklärung „Anpassung und Verankerung“ (Start beim Anker, zu wenig Korrektur) gilt nach späteren Versuchen vor allem für selbst gewählte Ausgangswerte, hier aber war die Zahl vorgegeben. Bei vorgegebenen Ankern wirkt offenbar ein anderer Mechanismus: Schon die Frage, ob die Antwort über oder unter der Zahl liegt, ruft bevorzugt Wissen wach, das zu ihr passt. Dass Menschen sich Zahlen nur einmal merken und nie mehr umdenken könnten, ist eine Übertreibung, die das Beispiel nicht stützt. Wer die Erklärung eines Effekts prüft, sollte fragen, ob sie zu den Rahmenbedingungen passt; ob beide Mechanismen nebeneinander wirken, ist in der Forschung umstritten.","coreRule":"⚡ Anker wirken auf mehr als einem Weg: Prüfe bei einer Erklärung, ob sie zu den Umständen passt (vorgegebener oder selbst gewählter Anker), und ersetze die erste Zahl bewusst durch eine eigene Ausgangsschätzung.","beleg":"Werkstück B.20 (Analyse: Anpassung und Verankerung); Fn. gl-b-anker-mechanismus (Epley/Gilovich 2006, Psychological Science 17(4), S. 312, 317; Gegenposition Simmons/LeBoeuf/Nelson 2010)","status":"entwurf","kernregel":"⚡ Auch eine erkennbar zufällige Zahl kann Schätzungen verschieben, schon die Frage „darüber oder darunter?“ ruft passendes Wissen wach. Schätze deshalb zuerst eigenständig, bevor du eine vorgegebene Zahl beachtest.","kurz":"Bei einer vorgegebenen Zahl erklärt vermutlich schon die Frage „über oder unter dieser Zahl?“ den Effekt, weil sie passendes Wissen wachruft. Vertrauen in eine Auskunft scheidet aus, und Start mit zu wenig Korrektur passt eher zu selbst gewählten Werten.","prueffrage":"Was unterscheidet diese Zahl von einem Startwert, den die Schätzenden selbst gewählt hätten, und woher kam sie?","rueckmeldung":[{"option":0,"text":"Dass die Schätzungen an der Zahl hängen, ist tatsächlich zu beobachten. Daraus folgt aber nicht, dass Menschen sich Zahlen nur einmal merken und nie umdenken: Das ist überzogen, und das Beispiel stützt es nicht."},{"option":1,"text":"Ungeprüftes Vertrauen in eine Auskunft ist ein möglicher Grund, warum Zahlen wirken. Hier passt er nicht: Das Rad war erkennbar Zufall, und niemand hielt die Zahl für eine Expertenauskunft."},{"option":3,"text":"Start beim Anker und zu wenig Korrektur ist die bekannte Erklärung und gilt vor allem für selbst gewählte Ausgangswerte. Hier wurde die Zahl vorgegeben, deshalb erklärt sie den Effekt nicht am besten."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Association for Psychological Science: Abstract zu Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient","oeffentlich":true,"url":"https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.2006.01704.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient. Psychological Science 17(4), 311–318","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01704.x","seite":"S. 312, 317"},{"typ":"literatur","kurz":"Simmons, J. P.; LeBoeuf, R. A.; Nelson, L. D. (2010): The effect of accuracy motivation on anchoring and adjustment: Do people adjust from provided anchors? Journal of Personality and Social Psychology 99(6)","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"90439d974211788f"}},{"id":"qx-b2-017","clusterId":"B","werkstueckRef":"B.21","stufe":1,"question":"Welche Erwiderung auf den Einwand des Ingenieurs prüft die Behauptung am besten, ohne die Ebenen von Werten und Fakten zu vermischen?","options":["Das Ziel steht fest. Offen ist nur der Weg, und ob er trägt, lässt sich mit den Berechnungen des Ingenieurs prüfen.","Der Ingenieur teilt das Ziel der Aktivistin, also stimmen auch seine Berechnungen, und sie sollte ihren Plan aufgeben.","Ziele zählen in solchen Debatten nicht. Nur wer die besseren Zahlen hat, darf über Energiepolitik mitreden.","Beide Seiten wollen das Richtige, also lässt sich nicht klären, wer sachlich recht hat. Es bleibt Geschmackssache."],"correctIndex":0,"explanation":"Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Tatsachenannahmen und wehrt die Gegenzahlen mit einem Angriff auf Motive ab. Das vermischt zwei Ebenen: was erstrebenswert ist (Werte) und was tatsächlich funktioniert (Fakten). Das Ziel kann geklärt sein, während der Weg offen bleibt und sich anhand von Fakten und Daten klären lässt. Ob der Ingenieur recht hat, ist damit noch nicht entschieden. Das zeigt sich erst, wenn man seine Berechnungen prüft, nicht durch den Verweis auf moralische Überlegenheit. Falsch wäre es, aus dem geteilten Ziel auf die Richtigkeit der Berechnungen zu schließen, Ziele für irrelevant zu erklären oder die Tatsachenfrage für unentscheidbar zu halten. Gute Absichten sind kein Schutz vor schlechten Ergebnissen.","coreRule":"⚡ Eine gute Absicht macht die Tatsachenbehauptung nicht wahr.","beleg":"Werkstück B.21 (Kernidee; Anti-Denkmuster; Beispiel Aktivistin und Ingenieur)","status":"entwurf","scenario":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten, also stimmt auch unser Plan: Jede Kernenergie ist abzulehnen, und eine Versorgung allein aus Erneuerbaren ist machbar. Wer das bezweifelt, dem ist der Planet egal.“ Ein Ingenieur entgegnet: „Ich teile dein Ziel, aber meine Berechnungen zeigen, dass wir ohne Kernenergie keine stabile Versorgung gewährleisten können.“ Die Aktivistin antwortet: „Deine Zahlen sind nur Ablenkung. Wir haben die moralische Überlegenheit, und die zählt am Ende.“","kurz":"Das Ziel kann geklärt sein, während der Weg offen bleibt: Ob der Plan trägt, zeigt sich erst an den Berechnungen. Der Fehler wäre, von guter Absicht auf richtige Tatsachen zu schließen oder Gegenzahlen als Ablenkung abzutun.","prueffrage":"Was genau wirft die Aktivistin dem Ingenieur vor, und was sagt sie zu seinen Berechnungen selbst?","rueckmeldung":[{"option":1,"text":"Dass der Ingenieur das Ziel teilt, wirkt wie ein Argument für seine Seite. Doch auch bei ihm sagt die Absicht nichts über die Richtigkeit seiner Zahlen. Sie müssen genauso geprüft werden wie der Plan der Aktivistin."},{"option":2,"text":"Zahlen sind für die Wirksamkeit eines Plans wichtig, aber das Ziel bleibt dennoch eine Wertfrage, über die man sich verständigen kann. Es ist sogar die Grundlage, auf der man überhaupt von „funktioniert“ oder „funktioniert nicht“ spricht."},{"option":3,"text":"Dass beide das Richtige wollen, macht die Tatsachenfrage nicht zur Geschmackssache. Ob eine Versorgung ohne Kernenergie stabil läuft, lässt sich mit Daten und Berechnungen klären, unabhängig von den Absichten beider Seiten."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c45ec9ed65b1d967"}},{"id":"qx-b2-018","clusterId":"B","werkstueckRef":"B.21","stufe":2,"question":"Was lässt sich aus dieser Antwort über die Richtigkeit der Berechnungen schließen?","scenario":"In einer Debatte zur Energieversorgung legt ein Ingenieur Berechnungen vor, wonach sich eine stabile Stromversorgung mit der heutigen Technik und Speicherlösung nicht allein mit erneuerbaren Quellen sichern lässt. Die Gegenseite antwortet: „Sie arbeiten für eine moralisch korrupte Industrie. Unsere Sache ist gerecht, und das zählt am Ende.“","options":["Sie zeigt, dass die Berechnungen stimmen, denn die Gegenseite legt keine eigene Zahl vor und greift nur den Ingenieur an.","Sie zeigt, dass die Berechnungen unvollständig sind, denn eine stabile Stromversorgung muss auch moralische Gründe berücksichtigen, die in Zahlen fehlen.","Sie zeigt, dass seine Zahlen vermutlich geschönt sind, denn wer für die Industrie arbeitet, rechnet meist in Richtung der eigenen Interessen.","Sie zeigt nichts darüber, denn ob die Berechnungen stimmen, lässt sich nur an den Zahlen selbst klären, nicht an Herkunft oder Moral."],"correctIndex":3,"explanation":"Die Antwort greift das Motiv des Gegners an („moralisch korrupte Industrie“) und beruft sich auf die eigene gerechte Sache. Beides sind Aussagen über Absichten und Werte, keine über die Berechnungen. Ob eine Rechnung stimmt, hängt nicht davon ab, wer sie vorlegt oder wie gut die Ziele des Gegenübers sind. Auch wer ein moralisch hehres Ziel verfolgt, kann sich über die Fakten irren, und auch ein Gegner mit zweifelhaften Motiven kann richtig rechnen. Der Einwand wäre nur dann ein Argument, wenn er die Zahlen selbst prüft, etwa Annahmen, Rechenweg oder Datenquellen. Solange das nicht geschieht, bleibt die Sachfrage offen und muss mit den Zahlen geklärt werden. Dass die Gegenseite keine Gegenzahlen nennt, wirkt wie ein Zugeständnis, macht die Berechnungen aber nicht richtig, sondern lässt die Frage offen. Moralische Gründe können für Entscheidungen wichtig sein, sagen aber nichts darüber, ob eine Rechnung stimmt. Und dass jemand befangen sein kann, ist ein Grund zum genauen Hinsehen, aber kein Beleg dafür, dass die Zahlen falsch sind.","coreRule":"⚡ Wer die Motive des Gegners angreift oder die eigene Moral betont, hat seine Zahlen noch nicht widerlegt.","beleg":"Werkstück B.21 (Eingangsszene; Analyse: Selbst-Immunisierung, Ad hominem)","status":"entwurf","kurz":"Der Angriff auf das Motiv und der Verweis auf die gerechte Sache sagen nichts darüber, ob die Rechnung stimmt. Ob sie stimmt, zeigt sich nur an Annahmen, Rechenweg und Daten, nicht an Herkunft oder Moral des Vorlegenden.","prueffrage":"Würde sich an den Berechnungen etwas ändern, wenn derselbe Ingenieur für einen Umweltverband arbeitete?","rueckmeldung":[{"option":0,"text":"Dass die Gegenseite keine eigene Rechnung vorlegt, wirkt wie ein Zugeständnis. Es lässt die Frage aber nur offen: Ob die Zahlen stimmen, wird erst durch die Prüfung von Annahmen, Rechenweg und Daten entschieden."},{"option":1,"text":"Moralische Gründe können bei der Entscheidung durchaus ins Gewicht fallen. Sie zeigen aber keine Lücke in der Rechnung: Ob eine Berechnung stimmt oder unvollständig ist, lässt sich nur an ihren Annahmen und Daten ablesen."},{"option":2,"text":"Befangenheit ist ein guter Grund, genauer hinzusehen. Sie ist aber noch kein Beleg dafür, dass die Zahlen falsch sind, denn auch wer Interessen hat, kann richtig rechnen. Das zeigt sich nur an der Rechnung selbst."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"eb1ed22dadd83747"}},{"id":"qx-b2-019","clusterId":"B","werkstueckRef":"B.21","stufe":3,"question":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten. Die Zahlen des Ingenieurs sind nur Ablenkung, er arbeitet für eine moralisch korrupte Industrie. Wir sind moralisch im Recht, und das zählt.“ Was ist an diesem Vorgehen der Kern des Fehlers?","options":["Sie schließt von der guten Absicht ihres Ziels auf die Richtigkeit ihrer Annahmen über den Weg dorthin und prüft die Zahlen deshalb nicht.","Sie verzerrt die Aussage des Ingenieurs zu einer leichter angreifbaren Karikatur und widerlegt nur diese, statt seine eigentlichen Zahlen.","Sie stützt ihren Plan auf die große Zahl ihrer Anhänger und lässt so die Zustimmung vieler an die Stelle der Prüfung der Annahmen treten.","Sie schließt von dem, was ist, auf das, was sein soll, und begründet ihre Forderung damit, dass der heutige Zustand auch der richtige sei."],"correctIndex":0,"explanation":"Ob ein Ziel gut ist (Werte) und ob ein bestimmter Weg es erreicht (Fakten), sind zwei verschiedene Fragen. Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Annahmen und wehrt Gegenargumente ab, indem sie die Motive des Ingenieurs angreift, statt seine Zahlen zu prüfen. Ob er recht hat, ist damit nicht entschieden, das ließe sich nur mit den Daten klären. Eine moralische Überzeugung ist dabei nicht das Problem, sie treibt oft Reformen an. Zum Fehler wird sie, wenn sie zur Lizenz wird, die Realität nicht mehr zu prüfen, und Fakten dann als moralisch minderwertig gelten. Ein Strohmann setzt eine verzerrte Wiedergabe der Aussage des anderen voraus; sie gibt aber gar keine Fassung seiner Aussage wieder. Dass viele ihrer Anhänger zustimmen, spielt in ihrer Äußerung keine Rolle. Und sie leitet nicht das Sollen aus dem Sein ab, sondern umgekehrt das Sein aus ihrem Wollen.","coreRule":"⚡ Moral gibt das Ziel vor, aber den Weg dorthin entscheiden die Fakten.","beleg":"Werkstück B.21 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Ob ein Ziel gut ist, sagt nicht, ob ein Weg es erreicht. Die Aktivistin lässt die gute Absicht für die Richtigkeit ihrer Annahmen einstehen und greift die Motive des Ingenieurs an, statt seine Zahlen zu prüfen.","prueffrage":"Womit begegnet die Aktivistin den Zahlen des Ingenieurs, und was davon betrifft die Zahlen selbst?","rueckmeldung":[{"option":1,"text":"Eine Verzerrung würde voraussetzen, dass sie seine Aussage in einer Fassung wiedergibt. Das tut sie aber nicht: Sie nennt seine Zahlen nur „Ablenkung“ und greift seine Motive an. Seine Zahlen bleiben ungeprüft."},{"option":2,"text":"Auf die Zahl ihrer Anhänger beruft sie sich in dieser Äußerung nirgends. Ihr „Wir“ benennt die Bewegung, ist aber kein Argument. Die Annahmen bleiben ungeprüft, weil sie sich moralisch im Recht sieht, nicht weil viele zustimmen."},{"option":3,"text":"Ein solcher Fehlschluss würde den heutigen Zustand zum richtigen erklären. Die Aktivistin will den Zustand aber gerade verändern. Ihr Fehler läuft in die andere Richtung: Aus ihrem Wollen, dem guten Ziel, folgt angeblich schon, dass ihre Annahmen über den Weg stimmen."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"117c40b74c671a82"}},{"id":"qx-b2-020","clusterId":"B","werkstueckRef":"B.21","stufe":4,"question":"Was ist ein produktiver erster Zug in dieser Debatte?","scenario":"In deinem Verein streiten zwei Lager über die Methoden eines Tierschutz-Protests. Lager A sagt: „Wir blockieren Schlachthof-Zufahrten, denn das ist der einzige Weg, der der Sache gerecht wird.“ Lager B meint: „Die Blockaden schaden uns eher, weil sie Spenden und Unterstützung kosten.“ Beide wollen weniger Tierleid und halten sich für moralisch im Recht.","options":["Beide Lager ihre Beweggründe für Blockade oder Verzicht darlegen lassen und dem Lager folgen, das glaubwürdiger für die Tiere eintritt, weil gute Absichten für gute Methoden sprechen.","Zuerst klären, ob der Verein Tierleid überhaupt verringern soll, denn ohne gemeinsame Werte lässt sich über Blockaden nicht sinnvoll streiten.","Das gemeinsame Ziel, weniger Tierleid, als geklärt festhalten und getrennt davon anhand der vorliegenden Daten prüfen, welcher Weg es am ehesten erreicht.","Sich auf einen Mittelweg zwischen Blockade und Verzicht einigen, etwa auf Blockaden nur an einzelnen Tagen, weil beide Lager dann Zugeständnisse machen und der Streit im Verein schnell endet."],"correctIndex":2,"explanation":"Hier streiten zwei Lager nicht über Werte, sondern über eine Tatsachenfrage: Welcher Weg führt tatsächlich zum gemeinsamen Ziel? Gute Absichten sagen nichts darüber, ob eine Methode wirkt. Man kann das Richtige wollen und sich trotzdem über den Weg irren. Sinnvoll ist deshalb, das Ziel als geklärt zu betrachten und die Wege an Fakten und Daten zu messen: Wie haben ähnliche Aktionen auf Spenden, Mitglieder und öffentliche Meinung gewirkt? Erst dann lässt sich begründet entscheiden. Der Vergleich der Beweggründe wirkt fair, ersetzt aber die Faktenprüfung durch Selbstvergewisserung, denn lautere Absichten sagen nicht, welche Methode wirkt. Die Frage nach den gemeinsamen Werten klingt grundsätzlich, doch über den Wert streiten die Lager nicht, denn beide wollen weniger Tierleid. Ein Mittelweg klingt nach einem Kompromiss, ist aber keine Prüfung, weil er nur fragt, wie sich beide Lager treffen, und nicht, was das Ziel erreicht.","coreRule":"⚡ Erst das Ziel klären, dann die Wege an den Fakten messen.","beleg":"Werkstück B.21 (Anti-Denkmuster; Verbindungen: Stahlmann-Argument)","status":"entwurf","kurz":"Hier streiten die Lager über eine Tatsachenfrage, nicht über Werte: Welcher Weg führt zum gemeinsamen Ziel? Gute Absichten sagen nicht, ob eine Methode wirkt, deshalb gehört der Weg an Daten geprüft.","prueffrage":"Wenn sich herausstellte, dass Blockaden tatsächlich Spenden kosten, würde das etwas an den Absichten von Lager A ändern?","rueckmeldung":[{"option":0,"text":"Offene Beweggründe schaffen Verständnis füreinander. Aber auch lautere Absichten sagen nicht, welche Methode wirkt: Man kann das Richtige wollen und sich über den Weg irren. Und beide Lager halten sich ja für moralisch im Recht."},{"option":1,"text":"Eine gemeinsame Wertbasis ist wichtig, hier aber schon da: Beide Lager wollen weniger Tierleid. Gestritten wird über den Weg, und die Frage danach lässt sich nicht durch weitere Wertdebatten beantworten."},{"option":3,"text":"Ein Kompromiss beendet Streit oft schnell. Er beantwortet aber nur, wie sich beide Lager treffen, nicht, welcher Weg Tierleid tatsächlich verringert. Auch Blockaden an einzelnen Tagen sind nur dann gut, wenn Daten dafür sprechen."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ed60c32934f10a22"}},{"id":"qx-b2-021","clusterId":"B","werkstueckRef":"B.22","stufe":1,"question":"Was erklärt am besten, warum so viele Menschen nicht erkennen können, ob das Posting ernst gemeint ist?","options":["Ohne erkennbaren Hinweis auf die Absicht lässt sich eine Parodie auf Extremes nicht von echtem Extremismus unterscheiden, der oft ebenso absurd klingt.","Die Leser bewegen sich in Echokammern und kennen den Tonfall anderer Gruppen nicht mehr, weshalb sie Beiträge aus fremden Lagern regelmäßig falsch einordnen.","Die Leser prüfen die Behauptung nicht an Quellen; wer sie nachschlägt, erkennt am Ergebnis, ob der Verfasser sie ernst meint, und kann sie einordnen.","Der Wahrheitseffekt wirkt: Was man mehrfach liest, hält man eher für wahr, und so wird aus einem Scherz in der Debatte schrittweise Ernst, ohne dass die Leser es bemerken."],"correctIndex":0,"explanation":"Ohne Tonfall, Mimik und Körpersprache fehlen im Netz die Signale, an denen man im Gespräch Satire von Ernst unterscheidet. Hinzu kommt: Die Wirklichkeit des Extremismus ist oft so bizarr, dass eine Parodie davon kaum noch abweicht. Deshalb kann dieselbe Aussage für den einen ein Witz und für den anderen aufrichtig sein, und echter Extremismus wird umgekehrt manchmal für Satire gehalten. Ein Beispiel: Die Bewegung „Birds Aren’t Real“ war von Anfang an Satire, wurde aber von Fremden häufig für echte Verschwörungsgläubigkeit gehalten. Die Unsicherheit liegt also im fehlenden Kontext, nicht in einer erkennbaren Gesinnung des Verfassers. Sinnvoll ist deshalb, Kontext und Absicht zu prüfen, statt vorschnell nach dem eigenen Eindruck zu urteilen.","coreRule":"⚡ Ohne klaren Hinweis auf die Absicht lässt sich Satire über Extremes nicht verlässlich von echtem Extremismus unterscheiden: Prüfe Kontext und Absicht, statt nur nach deinem Eindruck zu urteilen.","beleg":"Werkstück B.22 (Kernidee; Analyse); Fn. gl-b-poe (Nathan Poe 2005; Aikin 2013)","status":"entwurf","scenario":"Auf einer Social-Media-Plattform erscheint der Beitrag: „Alle Tauben sind Überwachungsdrohnen der Regierung. Wer das noch bezweifelt, ist naiv.“ Kein Emoji, kein Hinweis auf Ironie, keine Angabe zum Autor. Unter dem Beitrag streiten sich die Leute: Ein Teil stimmt empört zu, ein anderer Teil lacht über den vermeintlichen Witz. Eine Person fragt: „Ist das ernst gemeint oder Satire?“ Niemand kann es sicher sagen.","kurz":"Im Netz fehlen Tonfall und Mimik, an denen man sonst Satire von Ernst unterscheidet, und echter Extremismus klingt oft selbst so absurd wie eine Parodie. Wer den Beitrag aus dem eigenen Eindruck heraus einordnet, rät nur.","prueffrage":"Was an diesem Beitrag, außerhalb seines Wortlauts, würde etwas über die Absicht des Verfassers verraten?","rueckmeldung":[{"option":1,"text":"Echokammern gibt es, und sie verzerren manches Urteil über fremde Lager. Hier streiten aber beide Lager im selben Thread, und schon der fehlende Kontext erklärt die Unsicherheit. Dass Leser Fremdes „regelmäßig“ falsch einordnen, ist eine Zusatzannahme."},{"option":2,"text":"Nachschlagen klingt gründlich, bringt hier aber nichts: Dass Tauben keine Drohnen sind, gilt für Ernst und Scherz gleichermaßen. Das Ergebnis der Prüfung verrät also nichts über die Absicht des Verfassers."},{"option":3,"text":"Der Wahrheitseffekt ist ein bekannter Mechanismus, wirkt aber erst, wenn man dieselbe Aussage mehrfach liest. Im Szenario gibt es nur diesen einen Beitrag, und der Effekt erklärt ohnehin nur, was man für wahr hält, nicht ob etwas Satire ist."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Do we have something to learn from conspiracy theories? (w/ Peter McIndoe), Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"45f8e39e276afad2"}},{"id":"qx-b2-022","clusterId":"B","werkstueckRef":"B.22","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Aus der Größe der Menge folgt nicht, dass die Menschen glauben, was auf den Schildern steht; sie könnten mitspielen, der Auftritt allein beweist es nicht.","Aus der Größe der Menge folgt nicht, dass die Behauptung auf den Schildern stimmt; was viele vertreten, ist nicht deshalb wahr (Argumentum ad populum).","Die Zeitung gibt die Behauptung der Bewegung verzerrt wieder und widerlegt eine überzogene Fassung, statt die tatsächliche Aussage zu prüfen (Strohmann).","Die Zeitung schließt von den Teilnehmern einer Kundgebung auf die ganze Bevölkerung, obwohl Kundgebungsbesucher eine besondere Auswahl sind (Selektionsverzerrung)."],"correctIndex":0,"explanation":"Von außen sehen Ernst und Spiel gleich aus: Wer ein Schild hochhält, kann glauben, was darauf steht, oder die Rolle des Gläubigen bewusst spielen. Genau so war es bei der Bewegung „Birds Aren’t Real“: Ihr Gründer Peter McIndoe gab 2021 öffentlich zu, dass sie von Anfang an Satire war, und viele der jungen Leute auf den Kundgebungen kannten den Witz und spielten die Gläubigen nur. Wer allein aus Auftritt und Menge auf aufrichtigen Glauben schließt, behandelt eine Möglichkeit als Tatsache. Solange keine Hinweise auf die Absicht vorliegen, ist die ehrliche Antwort Unsicherheit und der nächste Schritt eine Prüfung des Kontexts.","coreRule":"⚡ Wo Satire und Ernst gleich klingen, entscheidet nur der Kontext der Absicht.","beleg":"Werkstück B.22 (Eingangsszene); Fn. gl-b-birds (Lorenz 2021, New York Times, 9.12.2021; McIndoe im TED-Podcast 24.07.2023; NPR 08.12.2023)","status":"entwurf","scenario":"Eine Bewegung behauptet auf Schildern, alle Vögel seien von der Regierung durch Überwachungsdrohnen ersetzt worden. Zu ihren Kundgebungen kommen Hunderte junge Leute. Eine Zeitung schreibt: „Hunderte Menschen glauben ernsthaft, dass es keine echten Vögel gibt. So weit ist der Verschwörungswahn gekommen.“","quote":"","quoteLabel":"","kurz":"Wer ein Schild hochhält, kann glauben, was darauf steht, oder den Gläubigen nur spielen; von außen sieht beides gleich aus. Die Zeitung behandelt eine Möglichkeit als Tatsache, statt zuerst den Kontext zu prüfen.","prueffrage":"Was genau hat die Zeitung gesehen, und was davon verrät, was in den Köpfen der Teilnehmenden vorgeht?","rueckmeldung":[{"option":1,"text":"Dass Verbreitung allein nichts beweist, stimmt. Die Zeitung hält die Behauptung aber gar nicht für wahr, sondern für Wahn. Ein Schluss von der Menge auf die Wahrheit liegt hier also nicht vor."},{"option":2,"text":"Ein Strohmann setzt eine verzerrte Wiedergabe voraus. Die Zeitung gibt die Behauptung der Schilder aber unverändert wieder. Der Fehler liegt woanders: im Schluss auf aufrichtigen Glauben."},{"option":3,"text":"Kundgebungsbesucher sind tatsächlich keine Zufallsauswahl. Die Zeitung spricht aber nur über die Teilnehmer und verallgemeinert nicht auf die Bevölkerung. Der Fehler liegt daher nicht in einer Verallgemeinerung."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Birds Aren't Real","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Birds_Aren%27t_Real","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Peter McIndoe, Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lorenz, T. (2021): Birds Aren't Real, or Are They? Inside a Gen Z Conspiracy Theory. The New York Times, 9.12.2021","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c4c10a47d7600b67"}},{"id":"qx-b2-023","clusterId":"B","werkstueckRef":"B.22","stufe":3,"question":"Ein Mitglied der Gruppe sagt: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Was ist an dieser Verteidigung als Beweis dafür, dass die Memes harmlos sind, fehlerhaft?","scenario":"In einer Online-Gruppe kursieren hasserfüllte Memes. Wird die Gruppe dafür kritisiert, heißt es regelmäßig: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Weitere Hinweise auf Ironie, etwa Übertreibung gegen die eigene Position oder eine erkennbare Pointe, gibt es nicht.","options":["Die Verteidigung stützt sich auf eine nicht prüfbare Selbstauskunft, die an der Wirkung nichts ändert: Die Botschaft verbreitet sich, die Verantwortung wird abgelehnt.","Die Verteidigung lenkt ab: Sie verweist auf Hassbeiträge anderer Gruppen, statt auf den Vorwurf einzugehen, dass die Memes der eigenen Gruppe Hass verbreiten.","Die Verteidigung beruft sich auf Gewohnheit: Solche Memes kursieren in der Gruppe schon seit Langem, und diese Gewohnheit ersetzt den Beleg, dass sie harmlos sind.","Die Verteidigung malt eine Gefahr aus: Wer die Memes kritisiere, wolle bald jeden Witz verbieten und die Meinungsfreiheit einschränken, und so weicht sie dem Vorwurf aus."],"correctIndex":0,"explanation":"Ob etwas Satire ist, entscheidet nicht die nachträgliche Behauptung des Absenders, sondern der Kontext und die erkennbare Absicht des Autors. Online fehlen Tonfall, Mimik und Körpersprache, deshalb sind Ironie und Ernst oft nicht zu trennen (Poe’s Law). Genau das lässt sich ausnutzen: Wer hasserfüllte Memes verbreitet und sich bei Kritik auf „nur ein Witz“ zurückzieht, normalisiert seine Ideologie und lehnt zugleich jede Verantwortung dafür ab. Satire ist ein gesundes Ventil und ein hochentwickeltes soziales Werkzeug, aber der Hinweis „nur ein Witz“ ersetzt weder Kontext noch erkennbare Absicht. Nützliche Prüffragen sind: Gibt es erkennbare Ironiesignale, etwa Emojis oder ein „/s“? Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Und was verrät der Kontext über die Absicht des Autors?","coreRule":"⚡ „War nur Spaß“ ist kein Beweis für Satire, sondern oft der Rückzugsraum für Ernst.","beleg":"Werkstück B.22 (Anwendung: politischer Extremismus & Trolle; Kipppunkt)","status":"entwurf","kurz":"„Nur ein Witz“ ist eine Selbstauskunft, die sich nicht prüfen lässt. Ob Satire vorliegt, zeigen Kontext und erkennbare Absicht, hier etwa fehlende Ironiesignale. Der Hinweis dient oft dazu, Verantwortung abzulehnen.","prueffrage":"Welche erkennbaren Signale im Meme selbst zeigen, dass der Autor die Aussage nicht ernst meint?","rueckmeldung":[{"option":1,"text":"Das Ablenken auf andere Gruppen ist tatsächlich eine bekannte Ausweichfigur. Hier kommt sie aber nicht vor: Das Mitglied sagt nur, es sei „ein Witz“ gewesen, und nennt keine anderen Gruppen."},{"option":2,"text":"Der Verweis auf Gewohnheit wäre ein Fehler, denn Dauer ersetzt keinen Beleg. Vorgebracht wird er hier aber nicht: Das Mitglied beruft sich allein darauf, es habe sich um einen Witz gehandelt."},{"option":3,"text":"Schreckbilder von Verboten und Zensur sind in Debatten verbreitet. Hier redet jedoch niemand von Verboten; es geht nur um die Behauptung „nur ein Witz“, und damit zugleich um die Frage, wer für die Wirkung der Memes einsteht."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"45754b5e38940047"}},{"id":"qx-b2-024","clusterId":"B","werkstueckRef":"B.22","stufe":4,"question":"Welches Vorgehen ist hier am sinnvollsten?","scenario":"Eine Kollegin teilt eine unglaubliche Schlagzeile: „Bericht: Bundesregierung will Schulpflicht durch freiwilliges Lernen per App ersetzen“. Du hältst es für einen Scherz, bist dir aber nicht sicher. Auf Nachfrage sagt sie nur: „Klingt doch total plausibel, oder?“","options":["Du wendest das Sparsamkeitsprinzip an: Ein Scherz erklärt die Schlagzeile über die Schulpflicht einfacher als ein echter Regierungsplan, und du stufst sie so ein.","Du prüfst Quelle, Kontext und mögliche Absicht der Schlagzeile und fragst dich, ob jemand das wirklich ernsthaft vertritt, bevor du dich festlegst.","Du bewertest, ob sich freiwilliges Lernen per App als Ersatz der Schulpflicht fachlich begründen lässt, und hältst die Schlagzeile für echt, wenn die Idee überzeugt.","Du leitest die Schlagzeile mit dem Vermerk „Quelle unklar“ an weitere Kollegen weiter, damit sie gemeinsam einordnen, ob die Regierung das wirklich plant."],"correctIndex":1,"explanation":"Ob ein Text ernst oder ironisch gemeint ist, lässt sich aus dem Inhalt allein oft nicht ablesen. Die Wirklichkeit des Extremismus und des Verschwörungsglaubens ist mitunter bizarrer als jede Parodie, und Satire-Seiten werden regelmäßig für echte Nachrichten gehalten. „Zu abwegig, um ernst zu sein“ ist deshalb kein sicherer Schluss. Verlässlich ist der Blick auf Quelle, Kontext und Absicht und die Frage, ob eine reale Gruppe genau das aufrichtig glaubt. Das Sparsamkeitsprinzip klingt vernünftig, setzt aber voraus, dass man Erklärungen an Belegen vergleichen kann, und die fehlen hier noch. Eine fachliche Begründung der Idee wirkt sorgfältig, sagt aber nichts darüber, ob jemand sie wirklich vertritt oder ob die Meldung echt ist; das ist eine Frage nach der Herkunft. Das Weiterleiten mit Vermerk wirkt vorsichtig, verbreitet die Schlagzeile aber, bevor die Frage geklärt ist.","coreRule":"⚡ Absurdität allein entscheidet nicht über Satire; Kontext und Quelle tun es.","quote":"Unabhängig davon, ob ich das persönlich für einen Witz halte: Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Bevor ich reagiere, sollte ich den Kontext und die Absicht des Autors prüfen.","quoteLabel":"Beispielgedanke:","beleg":"Werkstück B.22 (Anti-Denkmuster; Red Flags; Anwendung: Fake News & Satire)","status":"entwurf","kurz":"Ob eine Meldung ernst oder ironisch gemeint ist, verrät ihr Inhalt oft nicht, denn die Wirklichkeit ist mitunter bizarrer als jede Parodie. „Zu abwegig für echt“ ist daher kein sicherer Schluss; erst Quelle, Kontext und Absicht schaffen Klarheit.","prueffrage":"Woran hast du bisher festgemacht, dass es ein Scherz sein könnte, und wie sicher ist dieses Zeichen?","rueckmeldung":[{"option":0,"text":"Die einfachere Erklärung wirkt vernünftig, doch ein Vergleich von Erklärungen braucht Belege, und die fehlen noch. Außerdem ist „zu abwegig, um ernst zu sein“ kein sicherer Schluss: Manches Echte ist absurder als jede Parodie."},{"option":2,"text":"Ob die Idee fachlich überzeugt, ist eine sorgfältige Überlegung, beantwortet aber eine andere Frage. Sie sagt nichts darüber, ob die Meldung echt ist oder ob jemand das wirklich plant; das klärt nur der Blick auf die Herkunft."},{"option":3,"text":"Der Vermerk „Quelle unklar“ ist vorsichtig gemeint, trotzdem geht die Schlagzeile weiter, bevor geklärt ist, ob sie stimmt. Zuerst prüfen, dann teilen: Dann kann gemeinsames Einordnen auf einer tragfähigen Grundlage stattfinden."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4accf0b39ce4acfd"}},{"id":"qx-b2-025","clusterId":"B","werkstueckRef":"B.23","stufe":1,"question":"Welcher Denkfehler steckt im Schluss des Moderators?","options":["Er nimmt an, die Wahrheit liege in der Mitte, obwohl die beiden Seiten unterschiedlich gut belegt sind (Mittelweg-Trugschluss).","Er hält die Aussage der Ozeanografin allein wegen ihres Fachtitels für wahr, obwohl ein Titel noch kein Beleg ist (Autoritätsargument).","Er hält eine der Aussagen für wahr, weil viele Menschen sie glauben, obwohl Verbreitung nichts beweist (Appell an die Menge).","Er verzerrt die Aussagen beider Seiten zu angreifbaren Ersatzbehauptungen, die so niemand vertreten hat (Strohmann)."],"correctIndex":0,"explanation":"Die Ozeanografin stützt sich auf Messdaten, der Gast nur auf Internetrecherchen ohne belastbare Fakten. Der Moderator wendet eine Kompromiss-Heuristik an, die bei Geschmacksfragen oft taugt (Kino oder Theater? Dann eben ein gemeinsames Abendessen), und überträgt sie auf eine Tatsachenfrage. Die Realität ist aber nicht verpflichtet, zwischen einer belegten und einer unbelegten Aussage zu liegen. Wenn eine Seite erdrückende Belege hat und die andere keine, liegt die Wahrheit bei den Belegen, nicht in der Mitte.","coreRule":"⚡ Die Wahrheit liegt bei den Beweisen, nicht automatisch in der Mitte.","beleg":"Werkstück B.23 (Eingangsszene Ozean/Gin; Kernidee; Analyse; Fußnoten: keine). Frage vom Definitionsabruf zur Fehlererkennung am konkreten Fall umgebaut.","status":"entwurf","scenario":"In einer Podiumsdiskussion sagt eine Ozeanografin: „Nach allen verfügbaren Messdaten ist der Ozean mit Wasser gefüllt.“ Ein Gast widerspricht: „Nach meinen Recherchen im Internet ist der Ozean mit reinem Gin gefüllt.“ Der Moderator fasst zusammen: „Zwei extreme Positionen. Die Wahrheit liegt wohl in der Mitte. Der Ozean ist also eine Art verdünnter Martini.“","kurz":"Wo die eine Seite belegt ist und die andere nicht, liegt die Wahrheit bei den Belegen. Der Moderator übertrug einen Kompromiss, der bei Geschmacksfragen oft taugt, auf eine Tatsachenfrage, bei der die Realität nicht zwischen zwei Aussagen liegen muss.","prueffrage":"Worauf stützt sich jede der beiden Aussagen, und wie gut lässt sich das jeweils nachprüfen?","rueckmeldung":[{"option":1,"text":"Die Ozeanografin kommt im Schluss des Moderators vor, doch er ordnet ihre Aussage weder wegen ihres Titels als wahr ein noch bevorzugt er sie. Er setzt beide Seiten gleich. Das Problem liegt daher nicht in übertriebenem Vertrauen in einen Titel."},{"option":2,"text":"Davon, dass viele Menschen eine der Aussagen glauben, ist weder im Szenario noch im Schluss etwas zu finden. Der Moderator zählt keine Anhänger, er mittelt zwei Aussagen. Mit der Verbreitung einer Aussage hat sein Fehler nichts zu tun."},{"option":3,"text":"Ein absurdes Ergebnis wie „verdünnter Martini“ lässt vermuten, dass hier etwas verzerrt wurde. Der Moderator nennt beide Aussagen aber korrekt, als „zwei extreme Positionen“. Absurd wird erst sein Schluss daraus, nicht seine Wiedergabe."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harker, D. (2015): Creating Scientific Controversies: Uncertainty and Bias in Science and Society. Cambridge University Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"4b814bb555ef6789"}},{"id":"qx-b2-026","clusterId":"B","werkstueckRef":"B.23","stufe":2,"question":"Welches Vorgehen ist für beide Streitpunkte zusammen am sinnvollsten?","options":["Bei der Temperatur einigt ihr euch auf 20,5 Grad, und beim Dachfenster einigt ihr euch darauf, dass es wohl nur ein bisschen undicht ist.","Bei der Temperatur einigt ihr euch auf 20,5 Grad, und beim Dachfenster seht ihr beim nächsten Regen nach, ob wieder eine Pfütze entsteht.","Bei der Temperatur messt ihr, welcher Wert objektiv der richtige ist, und beim Dachfenster seht ihr beim nächsten Regen nach, ob es tropft.","Bei der Temperatur einigt ihr euch auf 20,5 Grad, und beim Dachfenster stimmt ihr zu dritt ab, ob es als dicht oder als undicht gelten soll."],"correctIndex":1,"explanation":"Bei der Temperatur geht es um Vorlieben: Lena friert schnell, Tom schwitzt schnell, und ihr habt ein gemeinsames Ziel, eine Wohnung, in der es allen erträglich ist. Dort ist ein Mittelweg wie 20,5 Grad tatsächlich eine gute, pragmatische Lösung. Ob das Dachfenster dicht ist, ist dagegen eine Tatsache. Sie lässt sich nicht aushandeln, sondern wird durch eine Beobachtung entschieden: Bildet sich beim nächsten Regen wieder eine Pfütze, ist es undicht. Die Mitte zwischen einer gut belegten Aussage (Lenas Pfütze) und einer unbelegten ist nicht automatisch wahr, denn die Wahrheit liegt dort, wo die Belege liegen. Sich auf „ein bisschen undicht“ zu einigen oder darüber abzustimmen, klingt friedlich, behandelt aber eine Tatsachenfrage wie eine Geschmacksfrage. Umgekehrt klingt Messen gründlich, doch für das Wohlbefinden zweier verschiedener Menschen gibt es keinen objektiv richtigen Wert, den ein Thermometer anzeigen könnte.","coreRule":"⚡ Kompromisse gehören in die Welt der Präferenzen, nicht in die Welt der Tatsachen.","beleg":"Werkstück B.23 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"Du wohnst mit Lena und Tom in einer Wohngemeinschaft. Lena friert schnell und will die Heizung auf 22 Grad, Tom schwitzt schnell und will 19 Grad. Außerdem behauptet Tom, das Dachfenster im Flur sei dicht, Lena dagegen hat nach dem letzten Regen eine Pfütze darunter gefunden. Heute Abend wollt ihr beide Streitpunkte klären.","quote":"","quoteLabel":"","kurz":"Bei der Temperatur geht es um Vorlieben, da ist ein Mittelweg wie 20,5 Grad gut. Ob das Fenster dicht ist, ist eine Tatsache und lässt sich nur durch Beobachtung klären. Der Fehler wäre, beides gleich zu behandeln.","prueffrage":"Handelt es sich bei jedem der beiden Streitpunkte um etwas, das sich durch Hinschauen entscheiden lässt, oder um etwas anderes?","rueckmeldung":[{"option":0,"text":"Ein Kompromiss wirkt hier fair, weil beide ein Stück nachgeben. Bei einer Tatsache ist die Mitte aber nicht automatisch wahr: Lenas Pfütze ist ein Beleg, Toms Aussage dagegen nicht, und „ein bisschen undicht“ klärt nichts."},{"option":2,"text":"Das Fenster so zu prüfen, ist genau richtig. Bei der Temperatur gibt es aber keinen objektiv richtigen Wert: Ein Thermometer zeigt nur, wie warm es ist, nicht, was für Lena und Tom angenehm ist."},{"option":3,"text":"Eine Abstimmung klingt gerecht und passt gut zu Geschmacksfragen. Ob Wasser durchkommt, hängt aber nicht von Mehrheiten ab, sondern davon, was man beim nächsten Regen beobachtet."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9d1dd88177caca55"}},{"id":"qx-b2-027","clusterId":"B","werkstueckRef":"B.23","stufe":3,"question":"In einer Schlichtung schlägt jemand vor: „Der Brandstifter will, dass das Haus brennt, die Feuerwehr will es löschen – einigen wir uns darauf, dass nur das halbe Haus abbrennt.“ Was ist an diesem Vorschlag das Kernproblem?","options":["Der Vorschlag lässt offen, wie die Einigung durchgesetzt wird: Ohne Kontrolle kann sich keine Seite darauf verlassen, dass die andere sie einhält.","Der Vorschlag tut so, als lägen beide Ziele auf derselben Waage, obwohl sie gegensätzlich sind: Das halbe Haus zu opfern wäre für eine Seite ein voller Sieg.","Der Vorschlag mittelt zwischen zwei Tatsachenbehauptungen, obwohl sich Tatsachen nicht aushandeln lassen: Ob etwas stimmt, entscheiden allein Belege.","Der Vorschlag übersieht ein Machtgefälle zwischen den Seiten: Die mächtigere könnte ihr Ziel auch ohne jede Einigung gegen die andere durchsetzen."],"correctIndex":1,"explanation":"Ein Kompromiss ist nur sinnvoll, wenn die Positionen symmetrisch genug sind. Hier sind die Ziele grundlegend asymmetrisch: Das eine Ziel ist, dass nichts brennt, das andere, dass es brennt. „Das halbe Haus“ klingt nach Mitte, wäre aber ein kompletter Sieg für den Brandstifter und eine komplette Niederlage für die Feuerwehr. Die Mitte zwischen zwei Positionen ist also nicht automatisch die vernünftigste Lösung, sondern kann ein Ergebnis sein, das nur einer Seite nützt. Man kann drei Arten von Asymmetrie unterscheiden: Fakten, Ziele und Macht. Vor einem Kompromiss lohnt die Prüfung, ob die Positionen symmetrisch genug sind.","coreRule":"⚡ Prüfe vor jedem Kompromiss, ob die Ziele überhaupt auf derselben Waage liegen.","beleg":"Werkstück B.23 (Das Problem der Asymmetrie; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Zwischen „es brennt“ und „es brennt nicht“ gibt es keine neutrale Mitte: Das halbe Haus wäre für den Brandstifter ein voller Sieg und für die Feuerwehr eine volle Niederlage. Ein Kompromiss trägt nur, wenn die Positionen symmetrisch genug sind.","prueffrage":"Was genau will die Feuerwehr erreichen, und was genau der Brandstifter?","rueckmeldung":[{"option":0,"text":"Ohne Kontrolle wäre eine Einigung tatsächlich brüchig, das ist eine berechtigte Sorge. Sie käme aber erst danach: Auch eine lückenlos eingehaltene Halbierung wäre ein Sieg des Brandstifters, der Fehler steckt schon im Vorschlag selbst."},{"option":2,"text":"Dass sich Tatsachen nicht aushandeln lassen, stimmt, passt hier aber nicht. Niemand streitet darüber, was der Fall ist, sondern darüber, was geschehen soll. Es treffen gegensätzliche Ziele aufeinander, keine widersprüchlichen Behauptungen über Fakten."},{"option":3,"text":"Ein Machtgefälle kann einen Kompromiss tatsächlich entwerten, im Szenario ist davon aber nichts zu lesen. Auch zwischen gleich starken Seiten bliebe der Vorschlag verzerrt, weil schon die Ziele nicht auf einer Skala liegen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"fe56b418f393c4fb"}},{"id":"qx-b2-028","clusterId":"B","werkstueckRef":"B.23","stufe":4,"question":"Was ist an dem Schluss der Zuschauerin fehlerhaft, und was hat die Sendung damit zu tun?","scenario":"Eine Talkshow lädt zur Klimafrage eine Klimawissenschaftlerin und einen Leugner ein, beide mit exakt gleichen Redeanteilen. Eine Zuschauerin sagt danach: „Dann liegt die Wahrheit wohl irgendwo dazwischen. Ganz so schlimm wird es nicht, aber ein bisschen was ist vielleicht dran.“","options":["Die Sendung lädt beide als gleichrangige Gäste ein, und die Zuschauerin folgt der Autorität, die ihr sympathischer ist (Autoritätsargument).","Die Sendung erzeugt den Anschein gleichwertiger Seiten, und die Zuschauerin löst die ungleiche Beweislage als Mittelweg auf (Mittelweg-Trugschluss).","Die Sendung lässt den Leugner neben der Wissenschaftlerin sprechen, und die Zuschauerin hält seine Behauptung für wahr, weil sie sie gehört hat (Wahrheitseffekt).","Die Sendung zeigt den Leugner als Außenseiter neben der Wissenschaftlerin, und die Zuschauerin lässt sich vom Mitleid mit ihm leiten (Appell an das Mitleid)."],"correctIndex":1,"explanation":"Die gleichwertige Darstellung beider Seiten erzeugt den Eindruck, beide Positionen stünden auf gleich festem Boden. Wer diesen Eindruck übernimmt, rechnet die Positionen zu einem „vernünftigen“ Kompromiss zusammen. Bei Tatsachenfragen gibt es aber keine Pflicht der Wirklichkeit, zwischen einer gut belegten Aussage und einer durch gar keine Beweise gestützten zu liegen. Der Schluss auf die Mitte ist hier ein Trugschluss, weil er die ungleiche Beweislage ignoriert. Und die Sendung hängt damit zusammen, weil die Darstellung als gleichwertig diesen Schluss nahelegt. Zugleich bleibt der Mittelweg bei Geschmacks- und Interessenfragen oft vernünftig. Entscheidend ist, die Positionen vorher nach Belegen zu gewichten, statt sie als gleichwertig zu behandeln. Die Orientierung an einer Autorität klingt plausibel, aber die Zuschauerin folgt keiner Seite, sondern bildet eine Mitte. Der Wahrheitseffekt ist ein echter Mechanismus, setzt aber häufige Wiederholung voraus, und die Zuschauerin übernimmt die Behauptung des Leugners ohnehin nicht, sondern mischt sie mit der anderen Seite. Mitleid mit einem Außenseiter kann Urteile färben, doch die Zuschauerin rechnet die beiden Aussagen zusammen, statt ihn zu stützen.","coreRule":"⚡ Gleich viel Redezeit heißt nicht gleich viel Belege.","beleg":"Werkstück B.23 (Anwendung: Journalismus; Verbindungen: Falsche Ausgewogenheit)","status":"entwurf","kurz":"Gleiche Redeanteile lassen beide Seiten gleich gut belegt wirken, und die Zuschauerin rechnet daraus eine Mitte. Bei Tatsachenfragen muss die Wahrheit aber nicht dazwischen liegen; man gewichtet die Seiten zuerst nach ihren Belegen.","prueffrage":"Wie viel Redezeit bekam jede Seite, und entspricht das dem Anteil der Fachleute, die jeweils so urteilen?","rueckmeldung":[{"option":0,"text":"Gleiche Redeanteile bedeuten tatsächlich, dass beide als gleichrangig auftreten. Die Zuschauerin folgt aber keiner der beiden Seiten, sie bildet eine Mitte; mit Sympathie für eine Autorität hat ihr Schluss nichts zu tun."},{"option":2,"text":"Der Wahrheitseffekt ist ein echter Mechanismus, wirkt aber vor allem bei häufiger Wiederholung. Hier gab es nur einen Auftritt, und die Zuschauerin übernimmt die Behauptung nicht, sondern mischt sie mit der Gegenseite zu einem Kompromiss."},{"option":3,"text":"Mitleid kann Urteile durchaus färben. Davon ist im Szenario aber nichts zu sehen: Beide Gäste haben gleiche Redeanteile, und die Zuschauerin stützt den Gast nicht, sondern rechnet zwei Aussagen zu einer Mitte zusammen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Northwestern University, SESP Magazine (Sommer 2022): The Perils of Bothsidesism","oeffentlich":true,"url":"https://sesp.northwestern.edu/magazine/summer-2022/the-perils-of-bothsidesism.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Imundo, M. N.; Rapp, D. N. (2022): When Fairness is Flawed: Effects of False Balance Reporting and Weight-of-Evidence Statements on Beliefs and Perceptions of Climate Change. Journal of Applied Research in Memory and Cognition","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d037a9bfe8da6fdd"}},{"id":"qx-b2-029","clusterId":"B","werkstueckRef":"B.24","stufe":1,"question":"Was ist an dieser Erklärung der Reporterin am ehesten fehlerhaft?","options":["Sie führt ein Geschehen mit vielen zusammenwirkenden Ursachen auf einen einzigen Schuldigen zurück und lässt die übrigen Faktoren unbeachtet (monokausaler Fehlschluss).","Sie schließt aus dem zeitlichen Zusammentreffen zweier Ereignisse auf einen ursächlichen Zusammenhang, ohne diesen zu prüfen (post hoc ergo propter hoc).","Sie hält ihre Erklärung allein deshalb für richtig, weil sich das Gegenteil nicht beweisen lässt, und verkehrt so die Beweislast (Argument aus Unwissenheit).","Sie beruft sich auf ihre Rolle als Reporterin und ersetzt damit die Prüfung der Belege durch die Autorität ihres Amtes (Autoritätsargument)."],"correctIndex":0,"explanation":"Ein Unglück wie dieses entsteht in der Regel aus dem Zusammenspiel vieler Faktoren: Materialermüdung, Belastung, Wartung und Wetter greifen ineinander. Die Reporterin reduziert das auf einen einzigen Bösewicht. Das ist leicht zu erzählen und emotional befriedigend, blendet aber alle übrigen Beiträge aus und führt zu einer scheinbar einfachen Lösung, nämlich den Bauleiter auszutauschen. Bleiben Materialermüdung und mangelnde Wartung bestehen, kann die nächste Brücke genauso versagen. Dass der Bauleiter einen Anteil gehabt haben kann, ist damit nicht ausgeschlossen. Der Fehler liegt darin, ihn zur alleinigen Ursache zu erklären.","coreRule":"⚡ Wo viele Faktoren zusammenwirken, ist die Erklärung mit einem einzigen Schuldigen verdächtig. Frag dich: Welche weiteren Faktoren könnten beigetragen haben?","beleg":"Werkstück B.24 (Kernidee; Analyse)","status":"entwurf","scenario":"Nach dem Einsturz einer Brücke sagt eine Reporterin im Fernsehen: „Die Wahrheit ist ganz einfach: Der Bauleiter hat geschlampt, er ist an allem schuld.“ Ein Gutachten nennt zugleich mehrere Faktoren: ein Baumaterial, das über Jahre ermüdet ist, eine Überlastung durch Schwerverkehr, aufgeschobene Wartungsarbeiten und ungewöhnlich starke Regenfälle.","kurz":"Ein Einsturz entsteht meist aus dem Zusammenspiel mehrerer Faktoren, hier Materialermüdung, Belastung, Wartung und Wetter. Die Aussage macht daraus eine einzige Ursache und blendet den Rest aus, obwohl der Bauleiter durchaus einen Anteil gehabt haben kann.","prueffrage":"Wie viele Faktoren nennt das Gutachten, und wie viele davon kommen in der Erklärung der Reporterin vor?","rueckmeldung":[{"option":1,"text":"Post hoc setzt voraus, dass zwei Ereignisse zeitlich zusammenfallen und daraus ein Zusammenhang gefolgert wird. Davon steht in der Aussage nichts: Sie verknüpft keine Ereignisse, sondern nennt einfach eine einzige Ursache."},{"option":2,"text":"Ein Argument aus Unwissenheit würde sich auf fehlende Widerlegung stützen. Die Reporterin begründet aber gar nichts damit, sie behauptet nur. Das Gutachten liefert sogar Gegenbelege, die ihre Aussage übergeht."},{"option":3,"text":"Ihre Rolle als Reporterin dient im Satz nicht als Begründung; sie beruft sich weder auf ein Amt noch auf besondere Sachkenntnis. Die Schwäche liegt im Inhalt der Aussage selbst, nicht darin, wer sie äußert."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"165b782131a62080"}},{"id":"qx-b2-030","clusterId":"B","werkstueckRef":"B.24","stufe":2,"question":"Welches Merkmal des Prospekts ist das deutlichste Warnzeichen für eine unzulässige Vereinfachung?","scenario":"Ein Prospekt erklärt: „Fast alle Krankheiten haben eine Wurzel: Schlacken im Darm. Unsere Detox-Kur beseitigt sie.“","options":["Der Prospekt nennt keine Studie, die zeigt, dass die Detox-Kur die Schlacken im Darm beseitigt, und die Aussage bleibt so eine unbelegte Behauptung.","Der Anbieter verdient am Verkauf der Detox-Kur gegen die Schlacken im Darm, und seine Darstellung ist deshalb vermutlich einseitig.","Sehr verschiedene Krankheiten werden auf eine einzige Wurzelursache zurückgeführt, und dafür wird eine ebenso einfache Lösung verkauft.","Der Prospekt sagt nicht, woran man erkennt, dass die Kur die Schlacken beseitigt hat, und die Aussage lässt sich so nie widerlegen."],"correctIndex":2,"explanation":"Krankheiten haben sehr verschiedene, oft mehrere zusammenwirkende Ursachen. Dass eine einzige „Wurzelursache“ fast alle erklären soll, ist ein typischer monokausaler Fehlschluss. Verdächtig wird es zusätzlich, wenn die Lösung genauso einfach ist wie die Ursache und genau das Produkt ist, das der Prospekt verkauft. Die Reduktion eines vielfältigen Problems auf ein einfaches Ziel ist ein Muster, das man bei komplexen Themen immer prüfen sollte.","coreRule":"⚡ Eine Ursache und eine Lösung, beide ganz einfach: bei komplexen Problemen ein Warnsignal.","beleg":"Werkstück B.24 (Anwendung: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Sehr verschiedene Krankheiten haben meist verschiedene, oft mehrere zusammenwirkende Ursachen. Eine einzige „Wurzel“ für fast alle samt passender Einfachlösung ist ein typischer monokausaler Fehlschluss, hier genau beim Produkt des Anbieters.","prueffrage":"Welche Aussage des Prospekts müsste am stärksten belegt sein, damit die Kur hält, was sie verspricht?","rueckmeldung":[{"option":0,"text":"Fehlende Belege sind bei Werbung ein berechtigtes Warnzeichen. Sie sagen aber nichts darüber, ob ein vielfältiges Problem auf eine einzige Ursache verkürzt wird, und genau danach fragt die Aufgabe."},{"option":1,"text":"Wer am Verkauf verdient, stellt sein Produkt oft einseitig dar, und das rät zur Vorsicht. Das betrifft aber den Interessenkonflikt, nicht die Vereinfachung selbst; sie wäre auch ohne Verkaufsabsicht ein Fehlschluss."},{"option":3,"text":"Eine Behauptung, deren Erfolg sich nicht überprüfen lässt, ist ein ernstes Warnzeichen für Unwiderlegbarkeit. Das ist aber ein anderes Problem als die Verkürzung vieler verschiedener Krankheiten auf eine einzige Ursache."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (National Center for Complementary and Integrative Health): Detoxes and Cleanses: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b131be5008d46ee2"}},{"id":"qx-b2-031","clusterId":"B","werkstueckRef":"B.24","stufe":3,"question":"Nach einem Schiffsunglück zeigt eine Untersuchung mehrere zusammenwirkende Ursachen: einen starken Sturm, einen unentdeckten Haarriss im Rumpf, eine Fehlentscheidung des Kapitäns unter Druck, eine unzureichend geschulte Crew und veraltete Rettungsboote. Ein Reeder kündigt an, nur den Kapitän zu entlassen, und erklärt: „Damit ist das Problem gelöst.“ Warum ist dieser Schluss riskant?","options":["Weil die übrigen Ursachen wie Haarriss und Crew weiter bestehen und das nächste Schiff gefährden, selbst wenn der Kapitän ersetzt wird.","Weil die Untersuchung nur dieses eine Unglück erfasst, reicht ihr Befund zu Sturm und Rumpfschaden nicht als Beleg (zu kleine Stichprobe).","Weil der Reeder nur deshalb auf den Kapitän schließt, weil dessen Fehlentscheidung dem Unglück vorausging (Post-hoc-Fehlschluss).","Weil der Reeder dem Kapitän eine böse Absicht unterstellt, obwohl sich aus einer Fehlentscheidung unter Druck kein Vorsatz ableiten lässt."],"correctIndex":0,"explanation":"Der Reeder greift aus mehreren zusammenwirkenden Ursachen eine einzige heraus und behandelt sie als die Lösung. Wer nur dieses einfache Ziel bekämpft, lässt die übrigen Ursachen unangetastet: den Haarriss im Rumpf, die schlecht geschulte Crew, die veralteten Rettungsboote. Das nächste Schiff trägt dann dieselben Risiken. Bei einfachen, technischen Problemen wie einem Wackelkontakt ist die Suche nach der einen Ursache dagegen oft richtig; bei komplexen Systemen mit vielen zusammenwirkenden Faktoren führt sie in die Irre. Eine gute Prüffrage lautet: Welche fünf weiteren, vielleicht weniger offensichtlichen Faktoren könnten ebenfalls zu diesem Ergebnis beigetragen haben? Der Einwand der kleinen Stichprobe ist sonst berechtigt, doch hier hat die Untersuchung die Ursachen an diesem einen Unglück unmittelbar festgestellt. Ein Post-hoc-Fehlschluss liegt nicht vor, denn die Fehlentscheidung gilt in der Untersuchung als eine der Ursachen und wird nicht nur aus der zeitlichen Abfolge geschlossen. Eine Unterstellung böser Absicht ist ein verbreiteter Fehler, aber der Reeder spricht nirgends von Vorsatz.","coreRule":"⚡ Wer nur den Sündenbock behandelt, lässt die Ursachen des Problems unangetastet.","beleg":"Werkstück B.24 (Das Geheimnis des Schiffsunglücks; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Reeder greift aus mehreren zusammenwirkenden Ursachen eine einzige heraus. Haarriss, schlecht geschulte Crew und veraltete Rettungsboote bleiben bestehen, und das nächste Schiff trägt dieselben Risiken, selbst mit neuem Kapitän.","prueffrage":"Welche Faktoren, die nichts mit dem Kapitän zu tun haben, tauchen im Untersuchungsbericht noch auf?","rueckmeldung":[{"option":1,"text":"Ein einzelnes Unglück als Datenbasis weckt schnell den Verdacht, es sei zu wenig. Hier hat die Untersuchung die Ursachen aber direkt an diesem Fall festgestellt, sie schließt nicht von wenigen Fällen auf eine allgemeine Regel."},{"option":2,"text":"Wer nur nach der zeitlichen Abfolge urteilt, kann tatsächlich in die Irre gehen. Die Untersuchung führt die Fehlentscheidung aber ausdrücklich als eine der Ursachen auf. Der Kapitän gehört dazu, das Problem liegt darin, ihn allein zu nehmen."},{"option":3,"text":"Dass eine Fehlentscheidung unter Druck noch keinen Vorsatz belegt, stimmt. Der Reeder unterstellt aber nirgends eine böse Absicht. Sein Fehler liegt darin, aus mehreren Ursachen nur eine herauszugreifen."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6fee3d5e5dc2879f"}},{"id":"qx-b2-032","clusterId":"B","werkstueckRef":"B.24","stufe":4,"question":"Welche Prüfung wendest du auf diese Slogans an?","scenario":"Im Wahlkampf heißt es: „Warum geht es uns schlecht? Wegen der Milliardäre!“ Das gegnerische Lager antwortet mit ebenso einfachen Parolen über eine andere Gruppe.","options":["Beide Parolen beziffern den Schaden der Milliardäre bzw. der anderen Gruppe mit scheinbar genauen Zahlen; prüfe, woher diese Zahlen stammen und wie sie berechnet wurden.","Beide Parolen legen den Milliardären bzw. der anderen Gruppe Sätze in den Mund; prüfe, in welchem Zusammenhang diese gefallen sind und ob das Zitat vollständig ist.","Beide Parolen versprechen, dass es uns nach dem Wahlsieg des eigenen Lagers besser geht; prüfe, wie verlässlich solche Versprechen früher eingetroffen sind.","Beide Parolen machen eine einzige Gruppe, die Milliardäre bzw. die andere, zum Schuldigen; frag, welche weniger offensichtlichen Faktoren noch mitgewirkt haben könnten."],"correctIndex":3,"explanation":"Beide Slogans haben denselben Fehler: Ein vielschichtiges Problem wie wirtschaftliche Not hat selten eine einzige Ursache, sondern entsteht aus dem Zusammenspiel vieler Faktoren. Eine Parole, die eine einzige Gruppe als Schuldige benennt, ist eingängig und emotional befriedigend, aber gerade deshalb verdächtig. Die richtige Prüfung fragt unabhängig von der politischen Richtung, welche weiteren, weniger offensichtlichen Faktoren mitgewirkt haben könnten. Einzelne Akteure können tatsächlich zu einem Problem beitragen, nur selten allein. Die Prüfung von Zahlen ist bei Parolen oft sinnvoll, hier nennt aber keine Parole eine Zahl, deren Herkunft sich klären ließe. Der Vergleich mit dem Originalzusammenhang hilft bei verkürzten Zitaten, doch hier wird niemand zitiert. Die Prüfung früherer Prognosen lohnt bei Versprechen, aber die Parolen sagen nichts über die Zukunft, sie benennen nur Schuldige.","coreRule":"⚡ Eine Erklärung wird nicht dadurch besser, dass sie einen klaren Schuldigen anbietet.","beleg":"Werkstück B.24 (Anwendung: In der Politik; Anti-Denkmuster: Aktivierungs-Frage), keine Fußnoten","status":"entwurf","kurz":"Wirtschaftliche Not hat selten nur eine Ursache, sondern entsteht aus dem Zusammenspiel vieler Faktoren. Wer eine einzige Gruppe zum Schuldigen erklärt, bietet eine eingängige Antwort, und genau das macht sie verdächtig, egal aus welchem Lager.","prueffrage":"Was wäre in den Slogans eigentlich zu erklären, und wie viele Ursachen kommen darin vor?","rueckmeldung":[{"option":0,"text":"Zahlen zu hinterfragen, ist bei Parolen oft klug. Hier gibt es aber nichts zu klären: Keine der beiden Parolen nennt eine Zahl, sie benennen nur eine Schuldige oder einen Schuldigen."},{"option":1,"text":"Bei verkürzten Zitaten lohnt der Blick auf den Zusammenhang. In diesem Szenario wird aber niemand zitiert, die Parolen behaupten nur eine Schuld. Die Prüfung läuft ins Leere."},{"option":2,"text":"Versprechen auf ihre frühere Verlässlichkeit zu prüfen, ist sinnvoll, wenn welche gemacht werden. Die Parolen sagen aber nichts über die Zeit nach der Wahl, sie weisen nur Schuld zu."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2d780cb6573b81cd"}},{"id":"qx-b2-033","clusterId":"B","werkstueckRef":"B.25","stufe":1,"question":"Welche Frage hilft dir am besten zu erkennen, ob du deine Denkwerkzeuge gerade als Späher oder als Soldat einsetzt?","options":["Habe ich die Denkfehler meines Gegenübers korrekt benannt, und lassen sich meine Einwände zum Gesundheitsthema fachlich belegen?","Wie überzeugend wirken meine Einwände auf Dritte, die die Diskussion zum Gesundheitsthema mitlesen, und bleibe ich dabei sachlich?","Welche Beobachtung zum Gesundheitsthema würde mich dazu bringen, meine eigene Einschätzung zu ändern, und habe ich danach gesucht?","Habe ich mich vor der Diskussion über das Gesundheitsthema in aktuelle Studien eingelesen, damit meine Einwände belastbar sind?"],"correctIndex":2,"explanation":"Dieselben Werkzeuge (Recherche, Logik, Befragung) können der Wahrheitssuche dienen oder dem Gewinnen um jeden Preis. Zwei Anwälte mit identischem Handwerk zeigen das: Anwalt A sammelt auch die Fakten, die seinem Mandanten schaden, baut den stärksten Fall der Gegenseite, um Schwachstellen zu finden, und ist bereit, seine Strategie bei widersprüchlichen Beweisen anzupassen. Anwalt B sucht nur Munition für seine vorgefasste Schlussfolgerung. Wer prüft, welche Beobachtung ihn umstimmen würde und ob er danach gesucht hat, testet genau diese Offenheit für Gegenbeweise; das ist die Haltung des Spähers. Dass du Denkfehler kennst, macht dich noch nicht zum Wahrheitssucher. Entscheidend ist, wofür du die Werkzeuge einsetzt und ob du sie auch auf dich selbst anwendest. Die Frage nach korrekt benannten Denkfehlern prüft die Treffsicherheit deiner Einwände, nicht dein Ziel; auch ein Soldat kann richtig liegen. Die Wirkung auf Mitlesende und der sachliche Ton betreffen die Außenwirkung, nicht die Offenheit für Gegenbeweise. Die Vorbereitung mit Studien kann Soldat wie Späher dienen und zeigt erst durch das Ziel, was sie ist.","coreRule":"⚡ Werkzeuge des Denkens sind neutral: Entscheidend ist, ob du sie auch gegen deine eigene Position richtest.","beleg":"Werkstück B.25 (Eingangsszene; Kernidee); Fn. gl-b-galef (Galef, TEDxPSU 2016; The Scout Mindset 2021)","status":"entwurf","scenario":"Du hast dich intensiv mit logischen Fehlschlüssen beschäftigt. In einer Diskussion über ein Gesundheitsthema fällt dir auf, dass du vor allem darauf achtest, wo dein Gegenüber einen Denkfehler macht. Dein Ziel ist es, die Diskussion zu gewinnen.","kurz":"Entscheidend ist, ob eine Beobachtung dich umstimmen könnte und ob du nach ihr gesucht hast. Wer nur prüft, ob seine Einwände stimmen, testet die Treffsicherheit, nicht das Ziel: Auch ein Soldat kann richtig liegen.","prueffrage":"Worauf achtest du in dieser Diskussion bisher vor allem, und was soll am Ende dabei herauskommen?","rueckmeldung":[{"option":0,"text":"Treffsichere, belegbare Einwände sind wichtig. Sie sagen aber nur, ob du richtig liegst, nicht wozu du deine Werkzeuge einsetzt: Auch jemand, der nur gewinnen will, kann mit seinen Einwänden recht haben."},{"option":1,"text":"Sachlichkeit und Überzeugungskraft sind sinnvolle Ziele. Sie betreffen jedoch die Außenwirkung. Wer gewinnen will, fragt genauso, und über deine Offenheit für Gegenbeweise sagt das nichts."},{"option":3,"text":"Gute Vorbereitung macht Einwände belastbarer. Dasselbe Einlesen kann aber der Wahrheitssuche dienen oder nur Munition für eine feste Schlussfolgerung liefern; erst das Ziel zeigt, was es ist."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"b351833e1ea4f481"}},{"id":"qx-b2-034","clusterId":"B","werkstueckRef":"B.25","stufe":2,"question":"Welche Haltung zeigt sich in dieser Selbstbeobachtung, und was folgt daraus?","scenario":"Du merkst: In Online-Debatten freust du dich vor allem, wenn du den Gegner „besiegt“ hast. Dein Wissen über Denkfehler nutzt du vor allem, um andere zu katalogisieren und abzuwerten. Deine wichtigen Meinungen hast du trotz ständigen Debattierens lange nicht mehr geändert.","options":["Du verteidigst eine feste Position: Das Wissen dient dem Gewinnen und dem Status, und die Gefahr, selbstgerecht zu werden, ist bereits nahe.","Du kartierst die Wirklichkeit sorgfältig: Dass du deine Meinung lange nicht geändert hast, zeigt, dass deine Sicht offenbar stimmt.","Du suchst nach der Wahrheit: Indem du die Fehler anderer sammelst, bleibst du in deinem eigenen Urteil beweglich.","Du schützt dich zu Recht vor Desinformation: Das Abwerten anderer ist eine gesunde Strategie, um klar zu denken."],"correctIndex":0,"explanation":"Wer sich über das Besiegen anderer freut, sein Wissen über Denkfehler vor allem zum Abwerten nutzt und trotz ständiger Debatten nie umdenkt, setzt Werkzeuge des kritischen Denkens als Waffen ein, nicht als Instrumente der Selbstkorrektur. Dass man trotz ständigen Debattierens lange keine wichtige Meinung aufgrund neuer Beweise geändert hat, ist ein Warnzeichen für die Soldaten-Mentalität. Eine lange unveränderte Meinung ist also kein Beleg dafür, dass die eigene Sicht stimmt. Kippt die Liebe zum Recht-Haben über die Liebe zur Wahrheit, wird aus dem Skeptiker ein Dogmatiker mit schärferem Schwert.","coreRule":"⚡ Frag dich bei jedem Denkwerkzeug: Setze ich es ein, um die Wahrheit zu finden, oder um recht zu behalten?","quote":"Benutze ich dieses Werkzeug wie ein Späher oder wie ein Soldat?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.25 (Red Flags; Kipppunkt; Anti-Denkmuster)","status":"entwurf","kurz":"Wer sich über Siege freut, Denkfehler vor allem bei anderen sucht und sich selbst nie korrigiert, nutzt Wissen als Waffe statt als Werkzeug. Dass die eigene Meinung lange gleich blieb, beweist nicht, dass sie stimmt.","prueffrage":"Wie oft hat eine deiner vielen Debatten in letzter Zeit eine deiner wichtigen Meinungen tatsächlich verändert?","rueckmeldung":[{"option":1,"text":"Eine Sicht kann stimmen, ohne dass man sie je ändern musste. Dass sie sich trotz ständigen Debattierens lange nicht verschoben hat, ist aber kein Beleg dafür, sondern passt eher zu einem Verteidigen als zu einem sorgfältigen Prüfen."},{"option":2,"text":"Das Ideal der Wahrheitssuche ist richtig. Fehler anderer zu sammeln zeigt aber nur auf andere und hält das eigene Urteil nicht beweglich; Beweglichkeit zeigt sich darin, dass man tatsächlich umdenkt, und genau das fehlt hier seit Langem."},{"option":3,"text":"Sich vor Desinformation zu schützen ist ein legitimes Ziel. Hier geht es aber um Freude am Besiegen und um Abwerten, und das dient dem Status, nicht dem klaren Denken, das beim Prüfen der eigenen Urteile beginnt."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"252153cc9fdf2905"}},{"id":"qx-b2-035","clusterId":"B","werkstueckRef":"B.25","stufe":4,"question":"Wie gehst du mit diesem Gesprächspartner am besten um?","scenario":"In einem Forum fordert jemand eine „offene Debatte“ zu einer Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde. Er lügt dabei systematisch, stellt deine Argumente verzerrt als Strohmänner dar und besteht darauf, du müsstest als Skeptiker offen bleiben.","options":["Du führst die Debatte so lange weiter, bis er seinen Irrtum öffentlich einräumt und dir in der Sache recht gibt.","Du prüfst die Behauptung immer wieder neu und offen, weil Skepsis verlangt, jede Idee ständig zu hinterfragen.","Du stellst fest, dass er sich nicht an die Bedingungen einer ehrlichen Auseinandersetzung hält, und steigst aus der Debatte aus.","Du bietest einen Mittelweg an, bei dem beide Seiten gleich viel nachgeben und sich in der Mitte treffen."],"correctIndex":2,"explanation":"Offenheit heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde, verdient keine erneute offene Prüfung: Eine erneute „offene“ Debatte darüber verschwendet Zeit und ist eine Form der falschen Ausgewogenheit. Wer zudem systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, sondern gewinnen. Hier ist die „offene“ Fortführung der Debatte keine Tugend, sondern Selbstschädigung; darum greift die Ausstiegs-Strategie. Auch ein Mittelweg löst das Problem nicht, denn dein Gegenüber sucht gar nicht die Wahrheit. Der Ausstieg ist daher kein Akt der Engstirnigkeit, sondern eine begründete Entscheidung, die deine Energie schützt.","coreRule":"⚡ Offenheit heißt, Behauptungen ernsthaft zu prüfen, nicht, jedem Debattenpartner unbegrenzt Zeit und Aufmerksamkeit zu schenken.","beleg":"Werkstück B.25 (Die Grenzen der Offenheit; Anti-Denkmuster)","status":"entwurf","kurz":"Eine längst widerlegte Behauptung verdient keine erneute „offene“ Prüfung, und wer systematisch lügt und Strohmänner baut, will gewinnen statt klären. Offenheit heißt nicht, um jeden Preis weiterzudiskutieren; der Ausstieg ist begründet.","prueffrage":"Was ist über die Behauptung selbst längst geklärt, und was hat er bisher mit deinen Argumenten gemacht?","rueckmeldung":[{"option":0,"text":"Hartnäckigkeit klingt nach Standhaftigkeit. Wer aber systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, und wird kaum einlenken. Du würdest nur Zeit und Kraft in eine Debatte stecken, die nicht auf Klärung zielt."},{"option":1,"text":"Skepsis heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine längst widerlegte Behauptung immer wieder neu zu öffnen, wäre falsche Ausgewogenheit und keine Offenheit."},{"option":3,"text":"Ein Mittelweg ist oft ein guter Ausgleich, wenn Interessen gegeneinanderstehen. Bei einer Tatsachenfrage gibt es aber keine Mitte zwischen widerlegt und nicht widerlegt. Außerdem sucht dein Gegenüber gar keine Lösung, sondern will gewinnen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2019): A dangerous balancing act. EMBO Reports 20(8), e48706","oeffentlich":true,"doi":"10.15252/embr.201948706","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6680130/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schmid, P.; Schwarzer, M.; Betsch, C. (2020): Weight-of-Evidence Strategies to Mitigate the Influence of Messages of Science Denialism in Public Discussions. Journal of Cognition 3(1), 36","oeffentlich":true,"doi":"10.5334/joc.125","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7528676/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"070df7c706860229"}},{"id":"qx-b2-036","clusterId":"B","werkstueckRef":"B.25","stufe":3,"question":"Was erklärt dieses Verhalten am besten?","scenario":"Jemand wirft in Online-Diskussionen ständig anderen „Strohmann“ und „Zirkelschluss“ vor und kennt viele Fachbegriffe für Denkfehler. Wird aber seine eigene Lieblingsthese kritisiert, tauchen dieselben Fehler in seinen Antworten auf. Er hat seine Ansicht seit Jahren nicht korrigiert, obwohl er täglich debattiert.","options":["Er setzt sein Wissen über Denkfehler als Waffe gegen andere ein, um seine vorgefasste Meinung zu verteidigen, statt es zur Selbstkorrektur zu nutzen.","Er passt sich dem Meinungsklima seiner Online-Gruppe an, um dazuzugehören, und übernimmt seine Lieblingsthese deshalb ungeprüft von ihr.","Er misstraut jeder Behauptung gleichermaßen, auch seinen eigenen, und hält Strohmann und Zirkelschluss überall für möglich, ohne sich festzulegen.","Er bewegt sich in einer Echokammer, in der nur Zustimmung vorkommt, und hört seit Jahren keine Gegenargumente zu seiner Lieblingsthese."],"correctIndex":0,"explanation":"Der bloße Besitz von Denkwerkzeugen macht niemanden zum wahrheitssuchenden Denker. Die Julia Galef zugeschriebene Unterscheidung beschreibt es so: Wer in der Soldaten-Mentalität denkt, will eine Position verteidigen und nutzt sein Wissen als Waffe. Wer in der Späher-Mentalität denkt, will herausfinden, was tatsächlich stimmt, und prüft zuerst sich selbst. Hier zeigen drei Signale die Soldaten-Haltung: Die Fehlerjagd richtet sich nur nach außen, die eigene These bleibt unangetastet, und trotz täglicher Debatten hat sich über Jahre nichts geändert. Auch kluge Verschwörungsgläubige sind ein typisches Beispiel: Sie werfen anderen Fehlschlüsse vor und begehen dieselben selbst. Das Ziel entscheidet, ob die Werkzeuge der Wahrheit oder der Verteidigung dienen. Die Anpassung an eine Gruppe ist ein bekannter Mechanismus, doch von einer Gruppe, der er gefallen will, ist keine Rede. Allgemeines Misstrauen wäre eine mögliche Haltung, passt aber nicht zu jemandem, der seine eigene These hartnäckig verteidigt. Eine Echokammer erklärt fehlende Gegenargumente, aber er debattiert täglich und trifft dort auf Kritik an seiner These.","coreRule":"⚡ Wissen über Denkfehler schützt nicht vor ihnen; es verpflichtet zur Selbstprüfung.","beleg":"Werkstück B.25 (Anwendung: Verschwörungs-„Forscher“; Kipppunkt)","status":"entwurf","kurz":"Er nutzt sein Wissen über Denkfehler als Waffe, um seine These zu verteidigen, statt sie damit zu prüfen. Der naheliegende Fehler: Wer viele Fachbegriffe kennt, gilt schnell als guter Denker, doch das Ziel entscheidet, wem die Werkzeuge dienen.","prueffrage":"Gegen wen richtet er seine Fehlervorwürfe, und was hat sich nach Jahren täglicher Debatten an seiner eigenen Ansicht verändert?","rueckmeldung":[{"option":1,"text":"Gruppendruck kann Meinungen tatsächlich festigen. Im Szenario steht aber nichts von einer Gruppe, der er gefallen will, und der Gruppenzwang erklärt nicht, warum er Fehlerbegriffe nur gegen andere einsetzt."},{"option":2,"text":"Wer jede Behauptung für fehlerhaft hält, wirkt gründlich. Er verteidigt seine eigene These aber hartnäckig und legt sich dort fest, prüft also gerade nicht alle Behauptungen gleich streng."},{"option":3,"text":"Eine Echokammer erklärt fehlende Gegenargumente, und das klingt nach Jahren ohne Meinungsänderung stimmig. Hier fehlt die Kritik aber nicht: Er debattiert täglich, seine These wird angegriffen, und er wehrt sie mit denselben Fehlern ab."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519","oeffentlich":false,"doi":"10.1037/a0028857"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2ea3d617699e9904"}},{"id":"qx-b2-037","clusterId":"B","werkstueckRef":"B.26","stufe":1,"question":"Was ist die sinnvollste Reaktion auf diesen Impuls?","scenario":"Beim Kauf von Konzerttickets blinkt ein roter Balken: „Nur noch 17 Tickets verfügbar! 250 Leute sehen sich dieses Angebot gerade an!“ Du wolltest eigentlich noch ein paar Tage überlegen, ob du hingehst. Jetzt schlägt dein Herz schneller, und du spürst den Impuls, sofort zu bestellen.","options":["Die 250 Interessenten als Hinweis nehmen, dass sich das Konzert lohnt, und bestellen, bevor die letzten 17 Tickets weg sind.","Innehalten und prüfen, ob dich der blinkende Balken oder der Wert des Konzerts antreibt, und erst danach entscheiden, ob du bestellst.","Deinem schnellen Herzschlag trauen, der zeigt, wie sehr du dieses Konzert willst, und sofort bestellen, solange es Tickets gibt.","Nachprüfen, ob wirklich nur noch 17 Tickets übrig sind, und bei echter Knappheit bestellen, weil sie zeigt, dass das Konzert begehrt ist."],"correctIndex":1,"explanation":"„Nur noch 17“ (Knappheit) und „250 Leute sehen sich das gerade an“ (sozialer Beweis) sagen nichts darüber, ob das Konzert dir das Geld wert ist. Sie erzeugen Zeitdruck und sollen die ruhige Abwägung umgehen. Seltenes wirkt automatisch wertvoller, und was viele wollen, wirkt automatisch richtig, auch wenn beides über den eigentlichen Wert nichts verrät. Der Impuls ist ein Warnsignal, kein Argument. Sinnvoll ist, ihn zu bemerken und gezielt zu fragen: Will ich das, weil ich den Wert verstanden habe, oder nur, weil ich Angst habe, es zu verpassen?","coreRule":"⚡ „Nur noch wenige“ und „viele schauen gerade“ sind Druckmittel, keine Informationen über den Wert. Prüfe, was dich antreibt, bevor du entscheidest.","beleg":"Werkstück B.26 (Eingangsszene Situation B; Analyse: drei Heuristiken; Anwendung: Alltag & Konsum)","status":"entwurf","kurz":"Der Balken erzeugt Zeitdruck, sagt aber nichts darüber, ob dir das Konzert sein Geld wert ist. Der Fehler: Seltenes und Begehrtes wirkt automatisch wertvoll. Erst den Impuls bemerken, dann fragen, ob dich der Wert oder die Angst, etwas zu verpassen, antreibt.","prueffrage":"Was verraten dir die beiden Zahlen im roten Balken über das Konzert selbst?","rueckmeldung":[{"option":0,"text":"250 Ansehende wirken wie ein Qualitätszeichen. Sie sehen aber nur auf dasselbe Angebot und urteilen nicht unabhängig, sodass die Zahl über den Wert des Konzerts nichts verrät."},{"option":2,"text":"Der Herzschlag fühlt sich wie echtes Wollen an. Hier hat ihn aber der Balken ausgelöst, er ist ein Warnsignal und kein Argument dafür, dass dir das Konzert den Preis wert ist."},{"option":3,"text":"Die Zahl nachzuprüfen ist sorgfältig und besser als blindes Vertrauen. Doch auch echte Knappheit sagt nichts darüber, ob das Konzert den Preis wert ist, und eigentlich wolltest du erst überlegen, ob du hingehst."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22, 37","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"eb17fa1d08fa22e2"}},{"id":"qx-b2-038","clusterId":"B","werkstueckRef":"B.26","stufe":3,"question":"Ein Kollege schwärmt von einem Vermögenswert, dessen Preis sich in sechs Monaten vervielfacht hat. Du fragst ihn, warum er gerade jetzt kauft. Welche Antwort deutet am stärksten darauf hin, dass er sich in einer Spekulationsblase bewegt?","options":["„Die Preise sind höher als vor einem Jahr, und auch große Anleger kaufen deutlich mehr dazu als früher.“","„Ich habe mir Gewinne, Umsätze und Kennzahlen angesehen, und sie tragen den Anstieg aus meiner Sicht weiterhin.“","„Seit sich die ersten Kritiker gemeldet haben, hat sich der Anstieg verlangsamt, ich warte, ob er wieder anzieht.“","„Ob er etwas wert ist, weiß ich nicht genau, aber morgen ist er teurer, und ich will nicht als Einziger draußen bleiben.“"],"correctIndex":3,"explanation":"Typisch für eine Blase ist, dass sich die Begründung vom Wert auf die Erwartung weiterer Preissteigerungen verlagert und die Angst, nicht dabei zu sein, den Kauf antreibt. Dann kauft man, weil der Preis steigt, nicht weil man verstanden hat, was der Vermögenswert wert ist. Ein höherer Preis oder zusätzliche Käufe allein sind noch kein Beleg, auch ein kräftiger Anstieg kann durch Gewinne und Umsätze gedeckt sein. Entscheidend ist, woher die Rechtfertigung stammt: aus dem Wert der Sache oder aus der Hoffnung auf den nächsten Käufer.","coreRule":"⚡ Prüfe die Begründung: Kaufst du wegen des Wertes oder weil der Preis gestern gestiegen ist?","quote":"","quoteLabel":"","beleg":"Werkstück B.26 (Red Flags: eine Spekulationsblase; Anti-Denkmuster)","status":"entwurf","scenario":"","kurz":"Wer kauft, weil der Preis morgen höher sein wird, und aus Angst, draußen zu bleiben, stützt sich nicht mehr auf den Wert der Sache. Der naheliegende Fehler ist, schon den Preisanstieg selbst als Zeichen einer Blase zu lesen.","prueffrage":"Was müsste dein Kollege über den Vermögenswert selbst wissen, um beurteilen zu können, ob der heutige Preis angemessen ist?","rueckmeldung":[{"option":0,"text":"Gestiegene Preise und mehr Käufe großer Anleger wirken wie ein Warnsignal. Beides gibt es aber auch bei einem Anstieg, den Gewinne und Umsätze decken, und dass er den Wert nicht kennt oder nur aus Angst kauft, draußen zu bleiben, sagt er nicht."},{"option":1,"text":"Wer Gewinne, Umsätze und Kennzahlen prüft, begründet seinen Kauf mit dem Wert der Sache. Das ist das Gegenteil einer Blasenlogik, auch wenn sich im Einzelfall streiten lässt, ob die Zahlen den Anstieg wirklich tragen."},{"option":2,"text":"Das Abwarten nach der Kritik zeigt, dass er auf den Kursverlauf schaut. Er kauft aber gerade nicht überstürzt, und weder Unwissen über den Wert noch die Angst, draußen zu bleiben, ist darin zu erkennen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes. 5. Aufl., Hoboken: Wiley","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"604127df74b21fb9"}},{"id":"qx-b2-039","clusterId":"B","werkstueckRef":"B.26","stufe":4,"question":"Welche Frage stellst du dir, bevor du auf das Angebot eingehst?","scenario":"Eine Freundin drängt: „Es gibt nur 20 Plätze beim Wochenend-Workshop mit dem berühmten Guru. Danach nimmt er drei Jahre lang keine neuen Schüler. Alle sagen, es hat ihr Leben verändert.“","options":["Habe ich schon so viel Geld und Zeit in die Lehre des Gurus gesteckt, dass ich den Workshop vor allem buchen will, um das Investierte nicht zu verlieren?","Würde ich den Workshop auch buchen, wenn es keine Begrenzung auf 20 Plätze und keine Frist gäbe, oder treibt mich die Angst, etwas zu verpassen?","Habe ich mich dem Guru gegenüber schon früher festgelegt, sodass ich jetzt nur nach Berichten suche, die meine bisherige Haltung bestätigen?","Hat die Zahl von 20 Plätzen meine Einschätzung verankert, sodass ich den Workshop an dieser Zahl und nicht an dem messe, was er mir inhaltlich bietet?"],"correctIndex":1,"explanation":"Platzbegrenzung („nur 20 Plätze“), Frist („drei Jahre keine neuen Schüler“) und Erfolgsberichte („alle sagen, es hat ihr Leben verändert“) sagen nichts darüber, ob der Workshop hält, was er verspricht. Knappheit und Exklusivität lassen Dinge automatisch wertvoller erscheinen, und eine große Zahl von Begeisterten wirkt als sozialer Beweis: Popularität wird mit Wert verwechselt. Beides erzeugt Zeitdruck und den Wunsch, zu einer auserwählten Gruppe zu gehören. Die beste Prüffrage trennt deshalb den Wert der Sache von dem Druck, der um sie herum aufgebaut wird: Würde das Angebot auch ohne Verknappung überzeugen? Wenn nicht, bezahlst du für die Angst vor dem Verpassen und nicht für den Inhalt.","coreRule":"⚡ Wer wegen der Angst vor dem Verpassen kauft, bezahlt für das Gefühl, nicht für die Sache.","beleg":"Werkstück B.26 (Eingangsszene Situation C; Anwendung: Esoterik; Anti-Denkmuster)","status":"entwurf","kurz":"Knappheit, Frist und begeisterte Berichte sagen nichts darüber, ob der Workshop hält, was er verspricht. Der naheliegende Fehler ist, Begehrtheit mit Wert zu verwechseln. Also frag dich, ob er dich auch ohne Verknappung überzeugen würde.","prueffrage":"Welche der drei Aussagen deiner Freundin sagt etwas darüber, was im Workshop tatsächlich geschieht?","rueckmeldung":[{"option":0,"text":"Die Sorge, Investiertes zu verlieren, ist bei vielen Entscheidungen berechtigt. Hier ist aber von bisherigen Ausgaben für diese Lehre keine Rede, und der Druck kommt aus der Verknappung, nicht aus einer Vorgeschichte."},{"option":2,"text":"Nach Bestätigung der eigenen Haltung zu suchen ist ein verbreiteter Fehler. Hier hast du dich aber noch auf nichts festgelegt, das du nur noch bestätigen müsstest. Der Druck entsteht durch die Verknappung."},{"option":3,"text":"Ein genannter Preis oder Richtwert kann tatsächlich den Maßstab verschieben. Die 20 Plätze sind hier aber selbst der Druck und kein Maßstab, an dem du den Inhalt misst. Die Frage trifft deshalb nicht den Kern."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"543449dc4f7f2159"}},{"id":"qx-b2-040","clusterId":"B","werkstueckRef":"B.26","stufe":2,"question":"Welche Beobachtung zeigt am deutlichsten, dass hier Angst vor dem Verpassen ausgenutzt wird, statt dass ein Angebot überzeugen soll?","scenario":"Eine Bekannte lädt dich zu einem „Business-Abend“ ein. „Wer jetzt Mitglieder anwirbt, sichert sich die beste Position und wird reich“, sagt sie. „Es gibt nur noch wenige Startplätze, und heute entscheiden sich schon die Ersten.“ Über das Produkt selbst spricht sie kaum.","options":["Der Vorteil, reich zu werden, wird über die Rekrutierung neuer Mitglieder und die knappen Startplätze begründet, nicht über den Nutzen des Produkts.","Der Vorteil, reich zu werden, wird über berühmte Fürsprecher begründet, die als Erste eingestiegen sein sollen, nicht über den Nutzen des Produkts.","Der Vorteil wird über die Einladung zum Business-Abend begründet, für die du dich revanchieren sollst, nicht über den Nutzen des Produkts.","Der Vorteil wird über deine Zusage zum Business-Abend begründet, an die du dich nun gebunden fühlen sollst, nicht über den Nutzen des Produkts."],"correctIndex":0,"explanation":"Bei Angeboten, die vor allem Reichtum durch Anwerben, Zeitdruck und Knappheit versprechen, wird nicht der Wert einer Sache verkauft, sondern die Sorge, eine einmalige Chance zu verpassen. Das Produkt tritt in den Hintergrund. Künstlich erzeugter Zeitdruck sowie Werbung mit Knappheit und Exklusivität sind typische Warnzeichen für FOMO-Manipulation. Entscheidend ist, woraus der versprochene Gewinn entsteht: Wird er mit dem Rekrutieren neuer Mitglieder statt mit dem Produkt begründet, ist das die FOMO-Mechanik von Multi-Level-Marketing und Schneeballsystemen.","coreRule":"⚡ Wer vor allem die Angst vor dem Verpassen verkauft, verkauft nicht den Wert der Sache.","beleg":"Werkstück B.26 (Anwendung: Multi-Level-Marketing & Schneeballsysteme; Red Flags: FOMO-Manipulation)","status":"entwurf","kurz":"Als Grund für den Reichtum nennt die Bekannte das Anwerben neuer Mitglieder, dazu knappe Plätze und Zeitdruck, und das Produkt kommt kaum vor. So wird kein Angebot verkauft, sondern die Sorge, eine einmalige Chance zu verpassen.","prueffrage":"Was müsste eine seriöse Einladung zu einem Verkaufsabend enthalten, das in ihren Worten fehlt?","rueckmeldung":[{"option":1,"text":"Prominente Fürsprecher gehören tatsächlich zu den bekannten Werbetechniken. Die Bekannte nennt aber niemanden dieser Art, und diese Technik erzeugt auch keine Eile. Was hier drängt, sind die wenigen Startplätze und der Ruf, heute zu entscheiden."},{"option":2,"text":"Ein Gefallen, den man erwidern soll, wäre eine bekannte Beeinflussungstechnik. Im Szenario wird die Einladung aber nicht als Gefallen dargestellt, für den du etwas schuldest. Auffällig sind stattdessen Rekrutierung, Knappheit und Zeitdruck."},{"option":3,"text":"Eine Bindung durch frühere Zusagen ist eine reale Technik, doch hier holt die Bekannte keine kleinen Zusagen ein, und deine Zusage zum Abend wird nicht als Verpflichtung benutzt. Die Warnzeichen liegen in Rekrutierung, Knappheit und dem Druck, jetzt zu entscheiden."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission, Consumer Advice: Multi-Level Marketing Businesses and Pyramid Schemes","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/multi-level-marketing-businesses-and-pyramid-schemes","abruf":"2026-10-12"},{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"c7076ce92f023a02"}},{"id":"qx-b2-041","clusterId":"B","werkstueckRef":"B.27","stufe":1,"question":"Welche Erklärung für Lenas Meinungswechsel ist die sparsamste?","scenario":"Lena fand das Programm einer neuen Partei lange unausgegoren; im Freundeskreis hieß die Partei „Die Spinner“, die Umfragen lagen bei 3 %. Dann springt die Partei auf 15 %. In Lenas Feed erscheinen positive Artikel, und zwei Kollegen, die sie für klug hält, loben das Programm. Lena liest es noch einmal und findet es jetzt „erfrischend anders“. Nach der Wahl, bei der die Partei 25 % erreicht, sagt sie: „Ich habe mir das genau angesehen. Die haben einfach die besten Lösungen.“ Am Programm selbst wurde zwischen den Umfragen und der Wahl nichts geändert.","options":["Mit dem Umfrageplus stieg für sie die wahrgenommene Glaubwürdigkeit der Ideen; das Programm blieb gleich.","Mit dem Umfrageplus rechtfertigte sie eine frühere Parteiwahl vor sich selbst und wertete das Programm auf.","Mit dem Umfrageplus bestätigte sich eine lange gehegte Sympathie, für die sie nur noch Belege suchte.","Mit dem Umfrageplus rückten ihre persönlichen Interessen in den Vordergrund, die das Programm nun besser bedient."],"correctIndex":0,"explanation":"Verglichen werden muss, was sich zwischen den beiden Urteilen tatsächlich geändert hat. Das Programm blieb gleich; geändert haben sich nur die Umfragewerte und die Signale aus Lenas Umfeld, also positive Artikel und das Lob zweier geschätzter Kollegen. Die sparsamste Erklärung nimmt deshalb an, dass dieses gewachsene Ansehen ihr Urteil verschoben hat: Popularität dient als Ersatz für Qualität („Wenn so viele das gut finden, muss etwas dran sein“), das ist der Mitläufer-Effekt. Auch Lenas Satz, sie habe sich alles genau angesehen, ändert daran nichts, denn die Ideen selbst sind dieselben geblieben.","coreRule":"⚡ Ändert sich nur die Zahl der Anhänger und nicht die Idee, dann sagt der Meinungswechsel etwas über die Stimmung aus, nicht über die Idee.","beleg":"Werkstück B.27 (Eingangsszene; Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Zwischen den beiden Urteilen änderten sich nur Umfragewerte und Signale aus Lenas Umfeld, nicht das Programm. Wer Beliebtheit als Ersatz für Qualität nimmt, fällt dem Mitläufer-Effekt zum Opfer und hält die Ideen für besser, obwohl sie gleich geblieben sind.","prueffrage":"Was genau hat sich zwischen Lenas erstem und ihrem zweiten Urteil nachweislich geändert?","rueckmeldung":[{"option":1,"text":"Menschen werten getroffene Entscheidungen oft nachträglich auf. Im Szenario hat Lena die Partei aber nie gewählt, sie hielt sie zuerst für „Spinner“. Die Erklärung setzt eine frühere Wahl voraus, die nirgends vorkommt."},{"option":2,"text":"Dass Lena das Programm noch einmal las und es plötzlich anders sah, wirkt wie späte Belegsuche. Eine lange gehegte Sympathie gibt es aber nicht: Anfangs hielt sie das Programm für unausgegoren und die Partei für „Spinner“."},{"option":3,"text":"Eigene Interessen können ein Urteil durchaus färben. Hier fehlt aber jeder Hinweis, dass sich bei Lena etwas verschoben hat; geändert haben sich nur Umfragen und Signale aus ihrem Umfeld, nicht ihre Lage und nicht das Programm."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Bandwagon“, „Appeal to the People“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9c4dd56e05838c55"}},{"id":"qx-b2-042","clusterId":"B","werkstueckRef":"B.27","stufe":2,"question":"Bei welcher dieser Entscheidungen ist „Mach, was die Mehrheit macht“ eine vertretbare Abkürzung?","options":["Beim Abendessen, weil ein Fehlgriff dort nur 15 Euro und einen mäßigen Abend kostet und du morgen einfach ein anderes Lokal ausprobieren kannst.","Beim Mittel für dein Kind, weil die lange Schlange am Stand zeigt, dass viele Eltern es kaufen und es offenbar bei vielen Kindern gut wirkt.","Bei der Kryptowährung, weil die Leute am Nebentisch nach eigener Aussage schon Gewinne gemacht haben und der Kurs gerade spürbar weiter steigt.","Beim Reisebericht, weil ein Video, das millionenfach geteilt wurde, vor dir schon von sehr vielen Menschen gesehen und für glaubwürdig befunden wurde."],"correctIndex":0,"explanation":"„Das volle Lokal ist wohl das bessere“ funktioniert als schnelle Faustregel, weil sich dahinter viele einzelne Erfahrungen bündeln, ein Fehlgriff hier nur 15 Euro und einen mäßigen Abend kostet und du morgen woanders essen kannst: Die Entscheidung ist umkehrbar und das Risiko gering. Je höher der mögliche Schaden und je schwerer die Entscheidung zurückzunehmen ist, desto weniger darf Popularität die eigene Prüfung von Fakten, Logik und Ethik ersetzen. Beim Mittel für dein Kind steht möglicherweise die Gesundheit auf dem Spiel, und dass viele Eltern es kaufen, sagt wenig über Wirksamkeit und Verträglichkeit. Wer seine Ersparnisse anlegt, weil andere gerade Gewinne machen, kauft nicht, weil der Wert unterbewertet wäre, sondern weil der Preis steigt; das treibt Blasen. Und dass ein Video millionenfach geteilt wurde, ist keine Prüfung, ob die Altstadt wirklich 2000 Jahre alt ist, zumal du es als Tatsache in die Zeitung bringen willst.","coreRule":"⚡ Der Mehrheit zu folgen genügt für den Filmabend, aber nicht für Wahrheitsfragen oder riskante Entscheidungen.","beleg":"Werkstück B.27 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"Du verbringst ein Wochenende in einer fremden Stadt. Fürs Abendessen für etwa 15 Euro schwankst du zwischen einem vollen Lokal und dem fast leeren daneben. Auf dem Markt verkauft ein Stand ein Mittel gegen Reisekrankheit für Kinder, und davor steht eine lange Schlange. Am Nebentisch schwärmen alle von einer Kryptowährung, mit der sie Gewinne gemacht haben, und du überlegst, deine Ersparnisse hineinzustecken. Außerdem willst du für die Zeitung deines Heimatorts einen Reisebericht schreiben und darin als Tatsache bringen, die Altstadt sei 2000 Jahre alt, weil ein millionenfach geteiltes Video das sagt.","kurz":"Beim Abendessen darfst du dich an der Menge orientieren: Viele Erfahrungen stecken im vollen Lokal, ein Fehlgriff kostet wenig und lässt sich morgen korrigieren. Je höher der Schaden und je schwerer rückgängig, desto weniger ersetzt Beliebtheit die eigene Prüfung.","prueffrage":"Was steht bei dieser Entscheidung auf dem Spiel, und lässt sich ein Fehlgriff später noch korrigieren?","rueckmeldung":[{"option":1,"text":"Die lange Schlange zeigt, dass viele das Mittel kaufen, nicht, dass es wirkt oder gut verträglich ist. Weil bei einem Kind möglicherweise die Gesundheit auf dem Spiel steht, sollte hier die eigene Prüfung zählen."},{"option":2,"text":"Gewinne anderer und ein steigender Kurs zeigen nur, dass der Preis gerade steigt, nicht, dass der Wert stimmt. Wer deshalb kauft, treibt womöglich eine Blase mit, und bei Ersparnissen ist der Schaden groß und schwer rückgängig."},{"option":3,"text":"Millionenfaches Teilen zeigt Verbreitung, aber nicht, dass jemand die Aussage geprüft hat. Als Tatsache in der Zeitung trägst du die Verantwortung dafür, dass das Alter der Altstadt wirklich belegt ist."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"76fd739e31e1816a"}},{"id":"qx-b2-043","clusterId":"B","werkstueckRef":"B.27","stufe":3,"question":"Welche Rückfrage prüft diese Erklärung am besten?","options":["Woher kam das Geld, mit dem so viele Anleger kaufen konnten, und wie stark wuchs die Kreditvergabe in dieser Zeit?","Hat der Kommentator ein eigenes finanzielles Interesse an der Aktie, sodass seine Erklärung gefärbt sein könnte?","Wie treffsicher waren frühere Kursprognosen dieses Kommentators, und wie oft lag er in seinen Erklärungen daneben?","Auf welchen Zeitraum und welchen Startkurs bezieht sich die Verdreifachung genau, und wie wurde sie berechnet?"],"correctIndex":0,"explanation":"Das Nachziehen hinter denen, die gerade Gewinne machen, ist real: Wer sieht, dass andere mit Spekulation verdienen, steigt ein. Das erklärt aber nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Bei einer einzelnen Aktie kann das Geld aus anderen Anlagen umgeschichtet werden; bei großen Manien sehen die Ökonomen Charles Kindleberger und Robert Aliber den eigentlichen Motor dagegen im Kredit, der in guten Zeiten rasch wächst, und das Mitlaufen ist bei ihnen ein Teil des Booms, nicht seine alleinige Ursache. Wer „der Herdentrieb allein“ behauptet, übersieht deshalb mindestens die Frage der Finanzierung. Die beste Rückfrage sucht diesen fehlenden Faktor. Ein Eigeninteresse des Kommentators ist ein vernünftiger Gedanke, betrifft aber seine Glaubwürdigkeit und sagt nichts über die Ursache des Anstiegs. Seine frühere Treffsicherheit zeigt, wie verlässlich er ist, nicht aber, ob der Herdentrieb hier allein genügt. Wie die Verdreifachung gerechnet wurde, klärt die genannte Zahl, nicht die behauptete Alleinursache.","coreRule":"⚡ Der Herdentrieb heizt Blasen an, aber das Geld dafür kommt aus wachsendem Kredit: Wer eine einzige Ursache behauptet, sollte nach den fehlenden fragen.","beleg":"Werkstück B.27 (Anwendung: Finanzmärkte); Fn. gl-b-kredit (Kindleberger/Aliber 2005, S. 12 und 29)","status":"entwurf","scenario":"Ein Börsenkommentator erklärt den starken Kursanstieg einer Aktie: „Sie hat sich in einem Jahr verdreifacht, weil alle auf den Zug aufgesprungen sind. Der Herdentrieb allein hat diese Blase gemacht.“","kurz":"Mitlaufen erklärt nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Wer „der Herdentrieb allein“ sagt, übersieht die Finanzierung. Bei großen Manien gilt Kredit als Motor, das Mitlaufen eher als Teil des Booms.","prueffrage":"Welche Auskunft könnte zeigen, dass der Herdentrieb allein den Anstieg nicht erklärt?","rueckmeldung":[{"option":1,"text":"Ein Eigeninteresse wäre ein berechtigter Gedanke, wenn es um die Glaubwürdigkeit des Kommentators geht. Ob der Herdentrieb den Anstieg allein erklärt, beantwortet es aber nicht, denn dafür zählt die Sache selbst und nicht, wer sie behauptet."},{"option":2,"text":"Eine schlechte Trefferquote macht den Kommentator weniger verlässlich, doch das betrifft ihn, nicht diese Erklärung. Auch jemand, der sonst oft danebenliegt, kann hier recht haben, und ein Treffsicherer kann sich irren. Geprüft wird so nicht, ob der Herdentrieb allein genügt."},{"option":3,"text":"Eine genaue Rechnung klärt, ob die Verdreifachung stimmt. Diese Zahl wird aber gar nicht bestritten, sondern ihre behauptete Ursache. Selbst mit sauber geklärter Basis bliebe offen, ob Mitlaufen allein den Anstieg erklärt."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes: A History of Financial Crises. 5. Aufl., Hoboken: Wiley","oeffentlich":false},{"typ":"url","kurz":"Schularick, M.; Taylor, A. M. (2009/2011): Credit Booms Gone Bust: Monetary Policy, Leverage Cycles and Financial Crises, 1870–2008. NBER Working Paper 15512","oeffentlich":true,"url":"https://www.nber.org/papers/w15512","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"dfa0bb76ce6f1f1f"}},{"id":"qx-b2-044","clusterId":"B","werkstueckRef":"B.27","stufe":4,"question":"Welche Prüffrage hilft dir am besten, die Aussage zu beurteilen, ohne aus ihrer Größe auf ihre Wahrheit zu schließen?","scenario":"Ein Video behauptet etwas Spektakuläres. Darunter steht: „10 Millionen Aufrufe! Hunderttausende sind schon auf der Straße! Wir werden jeden Tag mehr!“ Dein Bekannter sagt: „Bei so vielen Leuten muss doch etwas dran sein.“","options":["Sind die zehn Millionen Aufrufe echt und nicht gekauft, denn erst geprüfte Zahlen sagten, wie viele Menschen die Behauptung teilen?","Wer hat das Video eingestellt und wer verdient an den Aufrufen, denn ein Geschäftsinteresse spräche gegen die Wahrheit der Behauptung?","Wie würde ich die Behauptung beurteilen, wenn nur ich davon wüsste, denn dann zählten allein die Belege, nicht Klickzahlen?","Wie schnell wächst die Zahl der Aufrufe pro Tag, denn ein auffälliges Tempo könnte auf gesteuerte Verbreitung hindeuten?"],"correctIndex":2,"explanation":"Aufrufe, Demonstrationsgrößen und Wachstum sagen etwas darüber aus, wie viele Menschen eine Behauptung teilen, nicht darüber, ob sie stimmt. Das ist die Verwechslung von Popularität mit Richtigkeit. Zudem erzeugt Popularität weitere Popularität: Wer mitläuft, macht die Bewegung größer und scheinbar überzeugender, ohne dass ein einziger Beleg hinzukommt. Prüfen lässt sich die Aussage nur, wenn man die Menge gedanklich ausblendet und fragt, was die Belege allein hergeben. Die anderen Fragen klingen sinnvoll, bleiben aber bei der Menge oder beim Absender: Selbst echte, nicht gekaufte Aufrufe sagen nichts darüber, ob die Behauptung stimmt. Ein Geschäftsinteresse macht eine Aussage nicht falsch, das lässt sich nur an den Belegen prüfen. Und auch ein auffällig steiles Wachstum, selbst wenn es gesteuert wäre, verrät nichts über den Wahrheitsgehalt.","coreRule":"⚡ Eine große Anhängerschaft ist ein Beleg für Beliebtheit, nicht für Wahrheit.","quote":"","quoteLabel":"","beleg":"Werkstück B.27 (Anwendung: Verschwörungsmythen & Kulte; Anti-Denkmuster)","status":"entwurf","kurz":"Aufrufe, Demonstrationsgrößen und Wachstum zeigen nur, wie viele eine Behauptung teilen, nicht, ob sie stimmt. Wer die Menge gedanklich ausblendet und fragt, was die Belege allein hergeben, trennt Beliebtheit von Richtigkeit.","prueffrage":"Welche der Angaben unter dem Video sagt etwas darüber, ob das Behauptete tatsächlich zutrifft?","rueckmeldung":[{"option":0,"text":"Gekaufte Klicks kommen tatsächlich vor, und eine Prüfung der Zahlen ist nicht verkehrt. Aber selbst ganz echte Aufrufe sagen nur, wie viele die Behauptung teilen, nicht, ob sie stimmt. Die Frage bleibt bei der Menge."},{"option":1,"text":"Wer von einer Behauptung profitiert, verdient einen genaueren Blick. Eine Aussage wird dadurch aber nicht falsch: Ein Geschäftsinteresse spricht nicht gegen die Wahrheit, das zeigt sich erst an den Belegen. Die Frage bleibt beim Absender."},{"option":3,"text":"Ein auffällig steiles Wachstum kann auf gesteuerte Verbreitung hindeuten, und das ist gut zu wissen. Über den Wahrheitsgehalt verrät es trotzdem nichts, denn auch gesteuert verbreitete Aussagen können stimmen oder falsch sein. Die Frage bleibt bei der Menge."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to the People“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"27b6b32b6ccc0a51"}},{"id":"qx-b2-045","clusterId":"B","werkstueckRef":"B.28","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Preisunterschied, und was spricht gegen den Einwand der Teilnehmerin?","scenario":"Bei einem Experiment bekommt die eine Hälfte einer Gruppe eine Kaffeetasse geschenkt, die andere Hälfte nicht. Wer eine Tasse hat, will sie im Schnitt erst ab einem deutlich höheren Preis verkaufen, als die Übrigen bereit sind, für dieselbe Tasse zu zahlen. Eine Teilnehmerin sagt: „Die Tassen sind ja alle gleich. Dann haben die Besitzer eben genauer geprüft, wie gut sie ist.“","options":["Der Unterschied entsteht erst durch das Besitzen: Wer die Tasse hat, erlebt das Abgeben als Verlust und gewichtet ihn stärker als den Erlös, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch bessere Information: Wer die Tasse hat, kann ihre Qualität in der Hand genauer beurteilen und verlangt deshalb mehr, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Knappheit: Wer die Tasse hat, hält sie für selten, weil nur die Hälfte der Gruppe eine bekam, und verlangt deshalb mehr, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Verankerung: Wer die Tasse hat, richtet sich nach dem Ladenpreis, den er für sie vermutet, und verlangt deshalb mehr, obwohl die Tassen identisch sind."],"correctIndex":0,"explanation":"Die Tassen sind identisch. Der einzige Unterschied zwischen den Gruppen ist der Besitz. Wer eine Tasse hat, für den wird sie Teil des Referenzpunkts. Sie herzugeben wird dann als Verlust erlebt, und ein Verlust wiegt meist schwerer als ein gleich hoher Gewinn. Deshalb verlangen die Besitzer mehr, als die anderen zahlen würden (Besitztumseffekt). Der Einwand der Teilnehmerin scheitert daran, dass identische Tassen keinen Qualitätsunterschied bieten, den die Besitzer genauer prüfen könnten. Dasselbe Muster steckt hinter „30 Tage kostenlos testen“: Was man schon hat, gibt man ungern zurück.","coreRule":"⚡ Wenn identische Dinge nur wegen des Besitzes unterschiedlich bewertet werden, steckt oft Verlustaversion dahinter: Was ich habe, wird Teil meines Referenzpunkts, und Hergeben zählt als Verlust.","beleg":"Werkstück B.28 (Analyse: Besitztumseffekt; Anwendung: Marketing)","status":"entwurf","kurz":"Der Preisunterschied entsteht durch den Besitz selbst: Wer die Tasse hat, erlebt das Abgeben als Verlust, und der wiegt meist schwerer als ein gleich hoher Erlös. Eine genauere Prüfung erklärt nichts, denn bei identischen Tassen gibt es nichts zu entdecken.","prueffrage":"Welche Information über die Tasse könnten die Besitzer haben, die den anderen fehlt, wenn alle Tassen gleich sind?","rueckmeldung":[{"option":1,"text":"Genaueres Prüfen lohnt sich, wenn Gegenstände verschieden sind. Hier sind die Tassen aber identisch, also gibt es in der Hand nichts zu entdecken, das den höheren Preis begründen könnte."},{"option":2,"text":"Knappheit kann Preise steigern. Hier sehen aber auch die Übrigen, dass nur die Hälfte eine Tasse bekam, sie träfe also beide Gruppen und erklärt nicht, warum nur die Besitzer mehr verlangen."},{"option":3,"text":"Ein vermuteter Ladenpreis kann Preisvorstellungen prägen. Er stünde aber auch den Übrigen als Anker zur Verfügung, würde also beide Gruppen betreffen und nicht den Unterschied zwischen ihnen erklären."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1990): Experimental Tests of the Endowment Effect and the Coase Theorem. Journal of Political Economy 98(6), 1325–1348","oeffentlich":false,"doi":"10.1086/261737"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2ae6083e3e480446"}},{"id":"qx-b2-046","clusterId":"B","werkstueckRef":"B.28","stufe":3,"question":"Ein Artikel behauptet: „Wissenschaftlich bewiesen: Verluste wiegen genau doppelt so schwer wie Gewinne.“ Zur Prüfung liest du die zugrunde liegenden Messungen nach. Die klassische Studie kam auf einen Faktor von 2,25. Eine große Zusammenstellung vieler späterer Arbeiten ergab im Mittel etwa 1,96. Betrachtet man nur Entscheidungen zwischen riskanten Lotterien, liegt der Wert bei etwa 1,31. Was folgt daraus für die Behauptung?","options":["Der Artikel überzeichnet: Der Wert ist eine Faustregel, die je nach Methode deutlich schwankt, und keine feste Konstante.","Der Artikel liegt richtig: Der Mittelwert vieler Arbeiten von etwa 1,96 entspricht praktisch dem Faktor 2 und belegt die Behauptung.","Der Artikel liegt falsch: Da die Werte so stark abweichen, ist nicht einmal belegt, dass Verluste überhaupt schwerer wiegen als Gewinne.","Der Artikel ist nicht beurteilbar: Solange die Zahl der Versuchspersonen jeder Studie fehlt, lässt sich über die Werte nichts sagen."],"correctIndex":0,"explanation":"Die Messwerte streuen je nach Methode erheblich: 2,25 in der klassischen Studie, etwa 1,96 im Mittel vieler späterer Arbeiten, nur etwa 1,31 bei riskanten Lotterien. Eine Größe, die so stark von der Messmethode abhängt, ist keine feste Konstante, sondern eine Faustregel. „Genau doppelt“ und „wissenschaftlich bewiesen“ verleihen der Zahl eine Präzision, die die Daten nicht hergeben. Die Gegenrichtung ist ebenso ein Fehlschluss: Schwankende Schätzwerte bedeuten nicht, dass der Effekt verschwindet. Die genannten Messungen liegen durchgehend über 1; wie stark der Effekt ausfällt, hängt von Methode und Kontext ab. Gal und Rucker (2018) bestreiten sogar, dass Verluste im Allgemeinen stärker wirken als gleich hohe Gewinne. Das „doppelt so stark“ ist also eine gerundete Faustregel, kein Naturgesetz. Der Mittelwert von etwa 1,96 liegt zwar in der Nähe von 2, macht aber „genau“ und „bewiesen“ bei einer Spanne von 1,31 bis 2,25 nicht wahr. Und auch ohne Angaben zur Stichprobengröße genügen die genannten Werte, um die behauptete Präzision zu widerlegen.","coreRule":"⚡ Eine Zahl, die je nach Messmethode stark schwankt, ist eine Faustregel, keine Konstante.","beleg":"Werkstück B.28 (Kernidee; Analyse); Fn. gl-b-verlust (Tversky/Kahneman 1992, S. 311; Brown u. a. 2024, JEL 62(2); Walasek u. a. 2024, JEP 103; Gal/Rucker 2018)","status":"entwurf","scenario":"","kurz":"Die Werte reichen je nach Methode von 1,31 bis 2,25, also ist „genau doppelt“ eine gerundete Faustregel und keine Konstante. Der naheliegende Fehler ist, einer glatten Zahl Präzision zuzutrauen, die die Messungen nicht hergeben.","prueffrage":"Wie weit liegen die drei genannten Werte auseinander, und welcher davon ist genau 2?","rueckmeldung":[{"option":1,"text":"Mit 1,96 liegt der Mittelwert tatsächlich nahe bei 2. Er fasst aber Werte von 1,31 bis 2,25 zusammen. Ein gerundeter Durchschnitt macht „genau doppelt“ und „bewiesen“ noch nicht wahr."},{"option":2,"text":"Die Werte streuen stark, das stimmt. Alle genannten Messungen liegen aber über 1. Schwankende Schätzwerte zeigen, dass die Zahl ungenau ist, nicht dass der Effekt verschwindet."},{"option":3,"text":"Stichprobengrößen wären für die Beurteilung einzelner Studien nützlich. Um die behauptete Genauigkeit zu widerlegen, genügt aber schon die Spanne der genannten Werte von 1,31 bis 2,25."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv; Zeitschriftenfassung JEL 62(2), 485–516)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"},{"typ":"doi","kurz":"Walasek, L.; Mullett, T. L.; Stewart, N. (2024): A meta-analysis of loss aversion in risky contexts. Journal of Economic Psychology 103, 102740","oeffentlich":false,"doi":"10.1016/j.joep.2024.102740"},{"typ":"doi","kurz":"Gal, D.; Rucker, D. D. (2018): The Loss of Loss Aversion: Will It Loom Larger Than Its Gain? Journal of Consumer Psychology 28(3), 497–516","oeffentlich":false,"doi":"10.1002/jcpy.1047"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"164c7b4179baf425"}},{"id":"qx-b2-047","clusterId":"B","werkstueckRef":"B.28","stufe":4,"question":"Welche Erklärung ihres Verhaltens ist am sparsamsten, wenn du nur ihre Lage betrachtest?","scenario":"Eine Bekannte ist seit Jahren in einer Gemeinschaft, die ihr viel bedeutet: Dort sind ihre engsten Freunde, ihre Rolle und das Gefühl, etwas Besonderes zu wissen. Sie hat investiert und gespendet. Nun hat ihr jemand die zentralen Behauptungen der Gruppe überzeugend widerlegt. Trotzdem sagt sie: „Du magst ja recht haben, aber ich bleibe.“","options":["Sie gewichtet den erwarteten Verlust durch einen Austritt stärker als den Gewinn, die Wahrheit zu erkennen.","Sie lässt nur gelten, was zu den Behauptungen der Gruppe passt, und hält diese deshalb weiterhin für zutreffend.","Sie erwartet, dass die Gruppe ihre Behauptungen bald von selbst korrigiert, und überschätzt die Aussicht darauf.","Sie traut demjenigen nicht, der die Widerlegung vorbrachte, und misst seinen Argumenten deshalb kein Gewicht bei."],"correctIndex":0,"explanation":"Wer aus einer Gemeinschaft austritt, verliert nicht nur eine Überzeugung, sondern auch Freunde, Identität, das Gefühl besonderen Wissens und die investierte Zeit und das Geld. Menschen gewichten Verluste meist stärker als gleich große Gewinne (Verlustaversion); wie stark, hängt von Methode und Lage ab. Deshalb kann der erwartete Verlust schwerer wiegen als der Gewinn, die Wahrheit zu erkennen, und diese Erklärung kommt mit ihrer geschilderten Lage aus. Die Verlust-Erklärung beschreibt zudem einen Mechanismus, kein Urteil über die Intelligenz der Bekannten.","coreRule":"⚡ Wer fragt, warum jemand nicht geht, sollte zuerst fragen, was der Austritt ihn kosten würde, nicht nur, ob er recht hat.","beleg":"Werkstück B.28 (Anwendung: Verschwörungsmythen & Kulte)","status":"entwurf","kurz":"Wer austritt, verliert Freunde, Rolle, Identität und das Investierte. Verluste wiegen oft schwerer als gleich große Gewinne, daher kann das Bleiben trotz Widerlegung herrühren, ohne dass sie die Behauptungen noch für wahr hält.","prueffrage":"Was hängt für sie außer der Frage, ob die Behauptungen stimmen, noch an dieser Gemeinschaft?","rueckmeldung":[{"option":1,"text":"Dass Menschen Passendes bevorzugen, kommt vor und wirkt hier naheliegend. Ihr „Du magst ja recht haben“ zeigt aber, dass sie die Widerlegung durchaus gelten lässt, die Erklärung passt also nicht zu ihren Worten."},{"option":2,"text":"Hoffnung auf Besserung ist ein vertrautes Motiv, wenn man ungern geht. Davon steht in ihrer Lage aber nichts; die Erklärung führt eine zusätzliche Annahme ein, die ihre Äußerung gar nicht braucht."},{"option":3,"text":"Misstrauen gegenüber dem Überbringer kann tatsächlich Argumente entwerten. Wer aber sagt „Du magst ja recht haben“, erkennt die Widerlegung gerade an. Von Misstrauen ist im Szenario außerdem keine Rede."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7d1a567d882d7916"}},{"id":"qx-b2-048","clusterId":"B","werkstueckRef":"B.28","stufe":2,"question":"Welche Frage prüft am besten, ob du das Abo behalten solltest?","scenario":"Seit Jahren läuft von deinem Konto ein Abo ab, das du kaum noch nutzt. Eine Freundin sagt: „Kündige es doch einfach.“ Du antwortest: „Aber ich habe schon so viel dafür bezahlt, das kann ich jetzt nicht wegwerfen.“","options":["Hatte ich beim Abschluss vor Jahren gute Gründe, und war der Vertrag damals rückblickend eine vernünftige Entscheidung?","Wenn ich das Abo heute nicht hätte, würde ich es jetzt neu abschließen und dafür diesen Aufwand an Geld und Zeit betreiben?","Was verliere ich, wenn ich jetzt kündige, verglichen mit dem, was ich gewinne, wenn das Abo einfach weiterläuft wie bisher?","Wie viele Menschen behalten ein Abo trotz kaum noch genutzter Leistung, und was wissen sie vielleicht, das ich nicht sehe?"],"correctIndex":1,"explanation":"Eine gute Entscheidung schaut nach vorn: Was bringt mir das Abo ab jetzt, und was kostet es mich ab jetzt? Am klarsten wird das, wenn man sich vorstellt, man besäße es nicht, und fragt, ob man heute Geld und Zeit dafür aufwenden würde. Das bereits Eingezahlte ist nicht mehr zurückzuholen, egal ob du kündigst oder nicht. Wer darauf schaut, wirft gutes Geld schlechtem hinterher (versunkene Kosten). Die Abwägung „Verlust bei Kündigung gegen Gewinn beim Weiterlaufen“ bleibt am bestehenden Abo als Referenzpunkt hängen, sodass Kündigen als Verlust erscheint. Der Blick auf das, was andere tun, beantwortet nicht, was das Abo dir ab jetzt bringt.","coreRule":"⚡ Frag nicht, was du schon investiert hast, sondern ob du heute neu einsteigen würdest.","quote":"würde ich mein Geld, meine Zeit oder meinen Verstand heute dafür aufwenden, um exakt hier einzusteigen?","quoteLabel":"Prüffrage für festgefahrene Entscheidungen:","beleg":"Werkstück B.28 (Anti-Denkmuster: Clean-Slate-Test; Werkbank-Frage)","status":"entwurf","kurz":"Entscheidend ist, was das Abo dir ab jetzt bringt und kostet. Das Eingezahlte ist so oder so weg. Wer es dennoch mitrechnet, wirft gutes Geld schlechtem hinterher. Stell dir vor, du hättest das Abo nicht: Würdest du es heute neu abschließen?","prueffrage":"Welcher Teil der Kosten hängt davon ab, ob du heute kündigst oder behältst, und welcher steht ohnehin fest?","rueckmeldung":[{"option":0,"text":"Gute Gründe von damals erklären, warum das Abo läuft. Sie sagen aber nichts darüber, was es dir ab jetzt bringt. Auch ein damals vernünftiger Vertrag kann heute kaum noch Nutzen haben."},{"option":2,"text":"Eine Abwägung nach vorn ist grundsätzlich richtig. Hier gilt das bestehende Abo aber als Normalzustand, sodass Kündigen automatisch wie ein Verlust aussieht und Weiterlaufen wie nichts Besonderes."},{"option":3,"text":"Vorsicht gegenüber den eigenen blinden Flecken ist grundsätzlich klug. Was andere tun, beantwortet aber nicht, was das Abo dir ab jetzt bringt und kostet. Das lässt sich nur an deiner eigenen Nutzung prüfen."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Watzek, J.; Brosnan, S. F. (2020): Capuchin and rhesus monkeys show sunk cost effects in a psychomotor task. Scientific Reports 10, 20396","oeffentlich":true,"doi":"10.1038/s41598-020-77301-w","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7683735/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1), 124–140","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"501b77a7a7f8cf11"}},{"id":"qx-b2-049","clusterId":"B","werkstueckRef":"B.29","stufe":2,"question":"Was ist an Lenas Schlussfolgerung fehlerhaft?","options":["Sie schließt aus dem Nicht-Finden auf das Nicht-Vorhandensein, obwohl Verzerrungen meist unbewusst ablaufen und sich durch bloßes Nach-innen-Schauen gar nicht zeigen.","Sie schließt aus der einseitigen Studienauswahl ihres Kollegen, dass seine Position falsch ist, obwohl auch einseitig gesammelte Studien eine zutreffende Aussage stützen können.","Sie verallgemeinert vom Kollegen auf alle, die ihre Meinung mit Studien stützen, obwohl ein einzelner Fall keine sichere Aussage über viele Menschen zulässt.","Sie überschätzt ihr Können, weil sie die Liste der Denkfehler gerade durcharbeitet, obwohl Anfänger ihr Können oft zu hoch einschätzen (Dunning-Kruger-Effekt)."],"correctIndex":0,"explanation":"Lena beurteilt sich über ihre Gedanken und Absichten, den Kollegen aber über sein sichtbares Verhalten. In ihren Gedanken findet sie fast immer gute Absichten. Die meisten Verzerrungen laufen jedoch unbewusst ab und sind durch einfaches Nach-innen-Schauen grundsätzlich nicht auffindbar. Aus „ich finde nichts“ folgt deshalb nicht „da ist nichts“. Zuverlässiger ist ein Blick von außen: ihr eigenes Verhalten prüfen (Welche Gegenargumente ignoriere ich? Welche Quellen nutze ich?) oder jemanden bitten, die eigene Position auseinanderzunehmen.","coreRule":"⚡ Wer nur in sich hineinschaut, findet gute Absichten und übersieht die Verzerrung.","beleg":"Werkstück B.29 (Analyse: Der Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena arbeitet sich durch eine Liste typischer Denkfehler. Bei ihrem Kollegen erkennt sie sofort, dass er nur Studien zitiert, die seine Meinung stützen. Danach prüft sie sich selbst: Sie geht in Gedanken durch, was sie bei ihrer eigenen Position antreibt, findet dort nur den Wunsch, die Wahrheit herauszufinden, und stellt fest: „Bei mir ist keine Voreingenommenheit im Spiel.“","kurz":"Wer in sich hineinschaut und keine Voreingenommenheit findet, hat sie damit nicht ausgeschlossen, denn Verzerrungen laufen meist unbewusst ab. Der naheliegende Fehler: aus „ich finde nichts“ wird „da ist nichts“. Verlässlicher ist der Blick auf das eigene Verhalten.","prueffrage":"Woran würde man bei Lena und bei ihrem Kollegen jeweils erkennen, ob Voreingenommenheit im Spiel ist?","rueckmeldung":[{"option":1,"text":"Dass einseitig gesammelte Studien eine zutreffende Aussage stützen können, stimmt. Lena erklärt die Position des Kollegen aber gar nicht für falsch, sie erkennt nur seine einseitige Auswahl. Ihr Fehler liegt bei der Einschätzung der eigenen Person."},{"option":2,"text":"Von einem Einzelfall auf alle zu schließen, wäre tatsächlich unsicher. Lena tut das hier aber nicht: Sie spricht über den Kollegen und dann über sich selbst, über andere Menschen sagt sie nichts."},{"option":3,"text":"Dass sich Anfänger oft überschätzen, ist als Tendenz bekannt. Das Szenario sagt aber nichts über Lenas Können, und sie urteilt auch nicht darüber, sondern über fehlende Voreingenommenheit. Das Problem liegt in ihrer Methode der Selbstprüfung."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5b8a5c7b2ae4722b"}},{"id":"qx-b2-050","clusterId":"B","werkstueckRef":"B.29","stufe":3,"question":"Was ist an Jonas' Schlussfolgerung am problematischsten?","options":["Er schließt aus seinem Wissen über Denkfehler, dass er selbst gegen sie immun ist, obwohl nach Befunden selbst höhere kognitive Fähigkeit den blinden Fleck nicht verkleinert.","Er schließt vom Verhalten seines einen Kollegen auf alle Menschen ohne Studium in Statistik und Logik, obwohl ein einzelner Fall keine sichere Aussage über viele Menschen trägt.","Er überschätzt sein Wissen über Denkfehler, weil er sie nur aus dem Studium kennt, obwohl ein Studium noch nicht heißt, dass man alle gängigen Fehler wirklich beherrscht.","Er hält sich für unvoreingenommen, weil ihm bisher niemand eine Verzerrung nachgewiesen hat, obwohl ein ausbleibender Nachweis noch nicht zeigt, dass keine vorliegt."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Wer nach innen schaut, findet meist gute Absichten und schließt daraus, dass keine Voreingenommenheit im Spiel ist. Auch Klugheit schützt nicht: In einer Studie von West, Meserve und Stanovich (2012) mit Studierenden verkleinerten weder höhere kognitive Fähigkeit noch einschlägige Denkstile den blinden Fleck, wenn überhaupt ging höhere Fähigkeit mit einem etwas größeren einher. Eine mögliche Erklärung: Klügere können ihre voreingenommenen Schlüsse geschickter rational begründen. Daraus folgt für Jonas: Sein Wissen macht ihn vor allem besser darin, Fehler bei anderen zu entdecken, nicht bei sich selbst. Sinnvoller wäre ein externer Check, etwa jemanden zu bitten, die eigene Position gezielt zu zerlegen.","coreRule":"⚡ Wissen über Denkfehler und hohe Intelligenz schützen nicht vor dem eigenen blinden Fleck; prüfe dich von außen, nicht nur durch Nach-innen-Schauen.","beleg":"Werkstück B.29 (Analyse: Intelligenz schützt nicht); Fn. gl-b-blindspot (West/Meserve/Stanovich 2012, JPSP 103(3), S. 511, 515)","status":"entwurf","scenario":"In einer Diskussion über einen Zeitungsartikel sagt Jonas: „Ich habe Statistik und Logik studiert und kenne die gängigen Denkfehler in- und auswendig. Von denen lasse ich mich nicht mehr täuschen. Bei meinem Kollegen erkenne ich sie sofort, bei mir selbst ist das kein Thema.“","kurz":"Wissen über Denkfehler schützt nicht vor dem eigenen blinden Fleck: Auch höhere Fähigkeit verkleinert ihn nach Befunden nicht. Der Fehler ist, vom Erkennen bei anderen auf Immunität bei sich zu schließen.","prueffrage":"Worauf stützt Jonas seine Aussage, bei ihm selbst seien Denkfehler kein Thema?","rueckmeldung":[{"option":1,"text":"Dass ein einzelner Fall wenig über viele aussagt, stimmt als Grundsatz. Jonas verallgemeinert aber gar nicht: Er sagt nur, dass er Fehler bei seinem Kollegen sofort erkennt. Der Schluss, der trägt nicht, betrifft ihn selbst."},{"option":2,"text":"Ein Studium garantiert nicht jede Kenntnis, das stimmt. An Jonas' Wissen besteht aber kein Anlass zum Zweifel. Gerade deshalb ist der Fehler woanders: Das Wissen schützt ihn nicht davor, die Fehler bei sich selbst zu übersehen."},{"option":3,"text":"Aus fehlendem Nachweis auf Abwesenheit zu schließen, wäre tatsächlich ein Fehler. Jonas argumentiert aber anders: Er beruft sich auf sein Studium, nicht darauf, dass ihm niemand etwas nachgewiesen hat."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4f06cabb8d54a775"}},{"id":"qx-b2-051","clusterId":"B","werkstueckRef":"B.29","stufe":4,"question":"Was solltest du als Nächstes tun, um herauszufinden, ob du selbst voreingenommen bist?","scenario":"In einer hitzigen Diskussion über Ernährung bist du überzeugt, der Einzige am Tisch zu sein, der objektiv urteilt. Du hast viel über Denkfehler gelesen und erkennst bei deinem Gegenüber sofort Bestätigungsfehler und selektive Quellenwahl.","options":["Du bittest eine vertraute Person mit anderer Meinung, dein Argument nach Kräften auseinanderzunehmen, und hörst zunächst nur zu.","Du prüfst genau, ob die Studien deines Gegenübers methodisch sauber sind und seine Schlüsse daraus tragen.","Du nimmst dir einen Tag Abstand und gehst deine Argumente danach in Ruhe allein noch einmal Punkt für Punkt durch.","Du suchst weitere hochwertige Studien zu deinem Standpunkt, damit deine Position auf einer breiteren Belegbasis steht."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Von innen suchst du mit demselben Gehirn, das den Fehler macht: Findest du keine Voreingenommenheit, heißt das nicht, dass keine da ist. Klüger zu sein schützt kaum davor. In einer Studie ging höhere kognitive Fähigkeit sogar eher mit einem größeren blinden Fleck einher, und kluge Menschen können voreingenommene Schlüsse oft geschickter rechtfertigen. Was von innen unsichtbar bleibt, kann ein Blick von außen sichtbar machen: Jemand, der anderer Meinung ist und dein Argument ernsthaft angreift, findet Lücken, die du selbst nicht siehst. Dass du dann zunächst nur zuhörst, verhindert, dass du die Kritik sofort wegerklärst. Die Studien des Gegenübers zu prüfen ist sinnvoll, sagt aber etwas über seine Quellen und nichts über deine eigene Verzerrung. Abstand und Nachdenken allein helfen gegen Hitze, nicht gegen einen blinden Fleck, den dasselbe Denken erzeugt. Und weitere Belege für den eigenen Standpunkt zu sammeln bestätigt ihn nur, statt ihn zu testen.","coreRule":"⚡ Was du von innen nicht siehst, zeigt dir nur ein Blick von außen.","beleg":"Werkstück B.29 (Anti-Denkmuster: Die wirksamste Taktik; Anwendung: Der intellektuelle Skeptiker)","status":"entwurf","kurz":"Voreingenommenheit wirkt meist unbemerkt, und von innen suchst du mit demselben Denken, das den Fehler macht. Erst jemand mit anderer Sicht, den du zunächst nur anhörst, kann Lücken zeigen, die du selbst nicht siehst.","prueffrage":"Wer hat dein eigenes Argument in dieser Diskussion bisher überhaupt auf Schwächen geprüft?","rueckmeldung":[{"option":1,"text":"Die Studien des Gegenübers zu prüfen ist sinnvoll, sagt aber nur etwas über seine Quellen. Ob du selbst verzerrt urteilst, bleibt dabei unberührt, denn die Prüfung richtet sich nach außen."},{"option":2,"text":"Ein Tag Abstand kühlt die Hitze der Diskussion ab. Dasselbe Denken, das einen blinden Fleck erzeugt, geht deine Argumente aber erneut durch und übersieht ihn deshalb sehr wahrscheinlich wieder."},{"option":3,"text":"Weitere gute Studien machen deine Position vielleicht breiter belegt, aber sie testen sie nicht. Wer nur Belege für den eigenen Standpunkt sammelt, bestätigt ihn und macht genau das, was du beim anderen kritisierst."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f8ec7215b3ef1c10"}},{"id":"qx-b2-052","clusterId":"B","werkstueckRef":"B.29","stufe":1,"question":"Wie lässt sich am besten erklären, was in dieser Situation passiert?","options":["Lena misst alle späteren Quellen an dem ersten Artikel, den sie zum Thema gelesen hat, und hält ihre Sammlung deshalb für ausgewogen (Ankereffekt).","Lena nimmt an, dass die meisten Kollegen wie sie nur die Wahrheit suchen, und hält Toms Einseitigkeit deshalb für eine Ausnahme (falscher Konsens).","Lena hält sich für objektiver als Tom, weil sie in sich hineinhorcht und dort nur gute Absichten findet (blinder Fleck für eigene Verzerrungen).","Lena hält ihre Position für gesichert, weil bekannte Fachleute in den gesammelten Artikeln sie stützen, und prüft sie deshalb nicht weiter (Autoritätsargument)."],"correctIndex":2,"explanation":"Lena misst Tom an seinem Verhalten, sich selbst aber an ihren Absichten: Sie horcht in sich hinein, findet dort nur den Wunsch nach Wahrheit und hält sich deshalb für objektiver. Viele Verzerrungen wirken jedoch unbewusst und zeigen sich beim Nach-innen-Schauen nicht; aus „nichts gefunden“ folgt nicht „nichts da“. Ihr eigener Schreibtisch zeigt dasselbe Muster, das sie Tom vorwirft. Ein Ankereffekt passt nicht, denn von einem ersten Artikel, an dem sie alles misst, ist keine Rede, sie beruft sich auf ihre Innenschau. Für einen falschen Konsens gibt es keinen Hinweis, denn sie spricht nur über Tom und sich selbst, nicht über eine Mehrheit der Kollegen. Ein Autoritätsargument liegt nicht vor, denn sie verweist auf keine Fachleute, sondern verlässt sich auf ihr eigenes Urteil.","coreRule":"⚡ Was du bei anderen sofort siehst, übersiehst du bei dir selbst am leichtesten.","beleg":"Werkstück B.29 (Kernidee; Eingangsszene; Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena erklärt in einer hitzigen Diskussion: „Mein Kollege Tom sieht nur die Quellen, die zu seiner Meinung passen, und ignoriert alles andere. Der ist komplett voreingenommen. Ich dagegen suche einfach die Wahrheit.“ Wenn man sich ihren Schreibtisch anschaut, stellt man fest: Auch sie hat fast nur Artikel gesammelt, die ihre eigene Position stützen. Auf Nachfrage sagt sie: „Ich habe nachgedacht und bei mir keine Voreingenommenheit gefunden.“","kurz":"Lena misst Tom an seinem Verhalten, sich selbst an ihren Absichten. Beim Nach-innen-Schauen zeigen sich viele Verzerrungen nicht, denn „nichts gefunden“ heißt nicht „nichts da“. Ihr Schreibtisch zeigt dasselbe Muster wie bei Tom.","prueffrage":"Was liegt auf Lenas Schreibtisch, und wie passt das zu ihrem Urteil über sich selbst?","rueckmeldung":[{"option":0,"text":"Auffällig ist tatsächlich, dass Lenas Sammlung einseitig ist. Von einem ersten Artikel, an dem sie alles misst, steht im Szenario aber nichts. Sie stützt sich auf ihre Innenschau, nicht auf einen Ausgangspunkt."},{"option":1,"text":"Mit Blick auf Toms Einseitigkeit wirkt ein Vergleich mit anderen naheliegend. Lena äußert sich aber nur über Tom und sich selbst, nicht über eine Mehrheit der Kollegen. Eine Fehleinschätzung dessen, was andere denken, ist hier nicht zu erkennen."},{"option":3,"text":"Dass Lena nur Stützendes sammelt und ihre Position nicht weiter prüft, stimmt. Sie beruft sich aber auf keine Fachleute, sondern auf ihr eigenes Urteil nach der Innenschau. Ein Autoritätsargument liegt deshalb nicht vor."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"37406884a76ed521"}},{"id":"qx-b2-053","clusterId":"B","werkstueckRef":"B.30","stufe":1,"question":"Warum ist Rot im nächsten Spiel nicht wahrscheinlicher als im ersten Spiel des Abends?","scenario":"Ein Freund erzählt dir: „Im Kasino ist die Roulettekugel gestern zwanzigmal hintereinander auf Schwarz gefallen. Ich setze jetzt alles auf Rot, nach so einer Serie muss Rot einfach kommen.“ Der Tisch ist unauffällig und funktioniert einwandfrei.","options":["Der Tisch hat eine Neigung: Wer zwanzigmal Schwarz erlebt, hat es vermutlich mit einem ungleichen Tisch zu tun, der Schwarz bevorzugt.","Die Serie hat eine Eigendynamik: Eine Glückssträhne für Schwarz hält erfahrungsgemäß an, deshalb steigt die Chance auf Rot nicht.","Der Ausgleich braucht Zeit: Das Gesetz der großen Zahlen gleicht die Serie erst über sehr viele Spiele aus, nicht schon im nächsten Spiel.","Die Kugel hat kein Gedächtnis: Bei unabhängigen Zufallsereignissen ist die Chance in jedem Spiel dieselbe, was zuvor auch fiel."],"correctIndex":3,"explanation":"Jedes Spiel ist ein neuer, unabhängiger Wurf. Die Kugel weiß nicht, was vorher gefallen ist, also bleibt die Chance auf Rot unverändert. Auch das Gesetz der großen Zahlen gleicht nichts aus, es verdünnt frühe Abweichungen nur: Über Tausende Spiele fällt eine frühe Serie immer weniger ins Gewicht, ohne dass der Zufall etwas nachholen müsste. Wer nach einer Serie auf die Gegenseite setzt, begeht den Spielerfehlschluss. Die Frage, die ihn entlarvt: Weiß das Ding, das hier „würfelt“, was vorher passiert ist? Wenn nicht, ist der nächste Wurf ein erster Wurf. Ein ungleicher Tisch klingt nach einer natürlichen Erklärung, scheitert aber daran, dass der Tisch laut Szenario einwandfrei funktioniert. Eine Glückssträhne mit Eigendynamik gibt es bei unabhängigen Würfen nicht, die Kugel „läuft“ nicht. Und einen Ausgleich, auch einen langsamen, gibt es nicht: Das Gesetz der großen Zahlen verdünnt die Serie nur.","coreRule":"⚡ Zufall gleicht nichts aus: Münze, Kugel und Würfel haben kein Gedächtnis.","beleg":"Werkstück B.30 (Eingangsszene; Kernidee; Analyse); Fn. gl-b-montecarlo (Huff 1959; Zahl nicht durch Kasinoprotokolle belegt); Fn. gl-b-tversky (Tversky/Kahneman 1971, S. 105–106)","status":"entwurf","kurz":"Jedes Spiel ist ein neuer, unabhängiger Wurf, und die Kugel weiß nicht, was zuvor fiel. Der Denkfehler: Eine Serie erzeugt Druck zum Ausgleich, doch das Gesetz der großen Zahlen verdünnt frühe Abweichungen nur.","prueffrage":"Wie viele rote und wie viele schwarze Fächer hat der Kessel vor dem ersten Spiel des Abends, und wie viele nach der Serie?","rueckmeldung":[{"option":0,"text":"Ein ungleicher Tisch wäre bei so einer Serie tatsächlich eine denkbare Erklärung. Das Szenario nennt den Tisch aber ausdrücklich unauffällig und einwandfrei, deshalb bleibt die Chance auf Rot bei jedem Spiel gleich."},{"option":1,"text":"Dass Rot nicht wahrscheinlicher wird, stimmt, die Begründung aber nicht: Eine Strähne mit Eigendynamik gibt es bei unabhängigen Würfen nicht. Schwarz ist genauso wenig „heiß“ wie Rot „fällig“, jeder Wurf beginnt neu."},{"option":2,"text":"Dass sich nichts schon im nächsten Spiel ausgleicht, stimmt. Die Annahme dahinter trägt jedoch nicht: Das Gesetz der großen Zahlen holt nichts nach, es verdünnt die frühe Serie nur, je mehr Spiele dazukommen."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ceb82f64376af640"}},{"id":"qx-b2-054","clusterId":"B","werkstueckRef":"B.30","stufe":2,"question":"Was ist an ihrem Vorgehen fehlerhaft?","scenario":"Eine Kreditprüferin hat drei Anträge hintereinander bewilligt. Beim vierten Antrag, der den anderen vom Risiko her gleicht, will sie ablehnen – „nur um nicht immer dasselbe zu entscheiden“.","options":["Sie behandelt die Reihe der Entscheidungen so, als müsse sie sich ausgleichen, obwohl jeder Antrag für sich zu beurteilen ist.","Sie schließt aus drei bewilligten Anträgen auf die Qualität künftiger Antragsteller, obwohl drei Fälle eine zu kleine Stichprobe sind.","Sie lässt sich von persönlichen Merkmalen der Antragsteller leiten, obwohl allein das Ausfallrisiko über die Bewilligung entscheiden sollte.","Sie verlässt sich beim vierten Antrag auf ihr Gefühl statt auf die Kennzahlen, obwohl Kredite nach berechnetem Risiko zu beurteilen sind."],"correctIndex":0,"explanation":"Jeder Antrag ist für sich zu bewerten; die vorherigen Entscheidungen sagen nichts über den nächsten Fall. Wer nach einer Serie das Gegenteil wählt, damit sich die Reihe „ausgleicht“, unterliegt dem Spielerfehlschluss: Er unterstellt einem Ablauf ohne Gedächtnis einen Ausgleichsdrang. Das ist kein Randphänomen: Chen, Moskowitz und Shue (2016) werteten über 150.000 Asylentscheidungen, rund 1,5 Millionen Schiedsrichter-Entscheidungen und gut 9.000 Kreditprüfungen aus einem Feldexperiment aus. Asylrichter, Kreditprüfer und Baseball-Schiedsrichter schwenkten nach einer oder mehreren gleichartigen Entscheidungen um einige Prozentpunkte häufiger „um“, und zwar umso öfter, je länger die Serie war. Ein Antrag verdient eine eigene Prüfung. Die Entscheidungen davor sind kein Argument. Die anderen Gedanken sind für sich bedenkenswert, treffen hier aber nicht zu: Die Prüferin schließt nichts über künftige Antragsteller, sie will nur die Reihe auflockern. Von persönlichen Merkmalen ist nicht die Rede, der Antrag gleicht den anderen vom Risiko her. Und ein Bauchgefühl gegen die Kennzahlen wird nicht erwähnt, ihr genannter Grund ist die Reihe selbst.","coreRule":"⚡ Jeder Fall beginnt neu: Die Entscheidung davor darf die Entscheidung jetzt nicht färben.","beleg":"Werkstück B.30 (Anwendung: Urteile unter Serien; Zahlen und Befund laut Buchtext); Fn. gl-b-chen (Chen/Moskowitz/Shue 2016, QJE 131(3), S. 1181–1242)","status":"entwurf","kurz":"Jeder Antrag ist für sich zu bewerten, denn die früheren Entscheidungen sagen nichts über den nächsten Fall. Wer nach einer Serie das Gegenteil wählt, damit sich die Reihe „ausgleicht“, unterstellt einem Ablauf ohne Gedächtnis einen Ausgleichsdrang.","prueffrage":"Worin unterscheidet sich der vierte Antrag vom Risiko her von den drei bereits bewilligten?","rueckmeldung":[{"option":1,"text":"Drei Fälle sind tatsächlich wenig, und mit kleinen Stichproben ist Vorsicht angebracht. Die Prüferin schließt aber gar nichts über künftige Antragsteller, sie will nur die Reihe auflockern."},{"option":2,"text":"Entscheiden sollte tatsächlich allein das Ausfallrisiko. Im Szenario ist aber von persönlichen Merkmalen nicht die Rede, der Antrag gleicht den anderen vom Risiko her. Ihr Grund liegt in der Reihe der Entscheidungen."},{"option":3,"text":"Kredite sollten nach berechnetem Risiko beurteilt werden. Von einem Bauchgefühl gegen die Kennzahlen steht hier aber nichts, ihr genannter Grund ist die Reihe selbst. Der Fehler liegt darin, was sie aus dieser Reihe macht."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Chen, D. L.; Moskowitz, T. J.; Shue, K. (2016): Decision-Making under the Gambler's Fallacy: Evidence from Asylum Judges, Loan Officers, and Baseball Umpires. NBER Working Paper 22026","oeffentlich":true,"url":"https://www.nber.org/papers/w22026","seite":"14, 27","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f188224742ccf90c"}},{"id":"qx-b2-055","clusterId":"B","werkstueckRef":"B.30","stufe":3,"question":"Wie beurteilst du den Einwand des Kollegen?","options":["Der Einwand trifft zu: Jonas’ Würfe sind so unabhängig wie die Läufe einer Roulettekugel, seine drei Treffer sagen also nichts über seinen nächsten Wurf.","Der Einwand greift zu kurz: Anders als eine Roulettekugel hat Jonas ein Gedächtnis, Form und Konzentration schwanken, die Serie kann also etwas aussagen.","Der Einwand trifft zu: Über ein ganzes Spiel gleichen sich Trefferserien wieder aus, nach drei Treffern ist bei Jonas also eher ein Fehlwurf zu erwarten.","Der Einwand greift zu kurz: Drei Treffer kündigen bei Spielern weitere Treffer an, während fünfmal Rot beim Roulette ein baldiges Ende der Serie ankündigt."],"correctIndex":1,"explanation":"Der Spielerfehlschluss gilt für unabhängige Zufallsereignisse: Eine Roulettekugel weiß nicht, was vorher geschah, also ist jeder Lauf ein erster Lauf. Jonas ist dagegen kein Zufallsgenerator, denn Menschen haben ein Gedächtnis, Kugeln nicht. Form und Konzentration können schwanken, sodass seine Serie etwas über den nächsten Wurf aussagen kann, aber nicht muss. Der Glaube an die „heiße Hand“ (eine Serie setzt sich fort) galt nach Gilovich, Vallone und Tversky (1985) lange als reiner Denkfehler. Neuere Analysen zeigen allerdings, dass es bei Menschen echte, messbare Formschwankungen geben kann; Miller und Sanjurjo (2018) korrigierten einen statistischen Verzerrungseffekt der älteren Analyse. Jonas’ Würfe mit den Läufen einer Kugel gleichzusetzen, klingt nüchtern, übersieht aber die entscheidende Frage: Hat das, was hier „würfelt“, ein Gedächtnis? Dass sich Serien über ein Spiel ausgleichen, trifft nicht zu, denn das Gesetz der großen Zahlen verdünnt Abweichungen nur, es gleicht sie nicht aus. Und dass Serien bei Spielern weitergehen und beim Roulette enden müssten, folgt weder für Kugeln noch für Spieler.","coreRule":"⚡ Prüfe zuerst, ob das, was die Serie erzeugt, ein Gedächtnis hat: Bei Roulettekugeln nie, bei Menschen kann eine Serie eine Ursache haben.","beleg":"Werkstück B.30 (Analyse); Fn. gl-b-hothand (Gilovich/Vallone/Tversky 1985, S. 295–314; Miller/Sanjurjo 2018, Econometrica 86(6), S. 2019–2047)","status":"entwurf","scenario":"Beim Spiel deiner Basketballmannschaft hat Jonas seine letzten drei Würfe getroffen. Trainerin Kaya sagt: „Gebt Jonas im nächsten Angriff den Ball. Wer gerade dreimal getroffen hat, trifft mit höherer Wahrscheinlichkeit auch den vierten.“ Ihr Kollege widerspricht: „Das ist derselbe Fehler wie im Casino, wo nach fünfmal Rot angeblich Schwarz fällig ist.“","kurz":"Eine Roulettekugel weiß nicht, was vorher geschah, ein Spieler schon: Form und Konzentration schwanken. Darum ist es ein Fehler, Jonas mit einer Kugel gleichzusetzen, denn seine Serie kann etwas über den nächsten Wurf aussagen, muss aber nicht.","prueffrage":"Hängt das, was hier „würfelt“, davon ab, was vorher passiert ist, oder fängt jeder Versuch von vorn an?","rueckmeldung":[{"option":0,"text":"Beim Roulette stimmt das, jeder Lauf beginnt von vorn. Jonas ist aber keine Kugel: Form und Konzentration schwanken, und seine Serie kann etwas aussagen, auch wenn sie es nicht muss."},{"option":2,"text":"Dass sich Abweichungen später „ausgleichen“, wirkt plausibel. Das Gesetz der großen Zahlen verdünnt sie aber nur, es gleicht sie nicht aus. Ein Fehlwurf ist deshalb nicht „fällig“; das wäre selbst der Spielerfehlschluss."},{"option":3,"text":"Dass der Einwand zu kurz greift, stimmt. Die Begründung trägt aber nicht: Weder endet beim Roulette eine Serie „fällig“, noch muss sie bei Spielern weitergehen. Bei Spielern kann sie etwas aussagen, bei Kugeln nichts."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Miller, J. B.; Sanjurjo, A.: Surprised by the Hot Hand Fallacy? A Truth in the Law of Small Numbers. arXiv:1902.01265 (Autorenfassung; Econometrica 86(6), 2018, 2019–2047)","oeffentlich":true,"url":"https://arxiv.org/abs/1902.01265","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gilovich, T.; Vallone, R.; Tversky, A. (1985): The hot hand in basketball: On the misperception of random sequences. Cognitive Psychology 17(3), 295–314","oeffentlich":false,"doi":"10.1016/0010-0285(85)90010-6"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ec536927e200f36a"}},{"id":"qx-b2-056","clusterId":"B","werkstueckRef":"B.30","stufe":4,"question":"Wie lässt sich die Beobachtung am besten erklären, ohne in den Spielerfehlschluss zu geraten?","scenario":"Nach einer ungewöhnlich schlechten Woche hat dein Fitnessarmband für die Folgewoche wieder normalere Werte gezeigt. Ein Bekannter sagt: „Das hat sich eben ausgeglichen. Die schlechte Woche musste durch eine bessere wettgemacht werden.“","options":["Extreme Werte sind selten, deshalb folgt auf einen Ausreißer meist ein normalerer Wert. Dafür muss nichts „ausgeglichen“ werden.","Auf eine Phase der Schwäche folgt meist eine Erholung des Körpers. Die schlechte Woche hat die normale Folgewoche also vorbereitet.","Wer seine Werte im Blick hat, verhält sich anders. Der schlechte Wert hat dich vermutlich in der Folgewoche zu mehr Bewegung angespornt.","Das Armband hat in der schlechten Woche vermutlich ungenau gemessen. Die Folgewoche zeigt deshalb wieder die tatsächlichen Werte."],"correctIndex":0,"explanation":"Die Beobachtung selbst stimmt: Extreme Werte werden tatsächlich oft von normaleren gefolgt. Aber nicht, weil der Zufall etwas ausgleicht, sondern weil Extremwerte selten sind. Der Spielerfehlschluss dagegen unterstellt, dass eine Abweichung aktiv „ausgeglichen“ werden müsse. Das Gesetz der großen Zahlen gleicht aber nichts aus, es verdünnt Abweichungen nur: Frühe Ausreißer fallen immer weniger ins Gewicht, je mehr normale Werte dazukommen. Eine bessere Folgewoche ist also nicht „fällig“, sie ist einfach der wahrscheinlichere Normalfall.","coreRule":"⚡ Auf Extremes folgt oft Normales, aber nicht, weil der Zufall etwas schuldig wäre.","beleg":"Werkstück B.30 (Verbindungen: Nicht zu verwechseln mit Regression zur Mitte; Analyse)","status":"entwurf","kurz":"Extreme Werte sind selten, darum folgt auf einen Ausreißer meist ein normalerer Wert. Der Denkfehler liegt darin, aus „wahrscheinlicher Normalfall“ ein „fälliger Ausgleich“ zu machen. Nichts muss wettgemacht werden.","prueffrage":"Wie oft hat das Armband in früheren Wochen so schlechte Werte gezeigt, und wie oft normale?","rueckmeldung":[{"option":1,"text":"Erholung nach Schwäche kommt vor und klingt vernünftig. Hier steht aber nichts davon, dass die schlechte Woche eine Erholungsphase war. Und „vorbereitet“ klingt wie ein Ausgleich, genau die Vorstellung, die den Spielerfehlschluss ausmacht."},{"option":2,"text":"Dass der Blick aufs Armband das Verhalten ändert, ist im Einzelfall denkbar. Das Szenario erwähnt davon aber nichts, die Erklärung stützt sich auf eine bloße Vermutung. Normalere Werte nach einem Ausreißer ergeben sich auch ohne eine solche Annahme."},{"option":3,"text":"Ein ungenaues Gerät ist möglich, doch es gibt hier keinen Hinweis darauf. Ungewöhnliche Werte allein beweisen keinen Messfehler. Die Annahme erklärt den Ausreißer weg, statt zu zeigen, warum auf Extremwerte meist normalere folgen."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Regression“, „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barnett, A. G.; van der Pols, J. C.; Dobson, A. J. (2005): Regression to the mean: what it is and how to deal with it. International Journal of Epidemiology 34(1), 215–220","oeffentlich":false,"doi":"10.1093/ije/dyh299"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8b6385bb55ff2a20"}},{"id":"qx-b2-057","clusterId":"B","werkstueckRef":"B.31","stufe":1,"question":"Welche Beobachtung würde die Behauptung der Kollegin am stärksten widerlegen?","options":["Die Jugendlichen bevorzugen beim Verteilen die eigene Gruppe, obwohl es weder Wettkampf noch Streit gab und die Einteilung zufällig war.","Die Jugendlichen bevorzugen beim Verteilen die eigene Gruppe stärker, nachdem sie in einem Wettkampf um einen Preis gegeneinander angetreten sind.","Die Jugendlichen verteilen mehr an Mitschüler, die sie persönlich mögen, ganz gleich in welcher Gruppe diese sind, obwohl die Einteilung zufällig war.","Die Jugendlichen verteilen das Geld gleichmäßig auf beide Gruppen, wenn die Einteilung per Münzwurf erfolgt und es weder Wettkampf noch Streit gab."],"correctIndex":0,"explanation":"Die Behauptung sagt: Ohne Konkurrenz und ohne Streitgeschichte entsteht keine Gruppenbevorzugung. Am stärksten widerlegt sie ein Fall, in dem beides fehlt, die Einteilung rein zufällig ist und die eigene Gruppe trotzdem bevorzugt wird; ähnlich war der Versuch von Tajfel mit britischen Schuljungen angelegt (Einteilung angeblich nach Bildgeschmack, tatsächlich zufällig), und in einem Folgeversuch blieb die Bevorzugung auch bei offen per Münzwurf gebildeten Gruppen bestehen, wenn auch schwächer. Wer mehr an Mitschüler gibt, die er persönlich mag, kann damit einer Beziehung folgen statt der Gruppe; über Konkurrenz und Streit sagt das nichts.","coreRule":"⚡ Wer behauptet, eine Ursache sei nötig, wird widerlegt durch einen Fall, in dem sie fehlt und die Wirkung trotzdem eintritt. Schon ein bloßes Etikett kann „wir“ gegen „die“ erzeugen.","beleg":"Werkstück B.31 (Eingangsszene); Fn. gl-b-tajfel (Tajfel 1970; Tajfel u. a. 1971; Billig/Tajfel 1973, S. 28 f.); Anmerkung zu gl-b-tajfel (Münzwurf-Bedingung im Folgeversuch)","status":"entwurf","scenario":"Eine Kollegin sagt: „Gruppenbevorzugung entsteht erst, wenn Gruppen um knappe Ressourcen konkurrieren und es eine Vorgeschichte von Streit gibt.“ In einem Versuch werden Jugendliche, die sich aus der Schule kennen, zufällig in zwei Gruppen eingeteilt, etwa per Münzwurf. Sie wissen nicht, wer sonst zu ihrer Gruppe gehört, und verteilen Geld an anonyme Empfänger beider Gruppen.","quote":"","quoteLabel":"","kurz":"Widerlegt wird die Behauptung nur durch einen Fall, in dem Konkurrenz und Streitgeschichte fehlen und die eigene Gruppe trotzdem bevorzugt wird. Beobachtungen mit Wettkampf, Sympathie oder Gleichverteilung betreffen diese Bedingung nicht oder bestätigen sie sogar.","prueffrage":"Unter welchen Umständen würde die Kollegin selbst gar keine Bevorzugung der eigenen Gruppe erwarten?","rueckmeldung":[{"option":1,"text":"Dass Wettkampf die Bevorzugung verstärkt, wirkt wie ein starkes Ergebnis. Es passt aber zur Behauptung: Konkurrenz soll ja Gruppenbevorzugung hervorbringen. Ob sie auch ohne Konkurrenz entsteht, sagt diese Beobachtung nicht."},{"option":2,"text":"Wer Gemochten mehr gibt, zeigt etwas Reales: Beziehungen zählen. Das folgt aber der Sympathie, nicht der Gruppe, und sagt nichts darüber, ob ohne Konkurrenz und Streit Gruppenbevorzugung entsteht."},{"option":3,"text":"Gleichmäßiges Verteilen ohne Wettkampf und Streit wirkt wie ein sauberer Test. Es entspricht aber genau dem, was die Kollegin vorhersagt: ohne Konkurrenz und Streitgeschichte keine Bevorzugung. Das bestätigt ihre Behauptung, statt sie zu widerlegen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict. In: Austin, W. G.; Worchel, S. (Hg.): The Social Psychology of Intergroup Relations (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"},{"typ":"doi","kurz":"Billig, M.; Tajfel, H. (1973): Social categorization and similarity in intergroup behaviour. European Journal of Social Psychology 3(1)","oeffentlich":false,"doi":"10.1002/ejsp.2420030103","seite":"27–29, 34, 39"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"99–102"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"108571012ff3ec6e"}},{"id":"qx-b2-058","clusterId":"B","werkstueckRef":"B.31","stufe":3,"question":"Ein Kommentator behauptet: „Das Experiment beweist es: Sobald Menschen in ‚wir‘ und ‚die‘ eingeteilt werden, ist der Weg zur Entmenschlichung vorgezeichnet. Wer Gruppen bildet, bekommt am Ende Feindbilder.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er springt von der milden Bevorzugung der eigenen Gruppe auf eine extreme Folge, ohne zu zeigen, dass die bloße Einteilung diesen Weg allein zurücklegt.","Er schließt von der Abfolge „erst Einteilung, dann Bevorzugung“ auf eine Ursache, obwohl der Bildgeschmack der Jugendlichen die Bevorzugung genauso erklären könnte.","Er übersieht, dass die Jugendlichen mit ihrer Verteilung vor allem den eigenen Gewinn steigern wollten, sodass die Bevorzugung der Gruppe bloß Eigennutz zeigt.","Er verwirft den Versuch, weil die Forschenden die Jugendlichen mit dem angeblichen Bildgeschmack getäuscht hätten, statt den Befund zu prüfen (Ad-hominem-Argument)."],"correctIndex":0,"explanation":"Das Experiment zeigt eine milde, messbare Bevorzugung der eigenen Gruppe bei bloßer, sogar zufälliger Einteilung. Zwischen diesem Befund und der Entmenschlichung, bei der der Fremdgruppe die Menschlichkeit selbst abgesprochen wird, liegt ein weiter Weg, den die bloße Einteilung allein nicht zurücklegt. Den Weg dorthin treibt dieselbe Gruppenbindung unter wachsendem Druck: Bedrohung, Konkurrenz um knappe Ressourcen und eine Führung, die die Distanz zwischen „wir“ und „die“ vergrößert. Zudem lässt sich der Ursprung der Gruppenbindung auch ohne Feindschaft erklären: Eine mögliche Erklärung sieht in ihr eine Gemeinschaft gegenseitigen Vertrauens, die Verbündeten Schutz und geteilte Nahrung brachte – eine Hypothese, kein Messergebnis. Und auch Entmenschlichung ist kein Entweder-oder, sondern hat Stufen von subtil bis offen. Der Kommentator schließt also von einem Anfangsbefund auf ein Endergebnis, ohne die Zwischenstrecke zu belegen.","coreRule":"⚡ Wer von einem milden Befund auf eine extreme Folge schließt, muss den Weg dazwischen belegen: Wir-Gefühl ist noch keine Feindschaft.","beleg":"Werkstück B.31 (Kontext & Tiefe; Kipppunkt); Fn. gl-b-brewer (Brewer 1999, S. 432–434); Fn. gl-b-kteily (Kteily u. a. 2015)","status":"entwurf","scenario":"In einem Experiment werden Jugendliche per Zufall in zwei Gruppen eingeteilt, angeblich nach ihrem Bildgeschmack. Sie verteilen anschließend kleine Geldbeträge an anonyme Mitglieder beider Gruppen und bevorzugen dabei systematisch die eigene Gruppe, teils sogar auf Kosten des absoluten Gewinns der eigenen Gruppe, solange der Abstand zur anderen Gruppe wächst.","kurz":"Das Experiment zeigt eine milde Bevorzugung der eigenen Gruppe. Der Weg zur Entmenschlichung braucht mehr als die bloße Einteilung, etwa Bedrohung, Konkurrenz und Führung; der Kommentator überspringt diese Zwischenstrecke.","prueffrage":"Was taten die Jugendlichen im Experiment gegenüber der anderen Gruppe, und was davon wurde gemessen?","rueckmeldung":[{"option":1,"text":"Eine Abfolge allein beweist tatsächlich keine Ursache. Hier greift das aber nicht: Die Jugendlichen wurden per Zufall eingeteilt, der Bildgeschmack war nur ein Vorwand und kann die Bevorzugung nicht erklären."},{"option":2,"text":"Eigennutz wäre eine naheliegende Deutung. Doch teils verzichteten die Jugendlichen sogar auf absoluten Gewinn der eigenen Gruppe, um den Abstand zu vergrößern. Reiner Eigennutz würde das nicht tun."},{"option":3,"text":"Dass die Jugendlichen über den Bildgeschmack getäuscht wurden, gehört zur Anlage, widerlegt aber den Befund nicht. Der Kommentator greift zudem niemanden an, er beruft sich auf den Versuch und überdehnt dessen Aussage."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kteily, N.; Bruneau, E.; Waytz, A.; Cotterill, S. (2015): The Ascent of Man: Theoretical and Empirical Evidence for Blatant Dehumanization. JPSP 109(5)","oeffentlich":false,"doi":"10.1037/pspp0000048"},{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9463677d249843f1"}},{"id":"qx-b2-059","clusterId":"B","werkstueckRef":"B.31","stufe":4,"question":"Was zeigt diese Beobachtung am ehesten über den Charakter der Debatte?","scenario":"In einer Debatte über eine Klimamaßnahme werden Abweichler in der eigenen Gruppe heftiger angegriffen als die eigentliche Gegenseite. Die Gegenseite wird nur noch als einheitliche Masse beschrieben.","options":["Die Gruppe nimmt Widerspruch auch im Inneren ernst, und die Debatte ist dadurch sachlicher geworden.","Die Gruppe prüft Abweichler strenger als externe Gegner, weil ihr die Sache besonders wichtig ist.","Die Gruppengrenze ist wichtiger geworden als die Sache selbst, und die Gegenseite gilt nur noch als Masse.","Die Gegenseite hat in der Sache recht, weil Gruppen auf unbequeme Wahrheiten besonders heftig reagieren."],"correctIndex":2,"explanation":"Wenn Abweichler in der eigenen Gruppe härter angegriffen werden als die eigentliche Gegenseite, geht es erkennbar nicht mehr um die Klimamaßnahme, sondern um Loyalität: Wer abweicht, stellt die Zugehörigkeit infrage. Dazu passt, dass die Gegenseite nur noch als einheitliche Masse ohne eigene Stimmen beschrieben wird. Das ist ein typisches Zeichen dafür, dass die Gruppenzugehörigkeit die Sachfrage überlagert: Wichtiger als die Argumente wird, was die Zugehörigkeit zur eigenen Gruppe signalisiert. Eine einfache Prüffrage: Würdest du dasselbe Argument genauso bewerten, wenn es aus der eigenen Gruppe käme, und ihm genauso widersprechen, wenn ein Mitglied deiner Gruppe es verträte?","coreRule":"⚡ Wo Zustimmung vor allem Zugehörigkeit signalisiert, verliert das Argument sein Gewicht.","quote":"","quoteLabel":"","beleg":"Werkstück B.31 (Red Flags; Anwendung: Politische Polarisierung; Anti-Denkmuster)","status":"entwurf","kurz":"Wer Abweichler härter angreift als die Gegenseite und diese nur noch als Masse beschreibt, kämpft erkennbar um Zugehörigkeit statt um die Klimamaßnahme. Der naheliegende Fehler ist, Härte für besondere Sachstrenge zu halten.","prueffrage":"Wen trifft die schärfste Kritik: Menschen mit anderen Argumenten oder Menschen aus den eigenen Reihen?","rueckmeldung":[{"option":0,"text":"Kritik von innen kann ein Zeichen offener Debatte sein. Hier werden Abweichler aber heftig angegriffen statt angehört, und die Gegenseite kommt nur als Masse vor. Das spricht nicht für mehr Sachlichkeit."},{"option":1,"text":"Wem eine Sache wichtig ist, der prüft genau, das wirkt plausibel. Doch wer wirklich die Sache prüft, nimmt sich die Gegenseite mindestens so genau vor wie Abweichler und beschreibt sie nicht nur als einheitliche Masse."},{"option":3,"text":"Heftige Reaktionen sagen etwas über die Gruppe, nicht darüber, wer in der Sache recht hat. Zudem treffen sie hier vor allem Abweichler aus den eigenen Reihen und nicht die Gegenseite."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan: A Meta-Analytic Comparison of Partisan Bias in Liberals and Conservatives. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3b5b3cae3558bba0"}},{"id":"qx-b2-060","clusterId":"B","werkstueckRef":"B.31","stufe":2,"question":"Welche Erklärung für diese Wahl ist am sparsamsten und erklärt zugleich, warum die Verteilung mit weniger Punkten für die eigene Gruppe gewählt wird?","scenario":"Zwei Gruppen von Schülern wurden eben erst zufällig eingeteilt, ohne Wettkampf und ohne vorherigen Streit; niemand weiß, wer sonst zur eigenen Gruppe gehört. Nun dürfen sie Punkte an anonyme Empfänger beider Gruppen verteilen, die später in echtes Geld umgetauscht werden. Viele wählen eine Verteilung, bei der die eigene Gruppe 7 Punkte und die andere 1 Punkt bekommt, statt einer Verteilung mit 10 Punkten für die eigene und 12 für die andere Gruppe. Dabei verteilen sie nie an sich selbst.","options":["Die Gruppe ist ihnen schon so wichtig, dass sie vor allem den Abstand zur anderen Gruppe vergrößern wollen, auch wenn die eigene Gruppe dabei absolut weniger erhält.","Sie wollen den Gewinn der eigenen Gruppe so groß wie möglich machen, weil mehr Punkte später auch mehr Geld bedeuten (Gewinnmaximierung).","Sie sehen in der anderen Gruppe einen Konkurrenten um knappe Mittel und wollen ihr zuvorkommen, bevor sie selbst benachteiligt werden (Gruppenkonflikt).","Sie folgen einer Reziprozitätsnorm: Wer der eigenen Gruppe viel gibt, erhält später eine Gegenleistung von deren Mitgliedern."],"correctIndex":0,"explanation":"Wenn jemand die Verteilung mit weniger Punkten für die eigene Gruppe wählt, nur weil der Abstand größer ist, geht es nicht ums Gewinnen, sondern ums Besser-Dastehen. Das passt dazu, dass ein Teil des Selbstwerts an die Gruppe gekoppelt ist: Es genügt nicht, dass es „uns“ gut geht, „wir“ sollen mehr haben als „die“. Dass schon eine zufällige Einteilung ausreicht, ist der Kern des Befunds: Das Gruppenetikett allein genügt, damit der Vergleich mit der anderen Gruppe wichtig wird. Die anderen Erklärungen klingen vernünftig, passen aber nicht zur Wahl: Wer den Gewinn der eigenen Gruppe maximieren wollte, hätte 10 statt 7 Punkte gewählt. Ein Konkurrenzdenken um knappe Mittel setzt einen Wettkampf voraus, den es hier nicht gab. Und Gegenleistung zu erwarten ergibt keinen Sinn, wenn niemand weiß, wer außer ihm selbst zur Gruppe gehört.","coreRule":"⚡ Wenn jemand lieber weniger für alle will, solange „wir“ mehr haben als „die“, geht es nicht um Gewinn, sondern um den Vergleich.","beleg":"Werkstück B.31 (Kernidee; Kontext & Tiefe: Sozialer Vergleich & positive Distinktheit)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer 7 zu 1 statt 10 zu 12 wählt, will nicht möglichst viel gewinnen, sondern besser dastehen als die andere Gruppe. Naheliegend wäre Eigennutz, doch der hätte die 10 Punkte gewählt; hier zählt der Abstand.","prueffrage":"Was haben die Schüler in der Verteilung für ihre eigene Gruppe verloren, und was haben sie dafür bekommen?","rueckmeldung":[{"option":1,"text":"Dass aus den Punkten später echtes Geld wird, spricht auf den ersten Blick für Eigennutz. Wer aber den Ertrag der eigenen Gruppe maximieren wollte, hätte die 10 Punkte gewählt statt der 7, und die Gruppe geht hier sogar mit weniger aus der Verteilung."},{"option":2,"text":"Konkurrenz um knappe Mittel erklärt oft Streit zwischen Gruppen. Hier gab es aber weder Wettkampf noch Vorgeschichte, die Gruppen wurden eben erst zufällig gebildet, und niemand muss sich Mittel gegen die andere Seite sichern."},{"option":3,"text":"Gegenseitigkeit kann Verhalten sonst tatsächlich steuern. Eine Gegenleistung setzt aber voraus, dass man weiß, wer sie erbringen soll; hier kennt niemand die anderen Gruppenmitglieder. Und sie würde nicht erklären, warum die eigene Gruppe mit 7 statt 10 Punkten weniger bekommt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–42","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"101–102"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"51005926453848ad"}},{"id":"qx-b2-061","clusterId":"B","werkstueckRef":"B.32","stufe":1,"question":"Welche Annahme steckt hinter dieser Einschätzung, und warum ist sie riskant?","options":["Er unterstellt, die Regierung dort sehe ihre Lage wie er und halte ohne Feind ebenfalls keine Atomwaffe für nötig, und ersetzt so fehlendes Wissen durch das eigene Bild.","Er schließt aus der Fähigkeit des Landes, Atomwaffen zu bauen, auf dessen Absicht dazu, und verwechselt so Können mit Wollen, ohne die Ziele der Regierung zu prüfen.","Er unterstellt, die Haltung der Regierung gelte für jeden Bürger des Landes, und übergeht so, dass viele Menschen dort anders über Atomwaffen denken könnten.","Er unterstellt, ein Land, das er kaum kennt, sei von Natur aus gefährlich, und überschätzt so die Gefahr, die von seinem Atomprogramm ausgeht."],"correctIndex":0,"explanation":"Die Einschätzung beantwortet nicht die Frage, wie die fremde Regierung ihre Lage sieht, sondern eine andere: Was würde ich an ihrer Stelle wollen? Sie stützt sich auf nichts, was von der anderen Seite stammt, weder Äußerungen noch Kenntnis ihrer Lage. Wo Wissen fehlt, setzt man unbemerkt das einzige Modell eines Geistes ein, das man von innen kennt: sich selbst. Das nennt man Spiegelbild-Denken (Mirror-Imaging). So wurde 1977 ein mutmaßliches Atomtestgelände in Südafrika von vielen Analysten abgetan, mit genau diesem Argument. Als Notbehelf lässt sich der Blick in den Spiegel manchmal nicht vermeiden, aber ein solches Urteil verdient wenig Vertrauen. Besser prüft man, ob die andere Seite ihre Lage selbst beschrieben hat, und zieht Menschen hinzu, die sie aus eigener Anschauung kennen. Die anderen Fehler sind real, kommen hier aber nicht vor: Fähigkeit und Absicht zu verwechseln würde zum Schluss führen, das Land wolle die Waffe, der Analyst schließt aber das Gegenteil. Von den Bürgern des Landes ist nirgends die Rede, er spricht von der Regierung. Und eine Überschätzung der Gefahr zeigt sich nicht, er unterschätzt sie eher.","coreRule":"⚡ Wo Wissen über den anderen fehlt, setzt man sich selbst ein, ohne es zu merken. Frag daher: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte?","beleg":"Werkstück B.32 (Kernidee; Analyse); Fn. gl-b-heuer (Heuer 1999, Psychology of Intelligence Analysis, S. 70)","status":"entwurf","scenario":"Ein Analyst soll einschätzen, ob ein ihm kaum bekannter Staat Atomwaffen anstrebt. Er schreibt: „Das Land hat keinen Feind, gegen den sich eine Atomwaffe wirksam einsetzen ließe. Also will es keine. An seiner Stelle würde ich auch darauf verzichten.“ Niemand im Team kennt das Land aus eigener Anschauung, und es liegen keine Äußerungen der dortigen Regierung vor.","kurz":"Der Analyst fragt nicht, wie die fremde Regierung ihre Lage sieht, sondern was er an ihrer Stelle wollte, und stützt sich auf nichts von ihrer Seite. Wo Wissen fehlt, setzt man leicht sich selbst als Modell ein (Spiegelbild-Denken), und dann trägt das Urteil wenig.","prueffrage":"Was von dem, worauf sich die Einschätzung stützt, stammt tatsächlich von der Regierung des Landes selbst?","rueckmeldung":[{"option":1,"text":"Können und Wollen auseinanderzuhalten ist ein wichtiger Gedanke, er trifft hier aber nicht zu. Von Fähigkeiten des Landes ist nirgends die Rede, und der Analyst schließt gerade nicht auf eine Absicht zum Bau, sondern auf deren Fehlen."},{"option":2,"text":"Von der Regierung auf alle Bürger zu schließen wäre tatsächlich unzulässig. Der Analyst spricht aber nur über die Regierung, die Bürger kommen in seiner Einschätzung gar nicht vor. Sein Problem liegt woanders: im Maßstab, den er für die Regierung anlegt."},{"option":3,"text":"Ein Land, das man kaum kennt, kann tatsächlich Misstrauen wecken. Der Analyst schließt aber das Gegenteil: Er hält das Land für harmlos und unterschätzt die Gefahr damit eher, als dass er sie überschätzt."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9ccec9af2417f24b"}},{"id":"qx-b2-062","clusterId":"B","werkstueckRef":"B.32","stufe":3,"question":"Was ist der entscheidende Fehler an diesem Vorgehen?","options":["Die vorläufige Annahme des Beraters wurde zur gesicherten Ausgangslage der Sanktionsentscheidung, obwohl sie nur eine Wissenslücke überbrücken sollte.","Der Entwurf übernimmt nur Hinweise auf einen Truppenabzug und lässt Gegenhinweise weg, sodass ein Bestätigungsfehler die Sanktionsentscheidung prägt.","Der Entwurf prüft nicht, wie die Sanktionen die Nachbarregierung und die eigene Seite treffen, obwohl man Nebenfolgen vor jeder solchen Entscheidung abschätzen sollte.","Der Entwurf beruft sich allein auf das Wort des Beraters und prüft seine Aussage nicht, sodass ein Autoritätsargument die Sanktionsentscheidung trägt."],"correctIndex":0,"explanation":"Die eigene Sicht ist das einzige Modell eines Geistes, das wir von innen kennen. Als vorläufiger Notbehelf bei fehlendem Wissen ist sie kaum zu vermeiden, solange allen klar bleibt, dass es nur eine Vermutung ist. Der Fehler liegt im Wechsel von der Vermutung zur Gewissheit: Aus „So würden wir handeln“ wurde „So wird sie handeln, alles andere wäre unvernünftig“, und das Wort „unvernünftig“ misst das Gegenüber an den eigenen Maßstäben. Wo niemand die andere Seite kennt, trägt diese Annahme allein keine folgenreiche Entscheidung. Dann hilft es, Fachleute hinzuzuziehen, die das Land kennen, oder die andere Seite mit ihren eigenen Worten zu Wort kommen zu lassen.","coreRule":"⚡ Ein Spiegel ist als Notbehelf erlaubt, solange du weißt, dass du in einen Spiegel blickst.","beleg":"Werkstück B.32 (Adaptives Talent; Kipppunkt; Anwendung & Relevanz: Fachleute von außen); Fn. gl-b-heuer (Heuer 1999, S. 70 f. und 181)","status":"entwurf","scenario":"In einer Lagebesprechung sagt ein Berater: „Über die Absichten der Nachbarregierung wissen wir wenig. Also nehmen wir vorläufig an, sie handelt so, wie wir es an ihrer Stelle täten.“ Drei Wochen später steht im Entwurf einer Sanktionsentscheidung als Ausgangslage: „Die Nachbarregierung wird ihre Truppen abziehen, denn alles andere wäre unvernünftig.“ Niemand im Raum kennt das Land aus eigener Anschauung.","kurz":"Eine Vermutung, die eine Wissenslücke überbrücken sollte, wurde im Entwurf zur Gewissheit. Aus „So würden wir handeln“ wurde „So wird sie handeln“, obwohl niemand das Land kennt und „unvernünftig“ nur die eigenen Maßstäbe anlegt.","prueffrage":"Welche neuen Erkenntnisse über das Nachbarland liegen zwischen der Lagebesprechung und dem Entwurf drei Wochen später?","rueckmeldung":[{"option":1,"text":"Gegenhinweise zu übergehen wäre ein echter Fehler, hier fehlen aber Belege überhaupt: Man wusste nach eigener Aussage wenig. Wo nichts einseitig ausgewählt wurde, trägt der Vorwurf nicht. Der Fehler liegt woanders."},{"option":2,"text":"Nebenfolgen vor einer Sanktionsentscheidung abzuschätzen ist grundsätzlich sinnvoll. Im Szenario ist davon aber nicht die Rede, und der Mangel liegt schon eine Stufe früher, in der Ausgangslage, auf der die Entscheidung aufbaut."},{"option":3,"text":"Der Berater berief sich auf keine Autorität, sondern nannte seine Annahme selbst ausdrücklich vorläufig. Die Gewissheit entstand erst im Entwurf, als aus der Vermutung eine feste Ausgangslage wurde."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7356fa39c66fabe8"}},{"id":"qx-b2-063","clusterId":"B","werkstueckRef":"B.32","stufe":4,"question":"Was ist die klügste Reaktion auf diesen Satz in einer Lageanalyse?","scenario":"In einer Lageanalyse zu einem fremden Land steht: „Das Vorgehen dieser Regierung ist völlig irrational und gegen ihre eigenen Interessen.“ Keiner der Autoren hat das Land je besucht, und die Regierung selbst kommt in der Analyse nicht zu Wort.","options":["Den Satz als Beleg nehmen, dass in der Regierung Gruppendenken herrscht, und die Analyse darauf stützen, dass Abweichler dort zum Schweigen gebracht werden.","Den Satz als Frage des Tons nehmen und „völlig irrational“ durch „schwer nachvollziehbar“ ersetzen, ohne die Einschätzung selbst zu ändern.","Den Satz als Behauptung nehmen, die man durch weitere Beispiele für das Verhalten der Regierung stützt, bis die Analyse belastbar ist.","Den Satz als Warnzeichen nehmen, dass womöglich eigene Werte und Denkrahmen übertragen wurden, und prüfen, wie die Regierung ihre Lage selbst sieht."],"correctIndex":3,"explanation":"Wenn das Verhalten einer fremden Regierung „irrational“ oder „gegen ihre eigenen Interessen“ wirkt, liegt der Fehler oft beim Beobachter: Er hat die eigenen Werte und Denkrahmen auf sie übertragen, statt die Logik der Lage so zu verstehen, wie sie sich ihr selbst darstellt. Wer nicht weiß, wie das Gegenüber denkt, setzt meist unbemerkt das einzige Modell eines Geistes ein, das er von innen kennt: sich selbst. Dass die Analyse keine Selbstauskunft der Regierung enthält und niemand das Land kennt, verstärkt den Verdacht. Das Etikett „irrational“ beendet die Erklärung, wo sie beginnen sollte. Die bessere Frage lautet: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte? Reden, Interviews und Programme der Regierung selbst sowie Fachleute, die das Land aus eigener Anschauung kennen, prüfen das. Die anderen Gedanken klingen vernünftig, passen aber nicht: Gruppendenken kann vorkommen, doch über das Innenleben der Regierung sagt der Satz nichts, es wäre eine unbelegte Zusatzannahme. Ein neutraleres Wort ändert nur den Ton, nicht den Denkfehler dahinter. Und weitere Beispiele für das Verhalten zeigen nur, was die Regierung tut, nicht, warum sie es aus ihrer Sicht tut.","coreRule":"⚡ „Irrational“ sagt oft mehr über den Beobachter als über den Beobachteten.","quote":"","quoteLabel":"","beleg":"Werkstück B.32 (Analyse; Red Flags; Anti-Denkmuster); Fn. gl-b-heuer (Heuer 1999, S. 33)","status":"entwurf","kurz":"Wirkt das Handeln einer fremden Regierung „irrational“, liegt der Fehler oft beim Beobachter, der eigene Werte und Denkrahmen überträgt. Besser ist es zu prüfen, wie die Regierung ihre Lage selbst sieht, statt nur einzusetzen, was man an ihrer Stelle täte.","prueffrage":"Auf welchen Quellen beruht das Urteil „irrational“, und wer von den Autoren war je in diesem Land?","rueckmeldung":[{"option":0,"text":"Gruppendenken ist in Regierungen durchaus möglich, und Abweichler könnten ausgegrenzt werden. Der Satz gibt dafür aber nichts her: Er beschreibt nur, wie das Vorgehen auf die Autoren wirkt. Die Analyse stünde auf einer unbelegten Zusatzannahme."},{"option":1,"text":"„Schwer nachvollziehbar“ klingt vorsichtiger und ist ehrlicher als „völlig irrational“. Doch die Einschätzung dahinter bleibt dieselbe, und sie beruht weiter auf eigenen Maßstäben statt auf der Sicht der Regierung. Der Ton ändert sich, die Lücke nicht."},{"option":2,"text":"Mehr Beispiele machen deutlicher, was die Regierung tut. Warum sie es aus ihrer eigenen Sicht tut, erklären sie nicht. Ohne diese Sicht bleibt „irrational“ ein Urteil, das nur häufiger wiederholt wird."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"33, 70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ec9dddf5d95c7ddd"}},{"id":"qx-b2-064","clusterId":"B","werkstueckRef":"B.32","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft, und was wäre der nächste sinnvolle Schritt?","scenario":"In einer Verhandlung stellt der andere Verband plötzlich eine Forderung, die deinem Team völlig unverständlich vorkommt. Eine Kollegin sagt: „Ich hätte an seiner Stelle nie so etwas verlangt. Er muss also bluffen und will uns nur unter Druck setzen.“ Ihr habt nie mit jemandem aus seinem Verband gesprochen, und in euren Unterlagen steht nichts darüber, wie er die eigene Lage beschreibt.","options":["Sie setzt das eigene Denken an die Stelle seines Denkens; sinnvoll wäre, zuerst herauszufinden, wie er seine eigene Lage und seine Ziele selbst beschreibt.","Sie sucht nur Hinweise, die die Vermutung stützen; sinnvoll wäre, die Vermutung als Hypothese zu formulieren und dafür Belege zu sammeln.","Sie hält die eigenen Ziele für moralisch besser als seine; sinnvoll wäre, die eigenen Ziele offen und ausführlich zu begründen.","Sie nimmt an, die Wahrheit liege in der Mitte zwischen beiden Positionen; sinnvoll wäre, sofort einen Kompromiss anzubieten."],"correctIndex":0,"explanation":"Die Kollegin beantwortet nicht die Frage, wie der andere seine Lage sieht, sondern eine andere: was sie selbst an seiner Stelle wollen würde. Das ist Spiegelbild-Denken. Die Frage „Warum würde ich so etwas tun?“ liefert eine Antwort über einen selbst, nicht über den anderen. Sie füllt eine Wissenslücke mit dem einzigen Modell eines Geistes, das sie von innen kennt: ihrem eigenen. Gerade weil niemand im Team die andere Seite aus eigener Anschauung kennt und ihre Sicht in den Unterlagen nirgends mit eigenen Worten vorkommt, ist die Schlussfolgerung „Bluff“ nur eine Vermutung und sollte nicht als Tatsache in die Verhandlung eingehen. Der nächste Schritt ist, die Sicht des anderen zu klären: über seine eigenen Worte, etwa eine Rede, ein Interview oder eine Beschreibung seiner Lage, und über Menschen, die seine Seite aus eigener Anschauung kennen. Mit dem Symmetrie-Trugschluss ist das nicht zu verwechseln: Dort liegt der Fehler in der Annahme, die Wahrheit liege in der Mitte zwischen zwei Positionen; hier darin, dass der andere als Spiegelbild von einem selbst gesehen wird. Ein sofortiges Kompromissangebot würde deshalb am eigentlichen Fehler vorbeigehen.","coreRule":"⚡ „Was würde ich tun?“ ist eine Frage über dich, nicht über den anderen.","beleg":"Werkstück B.32 (Anwendung: Verhandlung & Alltag; Anti-Denkmuster)","status":"entwurf","kurz":"Die Kollegin beantwortet nicht, wie der andere seine Lage sieht, sondern was sie selbst an seiner Stelle wollen würde. „Bluff“ ist damit nur eine Vermutung. Sinnvoll ist, zuerst seine eigene Sicht zu klären.","prueffrage":"Was hat der andere Verband selbst über seine Forderung gesagt, und wer im Team hat je mit jemandem von dort gesprochen?","rueckmeldung":[{"option":1,"text":"Dass „Bluff“ nur eine Vermutung ist, stimmt. Doch die Kollegin sucht gar keine Hinweise, sie schließt von sich auf ihn; und Belege nur für die eigene Vermutung zu sammeln, klärt nicht, wie er seine Lage sieht."},{"option":2,"text":"Die eigenen Ziele offen zu begründen, ist nützlich. Von einer moralischen Wertung ist in der Aussage aber gar nicht die Rede, und die Begründung klärt nichts darüber, wie der andere seine Lage sieht."},{"option":3,"text":"Ein Kompromiss klingt vernünftig, wenn zwei Positionen aufeinandertreffen. Hier fehlt aber erst das Wissen darüber, was der andere will. Der Fehler liegt im Blick auf ihn als Spiegelbild, nicht in einer Mitte-Annahme."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"68677764c81752d1"}}]`);export{t as n,n as t};